window.FORMS = [{"id": "aurelia", "file": "forms/aurelia.html", "title": "Aurelia", "layout": "Underline + Sliding Tab", "layout_key": "underline-sliding-tab", "palette": "Ink & Gold", "palette_key": "ink-gold", "blurb": "A members' concierge: floating-label fields, a gliding tab bar, gold sweeps in on button hover.", "n": 1, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Aurelia \u2014 Member Entrance</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;1,500&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --ink:#100d09;\n    --ink-2:#171209;\n    --gold-deep:#8a6a35;\n    --gold:#c9a24a;\n    --gold-bright:#e7c988;\n    --cream:#f3ead9;\n    --taupe:#9c8f78;\n    --hairline:rgba(231,201,136,0.16);\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--ink);\n    color:var(--cream);\n    font-family:'Inter', sans-serif;\n    -webkit-font-smoothing:antialiased;\n    min-height:100vh;\n    display:flex; align-items:center; justify-content:center;\n    padding:60px 28px;\n    position:relative;\n    overflow:hidden;\n  }\n\n  /* ---------- ambient background ---------- */\n  .glow{\n    position:fixed; border-radius:50%; filter:blur(120px); pointer-events:none; z-index:0;\n    background:radial-gradient(circle, var(--gold-deep), transparent 70%);\n    opacity:.22;\n  }\n  .glow-a{width:640px; height:640px; top:-220px; left:-160px; animation:drift-a 34s ease-in-out infinite;}\n  .glow-b{width:520px; height:520px; bottom:-200px; right:-140px; animation:drift-b 40s ease-in-out infinite;}\n  @keyframes drift-a{0%,100%{transform:translate(0,0);} 50%{transform:translate(60px,40px);}}\n  @keyframes drift-b{0%,100%{transform:translate(0,0);} 50%{transform:translate(-50px,-30px);}}\n\n  .grain{\n    position:fixed; inset:0; pointer-events:none; z-index:0; opacity:.05; mix-blend-mode:overlay;\n    background-image:radial-gradient(rgba(255,255,255,.9) 0.6px, transparent 0.6px);\n    background-size:3px 3px;\n  }\n\n  /* ---------- composition ---------- */\n  .stage{\n    position:relative; z-index:1; width:100%; max-width:400px;\n    opacity:0; transform:translateY(14px) scale(.98);\n    animation:reveal 1s cubic-bezier(.16,1,.3,1) forwards;\n  }\n  @keyframes reveal{ to{ opacity:1; transform:translateY(0) scale(1); } }\n\n  .mark{\n    display:flex; align-items:center; gap:14px; margin-bottom:38px;\n    opacity:0; animation:fadeIn .8s ease forwards; animation-delay:.15s;\n  }\n  .mark svg{ width:30px; height:30px; flex:none; }\n  .mark svg path{\n    stroke:var(--gold); stroke-width:1; fill:none;\n    stroke-dasharray:120; stroke-dashoffset:120;\n    animation:draw 1.4s cubic-bezier(.65,0,.35,1) forwards; animation-delay:.25s;\n  }\n  .mark .word{ font-family:'Cormorant Garamond', serif; font-size:19px; letter-spacing:.06em; color:var(--gold-bright); }\n\n  h1{\n    font-family:'Cormorant Garamond', serif; font-weight:500; font-size:38px; line-height:1.15;\n    margin-bottom:10px; max-width:320px;\n    opacity:0; animation:fadeUp .8s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.3s;\n  }\n  .sub{\n    font-size:14px; color:var(--taupe); margin-bottom:8px; max-width:300px; line-height:1.5;\n    opacity:0; animation:fadeUp .8s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.38s;\n  }\n  .rule{\n    height:1px; width:0; background:linear-gradient(90deg, var(--gold), transparent);\n    margin:26px 0 30px; animation:growRule 1s cubic-bezier(.65,0,.35,1) forwards; animation-delay:.5s;\n  }\n  @keyframes fadeIn{ to{ opacity:1; } }\n  @keyframes fadeUp{ to{ opacity:1; transform:none; } }\n  @keyframes growRule{ to{ width:100%; } }\n  h1, .sub{ transform:translateY(8px); }\n\n  /* ---------- tabs ---------- */\n  .tabs{\n    position:relative; display:flex; gap:28px; margin-bottom:34px; border-bottom:1px solid var(--hairline);\n    opacity:0; animation:fadeUp .7s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.58s;\n  }\n  .tabs button{\n    background:none; border:none; color:var(--taupe); font-family:'Inter', sans-serif; font-size:13px;\n    font-weight:500; letter-spacing:.02em; padding:0 0 14px; cursor:pointer; transition:color .3s ease;\n  }\n  .tabs button.active{ color:var(--gold-bright); }\n  .tab-indicator{\n    position:absolute; bottom:-1px; height:1.5px; background:var(--gold-bright); box-shadow:0 0 8px var(--gold);\n    transition:transform .5s cubic-bezier(.65,0,.35,1), width .5s cubic-bezier(.65,0,.35,1);\n  }\n\n  /* ---------- form ---------- */\n  form{\n    opacity:0; animation:fadeUp .7s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.68s;\n  }\n  .field{ position:relative; margin-bottom:28px; }\n  .field label{\n    position:absolute; left:0; top:11px; font-size:14px; color:var(--taupe); pointer-events:none;\n    transition:transform .3s cubic-bezier(.4,0,.2,1), font-size .3s cubic-bezier(.4,0,.2,1), color .3s ease;\n    transform-origin:left top;\n  }\n  .field input{\n    width:100%; background:none; border:none; border-bottom:1px solid var(--hairline); color:var(--cream);\n    font-family:'Inter', sans-serif; font-size:15px; padding:11px 0 10px; outline:none;\n    transition:border-color .3s ease;\n  }\n  .field .underline-accent{\n    position:absolute; left:0; right:0; bottom:-1px; height:1.5px; background:var(--gold-bright);\n    transform:scaleX(0); transition:transform .4s cubic-bezier(.65,0,.35,1); box-shadow:0 0 8px var(--gold);\n  }\n  .field input:focus ~ .underline-accent{ transform:scaleX(1); }\n  .field input:focus{ border-color:transparent; }\n  .field input:focus + label,\n  .field input:not(:placeholder-shown) + label{\n    transform:translateY(-20px); font-size:11px; color:var(--gold-bright);\n  }\n  .field input::placeholder{ color:transparent; }\n\n  .extra{ max-height:0; opacity:0; overflow:hidden; transition:max-height .5s cubic-bezier(.4,0,.2,1), opacity .35s ease; }\n\n  .row-between{\n    display:flex; justify-content:space-between; align-items:center; font-size:12.5px; color:var(--taupe);\n    margin:2px 0 30px;\n  }\n  .row-between a{ color:var(--taupe); text-decoration:none; border-bottom:1px solid var(--hairline); padding-bottom:1px; transition:color .2s ease, border-color .2s ease; }\n  .row-between a:hover{ color:var(--gold-bright); border-color:var(--gold); }\n  .checkbox{ display:flex; align-items:center; gap:8px; }\n  .checkbox input{ accent-color:var(--gold); width:13px; height:13px; }\n\n  button.enter{\n    position:relative; width:100%; background:transparent; border:1px solid var(--gold-deep); color:var(--gold-bright);\n    font-family:'Cormorant Garamond', serif; font-style:italic; font-size:18px; letter-spacing:.02em;\n    padding:15px; cursor:pointer; overflow:hidden; isolation:isolate;\n    transition:color .5s ease, border-color .4s ease;\n  }\n  button.enter::before{\n    content:\"\"; position:absolute; inset:0; background:linear-gradient(100deg, var(--gold-deep), var(--gold-bright));\n    transform:translateX(-100%); transition:transform .5s cubic-bezier(.65,0,.35,1); z-index:-1;\n  }\n  button.enter:hover{ color:var(--ink); border-color:var(--gold-bright); }\n  button.enter:hover::before{ transform:translateX(0); }\n  button.enter:active{ transform:scale(.99); }\n  button.enter .btn-label{ display:inline-flex; align-items:center; justify-content:center; gap:10px; transition:opacity .25s ease; }\n  button.enter.loading .btn-label{ opacity:0; }\n  .btn-spinner{\n    position:absolute; inset:0; display:flex; align-items:center; justify-content:center; opacity:0; transition:opacity .25s ease;\n  }\n  button.enter.loading .btn-spinner{ opacity:1; }\n  .btn-spinner svg{ width:18px; height:18px; animation:spin 1.1s linear infinite; }\n  .btn-spinner circle{ stroke:currentColor; stroke-width:2; fill:none; stroke-dasharray:44; stroke-dashoffset:32; stroke-linecap:round; }\n  @keyframes spin{ to{ transform:rotate(360deg); } }\n\n  .divider{\n    display:flex; align-items:center; gap:16px; margin:28px 0; color:var(--taupe); font-size:11.5px; letter-spacing:.04em;\n  }\n  .divider::before, .divider::after{ content:\"\"; flex:1; height:1px; background:var(--hairline); }\n\n  button.ghost{\n    width:100%; background:none; border:1px solid var(--hairline); color:var(--cream); font-family:'Inter', sans-serif;\n    font-size:13.5px; padding:13px; cursor:pointer; transition:border-color .25s ease, background .25s ease;\n  }\n  button.ghost:hover{ border-color:var(--gold-deep); background:rgba(201,162,74,0.06); }\n\n  .foot{ text-align:center; font-size:12.5px; color:var(--taupe); margin-top:26px; }\n  .foot a{ color:var(--gold-bright); text-decoration:none; cursor:pointer; }\n  .foot a:hover{ text-decoration:underline; }\n\n  :focus-visible{ outline:1px solid var(--gold-bright); outline-offset:3px; }\n\n  @media (prefers-reduced-motion: reduce){\n    *{ animation-duration:.01ms !important; transition-duration:.01ms !important; }\n  }\n\n  .field{ position:relative; }\n  .eye-btn{\n    position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer;\n    color:var(--taupe); display:flex; align-items:center; justify-content:center; transition:color .2s ease; z-index:2;\n  }\n  .eye-btn:hover{ color:var(--gold-bright); }\n  .eye-btn svg{ width:15px; height:15px; }\n  input.has-eye{ padding-right:32px !important; }\n</style>\n</head>\n<body>\n\n<div class=\"glow glow-a\"></div>\n<div class=\"glow glow-b\"></div>\n<div class=\"grain\"></div>\n\n<div class=\"stage\">\n  <div class=\"mark\">\n    <svg viewBox=\"0 0 32 32\"><path d=\"M16 3 L16 29 M6 10 C6 18 10 26 16 29 C22 26 26 18 26 10 C20 13 12 13 6 10Z\"/></svg>\n    <span class=\"word\">AURELIA</span>\n  </div>\n\n  <h1 id=\"heading\">Welcome back.</h1>\n  <p class=\"sub\" id=\"subhead\">Your concierge is expecting you.</p>\n  <div class=\"rule\"></div>\n\n  <div class=\"tabs\" id=\"tabs\">\n    <button class=\"active\" data-tab=\"signin\" type=\"button\">Sign in</button>\n    <button data-tab=\"signup\" type=\"button\">Request access</button>\n    <span class=\"tab-indicator\" id=\"tabIndicator\"></span>\n  </div>\n\n  <form onsubmit=\"return false;\">\n    <div class=\"field extra\" id=\"nameField\">\n      <input type=\"text\" placeholder=\" \" id=\"nameInput\"  autocomplete=\"name\" />\n      <label for=\"nameInput\">Full name</label>\n      <span class=\"underline-accent\"></span>\n    </div>\n\n    <div class=\"field\">\n      <input type=\"email\" placeholder=\" \" id=\"emailInput\" required  autocomplete=\"email\" />\n      <label for=\"emailInput\">Email address</label>\n      <span class=\"underline-accent\"></span>\n    </div>\n\n    <div class=\"field\">\n      <input type=\"password\" placeholder=\" \" id=\"pwInput\" required  autocomplete=\"current-password\"  class=\"has-eye\" />\n      <label for=\"pwInput\">Password</label>\n      <span class=\"underline-accent\"></span><button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n    </div>\n\n    <div class=\"field extra\" id=\"confirmField\">\n      <input type=\"password\" placeholder=\" \" id=\"confirmInput\"  autocomplete=\"new-password\" />\n      <label for=\"confirmInput\">Confirm password</label>\n      <span class=\"underline-accent\"></span>\n    </div>\n\n    <div class=\"row-between\" id=\"signinOnlyRow\">\n      <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n      <a href=\"#\">Forgot password?</a>\n    </div>\n\n    <button class=\"enter\" type=\"submit\" id=\"submitBtn\">\n      <span class=\"btn-label\" id=\"submitLabel\">Enter</span>\n      <span class=\"btn-spinner\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"10\"/></svg></span>\n    </button>\n  </form>\n\n  <div class=\"divider\">or continue with</div>\n  <button class=\"ghost\" type=\"button\">Google</button>\n\n  <p class=\"foot\" id=\"footNote\">New to Aurelia? <a data-switch=\"signup\" id=\"switchLink\">Request access</a></p>\n</div>\n\n<script>\n(function(){\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    if(!input) return;\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n      btn.innerHTML = showing ? '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M17.94 17.94A10.94 10.94 0 0112 19c-7 0-11-7-11-7a20.6 20.6 0 015.06-5.94M9.9 4.24A10.4 10.4 0 0112 4c7 0 11 7 11 7a20.6 20.6 0 01-2.16 3.19M14.12 14.12a3 3 0 11-4.24-4.24\"/><line x1=\"1\" y1=\"1\" x2=\"23\" y2=\"23\"/></svg>' : '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>';\n    });\n  });\n\n  var tabs = document.querySelectorAll('#tabs button[data-tab]');\n  var indicator = document.getElementById('tabIndicator');\n  var nameField = document.getElementById('nameField');\n  var confirmField = document.getElementById('confirmField');\n  var signinOnlyRow = document.getElementById('signinOnlyRow');\n  var heading = document.getElementById('heading');\n  var subhead = document.getElementById('subhead');\n  var submitLabel = document.getElementById('submitLabel');\n  var footNote = document.getElementById('footNote');\n  var submitBtn = document.getElementById('submitBtn');\n\n  var COPY = {\n    signin: { heading: 'Welcome back.', sub: 'Your concierge is expecting you.', submit: 'Enter', foot: 'New to Aurelia? <a data-switch=\"signup\">Request access</a>' },\n    signup: { heading: 'Join Aurelia.', sub: 'Membership is by request. We reply within a day.', submit: 'Request access', foot: 'Already a member? <a data-switch=\"signin\">Sign in</a>' }\n  };\n\n  function positionIndicator(el){\n    indicator.style.width = el.offsetWidth + 'px';\n    indicator.style.transform = 'translateX(' + el.offsetLeft + 'px)';\n  }\n\n  function bindSwitchLinks(){\n    document.querySelectorAll('[data-switch]').forEach(function(a){\n      a.addEventListener('click', function(e){ e.preventDefault(); setMode(a.getAttribute('data-switch')); });\n    });\n  }\n\n  function setMode(mode){\n    tabs.forEach(function(t){ t.classList.toggle('active', t.dataset.tab === mode); if(t.dataset.tab === mode) positionIndicator(t); });\n    var showExtra = mode === 'signup';\n    [nameField, confirmField].forEach(function(f){\n      f.style.maxHeight = showExtra ? f.scrollHeight + 'px' : '0px';\n      f.style.opacity = showExtra ? 1 : 0;\n    });\n    signinOnlyRow.style.display = mode === 'signin' ? 'flex' : 'none';\n    heading.textContent = COPY[mode].heading;\n    subhead.textContent = COPY[mode].sub;\n    submitLabel.textContent = COPY[mode].submit;\n    footNote.innerHTML = COPY[mode].foot;\n    bindSwitchLinks();\n  }\n\n  tabs.forEach(function(t){ t.addEventListener('click', function(){ setMode(t.dataset.tab); }); });\n  bindSwitchLinks();\n  window.addEventListener('load', function(){ positionIndicator(document.querySelector('#tabs button.active')); });\n\n  // decorative submit micro-interaction (demo only \u2014 no real request is sent)\n  submitBtn.addEventListener('click', function(){\n    if(submitBtn.classList.contains('loading')) return;\n    submitBtn.classList.add('loading');\n    setTimeout(function(){ submitBtn.classList.remove('loading'); }, 1600);\n  });\n\n  window.addEventListener('message', function(e){\n    if(e.data && e.data.type === 'loginkit-accent'){\n      document.documentElement.style.setProperty('--gold-bright', e.data.color);\n    }\n  });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "noctis", "file": "forms/noctis.html", "title": "Noctis", "layout": "Split Screen + Pill Tab", "layout_key": "split-pill-tab", "palette": "Sapphire Navy", "palette_key": "sapphire-navy", "blurb": "A late-night workspace: sign-in/sign-up ride a sliding pill toggle, particles drift behind a glass card.", "n": 2, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Noctis \u2014 Sign In</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,500;0,600;1,500&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --navy:#0a0f1c; --navy-2:#0f1626; --panel:#121b30; --line:rgba(202,169,104,0.14);\n    --gold:#caa968; --gold-bright:#e8d3a0; --cream:#eef0f7; --dim:#7c869e;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--navy); color:var(--cream); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:grid; grid-template-columns:1.15fr 1fr; overflow:hidden;\n  }\n  @media(max-width:860px){ body{ grid-template-columns:1fr; } .left{ display:none; } }\n\n  /* ---------- left: quote panel with drifting particles ---------- */\n  .left{\n    position:relative; background:linear-gradient(160deg, var(--navy-2), var(--navy)); overflow:hidden;\n    display:flex; flex-direction:column; justify-content:space-between; padding:56px;\n  }\n  .particle{ position:absolute; border-radius:50%; background:var(--gold); opacity:0; animation:twinkle var(--dur) ease-in-out infinite; animation-delay:var(--delay); }\n  @keyframes twinkle{ 0%,100%{ opacity:0; transform:translateY(0) scale(.8);} 50%{ opacity:var(--peak); transform:translateY(-14px) scale(1);} }\n\n  .brand{ font-family:'Playfair Display', serif; font-size:15px; letter-spacing:.1em; color:var(--gold-bright); position:relative; z-index:1;\n    opacity:0; animation:fadeIn .8s ease forwards; animation-delay:.2s; }\n  .quote{ position:relative; z-index:1; max-width:400px; opacity:0; animation:fadeUp .9s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.4s; }\n  .quote p{ font-family:'Playfair Display', serif; font-style:italic; font-size:26px; line-height:1.5; color:var(--cream); }\n  .quote span{ display:block; margin-top:18px; font-size:12.5px; color:var(--dim); font-style:normal; }\n  .foot-mark{ position:relative; z-index:1; font-size:11.5px; color:var(--dim); letter-spacing:.05em;\n    opacity:0; animation:fadeIn .8s ease forwards; animation-delay:.6s; }\n  @keyframes fadeIn{ to{ opacity:1; } }\n  @keyframes fadeUp{ to{ opacity:1; transform:none; } }\n  .quote{ transform:translateY(10px); }\n\n  /* ---------- right: glass form ---------- */\n  .right{ display:flex; align-items:center; justify-content:center; padding:48px; position:relative; }\n  .card{\n    width:100%; max-width:380px; background:rgba(255,255,255,0.03); border:1px solid var(--line); border-radius:4px;\n    padding:44px 38px; backdrop-filter:blur(20px); -webkit-backdrop-filter:blur(20px);\n    box-shadow:0 40px 80px -30px rgba(0,0,0,.6);\n    opacity:0; transform:translateY(14px) scale(.98); animation:reveal 1s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.15s;\n  }\n  @keyframes reveal{ to{ opacity:1; transform:none; } }\n\n  h1{ font-family:'Playfair Display', serif; font-weight:600; font-size:27px; margin-bottom:8px; }\n  .sub{ font-size:13.5px; color:var(--dim); margin-bottom:30px; }\n\n  .tabs{ position:relative; display:flex; gap:4px; margin-bottom:30px; background:rgba(255,255,255,0.03); border:1px solid var(--line); border-radius:999px; padding:4px; }\n  .tabs button{ position:relative; z-index:2; flex:1; background:none; border:none; color:var(--dim); font-size:12px; font-weight:600; padding:9px 0; cursor:pointer; transition:color .3s ease; border-radius:999px; }\n  .tabs button.active{ color:#101b30; }\n  .tab-indicator{ position:absolute; top:4px; bottom:4px; z-index:1; border-radius:999px; background:var(--gold); box-shadow:0 4px 14px -4px rgba(202,169,104,0.5); transition:transform .45s cubic-bezier(.65,0,.35,1), width .45s cubic-bezier(.65,0,.35,1); }\n\n  .field{ position:relative; margin-bottom:24px; }\n  .field label{ position:absolute; left:14px; top:13px; font-size:14px; color:var(--dim); pointer-events:none; transition:transform .3s cubic-bezier(.4,0,.2,1), font-size .3s ease, color .3s ease; transform-origin:left top; }\n  .field input{ width:100%; background:rgba(255,255,255,0.02); border:1px solid var(--line); color:var(--cream); font-size:14.5px; padding:20px 14px 8px; border-radius:3px; outline:none; transition:border-color .3s ease, background .3s ease; }\n  .field input:focus{ border-color:var(--gold); background:rgba(202,169,104,0.05); }\n  .field input:focus + label, .field input:not(:placeholder-shown) + label{ transform:translateY(-9px); font-size:10.5px; color:var(--gold-bright); }\n  .field input::placeholder{ color:transparent; }\n  .extra{ max-height:0; opacity:0; overflow:hidden; transition:max-height .5s cubic-bezier(.4,0,.2,1), opacity .35s ease; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--dim); margin:-6px 0 26px; }\n  .row-between a{ color:var(--dim); text-decoration:none; border-bottom:1px solid var(--line); }\n  .row-between a:hover{ color:var(--gold-bright); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--gold); width:13px; height:13px; }\n\n  button.enter{ position:relative; width:100%; background:var(--gold); border:none; color:#171008; font-weight:600; font-size:13.5px; letter-spacing:.02em; padding:14px; border-radius:3px; cursor:pointer; overflow:hidden; transition:filter .3s ease, transform .1s ease; }\n  button.enter:hover{ filter:brightness(1.1); }\n  button.enter:active{ transform:scale(.99); }\n  button.enter::after{ content:\"\"; position:absolute; top:0; left:-60%; width:40%; height:100%; background:linear-gradient(120deg, transparent, rgba(255,255,255,.35), transparent); transform:skewX(-20deg); transition:left .6s ease; }\n  button.enter:hover::after{ left:120%; }\n\n  .divider{ display:flex; align-items:center; gap:14px; margin:24px 0; color:var(--dim); font-size:11px; }\n  .divider::before,.divider::after{ content:\"\"; flex:1; height:1px; background:var(--line); }\n  button.ghost{ width:100%; background:none; border:1px solid var(--line); color:var(--cream); font-size:13px; padding:12px; border-radius:3px; cursor:pointer; transition:border-color .2s ease; }\n  button.ghost:hover{ border-color:var(--gold); }\n  .foot{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:22px; }\n  .foot a{ color:var(--gold-bright); text-decoration:none; cursor:pointer; }\n  :focus-visible{ outline:1px solid var(--gold-bright); outline-offset:2px; }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n\n  .field{ position:relative; }\n  .eye-btn{\n    position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer;\n    color:var(--dim); display:flex; align-items:center; justify-content:center; transition:color .2s ease; z-index:2;\n  }\n  .eye-btn:hover{ color:var(--gold-bright); }\n  .eye-btn svg{ width:15px; height:15px; }\n  input.has-eye{ padding-right:32px !important; }\n</style>\n</head>\n<body>\n\n<div class=\"left\" id=\"leftPanel\">\n  <div class=\"brand\">NOCTIS</div>\n  <div class=\"quote\">\n    <p>\"The quiet hours are when the real work gets done.\"</p>\n    <span>\u2014 a founder, 2 a.m., three weeks before launch</span>\n  </div>\n  <div class=\"foot-mark\">Encrypted end to end \u00b7 SOC 2 Type II</div>\n</div>\n\n<div class=\"right\">\n  <div class=\"card\">\n    <h1 id=\"heading\">Sign in to Noctis</h1>\n    <p class=\"sub\" id=\"subhead\">Pick up exactly where the night left off.</p>\n\n    <div class=\"tabs\" id=\"tabs\">\n      <button class=\"active\" data-tab=\"signin\" type=\"button\">Sign in</button>\n      <button data-tab=\"signup\" type=\"button\">Create account</button>\n      <span class=\"tab-indicator\" id=\"tabIndicator\"></span>\n    </div>\n\n    <form onsubmit=\"return false;\">\n      <div class=\"field extra\" id=\"nameField\">\n        <input type=\"text\" placeholder=\" \" id=\"nameInput\"  autocomplete=\"name\" />\n        <label for=\"nameInput\">Full name</label>\n      </div>\n      <div class=\"field\">\n        <input type=\"email\" placeholder=\" \" id=\"emailInput\" required  autocomplete=\"email\" />\n        <label for=\"emailInput\">Email address</label>\n      </div>\n      <div class=\"field\">\n        <input type=\"password\" placeholder=\" \" id=\"pwInput\" required  autocomplete=\"current-password\"  class=\"has-eye\" />\n        <label for=\"pwInput\">Password</label><button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n      </div>\n      <div class=\"field extra\" id=\"confirmField\">\n        <input type=\"password\" placeholder=\" \" id=\"confirmInput\"  autocomplete=\"new-password\" />\n        <label for=\"confirmInput\">Confirm password</label>\n      </div>\n      <div class=\"row-between\" id=\"signinOnlyRow\">\n        <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n        <a href=\"#\">Forgot password?</a>\n      </div>\n      <button class=\"enter\" type=\"submit\"><span id=\"submitLabel\">Sign in</span></button>\n    </form>\n\n    <div class=\"divider\">or continue with</div>\n    <button class=\"ghost\" type=\"button\">Google</button>\n\n    <p class=\"foot\" id=\"footNote\">New here? <a data-switch=\"signup\">Create an account</a></p>\n  </div>\n</div>\n\n<script>\n(function(){\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    if(!input) return;\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n      btn.innerHTML = showing ? '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M17.94 17.94A10.94 10.94 0 0112 19c-7 0-11-7-11-7a20.6 20.6 0 015.06-5.94M9.9 4.24A10.4 10.4 0 0112 4c7 0 11 7 11 7a20.6 20.6 0 01-2.16 3.19M14.12 14.12a3 3 0 11-4.24-4.24\"/><line x1=\"1\" y1=\"1\" x2=\"23\" y2=\"23\"/></svg>' : '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>';\n    });\n  });\n\n  // scatter drifting particles across the left panel\n  var left = document.getElementById('leftPanel');\n  for(var i=0;i<26;i++){\n    var d = document.createElement('div');\n    d.className = 'particle';\n    var size = 1 + Math.random()*2;\n    d.style.width = size+'px'; d.style.height = size+'px';\n    d.style.left = Math.random()*100+'%'; d.style.top = Math.random()*100+'%';\n    d.style.setProperty('--dur', (4+Math.random()*5).toFixed(1)+'s');\n    d.style.setProperty('--delay', (Math.random()*6).toFixed(1)+'s');\n    d.style.setProperty('--peak', (0.35+Math.random()*0.45).toFixed(2));\n    left.appendChild(d);\n  }\n\n  var tabs = document.querySelectorAll('#tabs button[data-tab]');\n  var indicator = document.getElementById('tabIndicator');\n  var nameField = document.getElementById('nameField');\n  var confirmField = document.getElementById('confirmField');\n  var signinOnlyRow = document.getElementById('signinOnlyRow');\n  var heading = document.getElementById('heading');\n  var subhead = document.getElementById('subhead');\n  var submitLabel = document.getElementById('submitLabel');\n  var footNote = document.getElementById('footNote');\n\n  var COPY = {\n    signin: { heading:'Sign in to Noctis', sub:'Pick up exactly where the night left off.', submit:'Sign in', foot:'New here? <a data-switch=\"signup\">Create an account</a>' },\n    signup: { heading:'Create your account', sub:'A minute of setup, then straight to work.', submit:'Create account', foot:'Already have an account? <a data-switch=\"signin\">Sign in</a>' }\n  };\n\n  function positionIndicator(el){ indicator.style.width = el.offsetWidth+'px'; indicator.style.transform = 'translateX('+el.offsetLeft+'px)'; }\n  function bindSwitchLinks(){ document.querySelectorAll('[data-switch]').forEach(function(a){ a.addEventListener('click', function(e){ e.preventDefault(); setMode(a.getAttribute('data-switch')); }); }); }\n\n  function setMode(mode){\n    tabs.forEach(function(t){ t.classList.toggle('active', t.dataset.tab===mode); if(t.dataset.tab===mode) positionIndicator(t); });\n    var showExtra = mode==='signup';\n    [nameField, confirmField].forEach(function(f){ f.style.maxHeight = showExtra ? f.scrollHeight+'px' : '0px'; f.style.opacity = showExtra?1:0; });\n    signinOnlyRow.style.display = mode==='signin' ? 'flex' : 'none';\n    heading.textContent = COPY[mode].heading;\n    subhead.textContent = COPY[mode].sub;\n    submitLabel.textContent = COPY[mode].submit;\n    footNote.innerHTML = COPY[mode].foot;\n    bindSwitchLinks();\n  }\n  tabs.forEach(function(t){ t.addEventListener('click', function(){ setMode(t.dataset.tab); }); });\n  bindSwitchLinks();\n  window.addEventListener('load', function(){ positionIndicator(document.querySelector('#tabs button.active')); });\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--gold', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "verdant", "file": "forms/verdant.html", "title": "Verdant", "layout": "Quiet Toggle + Static Labels", "layout_key": "quiet-static", "palette": "Emerald Noir", "palette_key": "emerald-noir", "blurb": "A textile atelier: plain-text mode switch, static labels (no floating), a flat solid button \u2014 no slider, no wipe.", "n": 3, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Verdant \u2014 Sign In</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;1,500&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --bg:#0b1512; --panel:rgba(255,255,255,0.035); --line:rgba(216,178,106,0.16);\n    --gold:#d8b26a; --gold-bright:#ecd49a; --cream:#e9f1ec; --dim:#8ea69a;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--bg); color:var(--cream); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:flex; align-items:center; padding:60px 6vw; gap:6vw;\n  }\n  @media(max-width:820px){ body{ flex-direction:column; justify-content:center; padding:60px 24px; gap:40px; } }\n\n  /* ---------- left: masked headline reveal ---------- */\n  .headline-col{ flex:1.1; min-width:0; }\n  .brand{ font-size:11.5px; letter-spacing:.14em; color:var(--gold); margin-bottom:26px;\n    opacity:0; animation:fadeIn .7s ease forwards; animation-delay:.1s; }\n  .headline{ overflow:hidden; }\n  .headline h1{\n    font-family:'Cormorant Garamond', serif; font-weight:500; font-style:italic; font-size:clamp(38px,6vw,64px);\n    line-height:1.08; color:var(--cream); max-width:520px;\n    clip-path:inset(0 100% 0 0); animation:wipe 1.1s cubic-bezier(.65,0,.35,1) forwards; animation-delay:.3s;\n  }\n  @keyframes wipe{ to{ clip-path:inset(0 0 0 0); } }\n  .lede{ font-size:15px; color:var(--dim); max-width:400px; margin-top:22px; line-height:1.6;\n    opacity:0; animation:fadeUp .8s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.9s; }\n  @keyframes fadeIn{ to{ opacity:1; } }\n  @keyframes fadeUp{ to{ opacity:1; transform:none; } }\n  .lede{ transform:translateY(8px); }\n\n  .vrule{ width:1px; align-self:stretch; background:linear-gradient(180deg, transparent, var(--line) 20%, var(--line) 80%, transparent);\n    opacity:0; animation:fadeIn 1s ease forwards; animation-delay:1s; }\n  @media(max-width:820px){ .vrule{ display:none; } }\n\n  /* ---------- right: form column ---------- */\n  .form-col{ flex:1; max-width:360px; width:100%;\n    opacity:0; animation:fadeUp .8s cubic-bezier(.16,1,.3,1) forwards; animation-delay:1.05s; }\n\n  .tabs{ display:flex; gap:26px; margin-bottom:32px; }\n  .tabs button{ background:none; border:none; color:var(--dim); font-size:13px; font-style:italic; font-family:'Cormorant Garamond', serif; padding:0; cursor:pointer; transition:color .3s ease, font-weight .3s ease; }\n  .tabs button.active{ color:var(--gold-bright); font-weight:600; }\n\n  .field{ position:relative; margin-bottom:22px; }\n  .field label{ display:block; font-size:11px; letter-spacing:.04em; color:var(--dim); margin-bottom:8px; }\n  .field input{ width:100%; background:none; border:none; border-bottom:1px solid var(--line); color:var(--cream); font-size:15px; padding:8px 0; outline:none; transition:border-color .3s ease; }\n  .field input:focus{ border-color:var(--gold-bright); }\n  .field input::placeholder{ color:var(--dim); opacity:.5; }\n  .extra{ max-height:0; opacity:0; overflow:hidden; transition:max-height .5s cubic-bezier(.4,0,.2,1), opacity .35s ease; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--dim); margin:4px 0 28px; }\n  .row-between a{ color:var(--dim); text-decoration:none; border-bottom:1px solid var(--line); }\n  .row-between a:hover{ color:var(--gold-bright); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--gold); width:13px; height:13px; }\n\n  button.enter{ width:100%; background:var(--gold-bright); border:none; color:#0b1512;\n    font-family:'Cormorant Garamond', serif; font-style:italic; font-weight:600; font-size:18px; padding:14px; cursor:pointer;\n    transition:background .3s ease, transform .1s ease; }\n  button.enter:hover{ background:var(--gold); }\n  button.enter:active{ transform:scale(.99); }\n\n  .divider{ display:flex; align-items:center; gap:14px; margin:24px 0; color:var(--dim); font-size:11px; }\n  .divider::before,.divider::after{ content:\"\"; flex:1; height:1px; background:var(--line); }\n  button.ghost{ width:100%; background:none; border:1px solid var(--line); color:var(--cream); font-size:13px; padding:12px; cursor:pointer; transition:border-color .2s ease; }\n  button.ghost:hover{ border-color:var(--gold); }\n  .foot{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:22px; }\n  .foot a{ color:var(--gold-bright); text-decoration:none; cursor:pointer; }\n  :focus-visible{ outline:1px solid var(--gold-bright); outline-offset:2px; }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n\n  .field{ position:relative; }\n  .eye-btn{\n    position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer;\n    color:var(--dim); display:flex; align-items:center; justify-content:center; transition:color .2s ease; z-index:2;\n  }\n  .eye-btn:hover{ color:var(--gold-bright); }\n  .eye-btn svg{ width:15px; height:15px; }\n  input.has-eye{ padding-right:32px !important; }\n</style>\n</head>\n<body>\n\n<div class=\"headline-col\">\n  <div class=\"brand\">VERDANT ATELIER</div>\n  <div class=\"headline\"><h1>Grown slowly,<br/>built to last.</h1></div>\n  <p class=\"lede\">Sign in to your workroom \u2014 patterns, fabric orders, and the season's fittings, all in one place.</p>\n</div>\n\n<div class=\"vrule\"></div>\n\n<div class=\"form-col\">\n  <div class=\"tabs\" id=\"tabs\">\n    <button class=\"active\" data-tab=\"signin\" type=\"button\">Sign in</button>\n    <button data-tab=\"signup\" type=\"button\">Create account</button>\n  </div>\n\n  <form onsubmit=\"return false;\">\n    <div class=\"field extra\" id=\"nameField\">\n      <label for=\"nameInput\">Full name</label>\n      <input type=\"text\" placeholder=\"Jordan Rivera\" id=\"nameInput\"  autocomplete=\"name\" />\n    </div>\n    <div class=\"field\">\n      <label for=\"emailInput\">Email address</label>\n      <input type=\"email\" placeholder=\"you@company.com\" id=\"emailInput\" required  autocomplete=\"email\" />\n    </div>\n    <div class=\"field\">\n      <label for=\"pwInput\">Password</label>\n      <input type=\"password\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\" id=\"pwInput\" required  autocomplete=\"current-password\"  class=\"has-eye\" /><button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n    </div>\n    <div class=\"field extra\" id=\"confirmField\">\n      <label for=\"confirmInput\">Confirm password</label>\n      <input type=\"password\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\" id=\"confirmInput\"  autocomplete=\"new-password\" />\n    </div>\n    <div class=\"row-between\" id=\"signinOnlyRow\">\n      <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n      <a href=\"#\">Forgot password?</a>\n    </div>\n    <button class=\"enter\" type=\"submit\"><span id=\"submitLabel\">Enter</span></button>\n  </form>\n\n  <div class=\"divider\">or continue with</div>\n  <button class=\"ghost\" type=\"button\">Google</button>\n\n  <p class=\"foot\" id=\"footNote\">New here? <a data-switch=\"signup\">Create an account</a></p>\n</div>\n\n<script>\n(function(){\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    if(!input) return;\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n      btn.innerHTML = showing ? '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M17.94 17.94A10.94 10.94 0 0112 19c-7 0-11-7-11-7a20.6 20.6 0 015.06-5.94M9.9 4.24A10.4 10.4 0 0112 4c7 0 11 7 11 7a20.6 20.6 0 01-2.16 3.19M14.12 14.12a3 3 0 11-4.24-4.24\"/><line x1=\"1\" y1=\"1\" x2=\"23\" y2=\"23\"/></svg>' : '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>';\n    });\n  });\n\n  var tabs = document.querySelectorAll('#tabs button[data-tab]');\n  var nameField = document.getElementById('nameField');\n  var confirmField = document.getElementById('confirmField');\n  var signinOnlyRow = document.getElementById('signinOnlyRow');\n  var submitLabel = document.getElementById('submitLabel');\n  var footNote = document.getElementById('footNote');\n\n  var COPY = {\n    signin: { submit:'Enter', foot:'New here? <a data-switch=\"signup\">Create an account</a>' },\n    signup: { submit:'Join', foot:'Already have an account? <a data-switch=\"signin\">Sign in</a>' }\n  };\n\n  function bindSwitchLinks(){ document.querySelectorAll('[data-switch]').forEach(function(a){ a.addEventListener('click', function(e){ e.preventDefault(); setMode(a.getAttribute('data-switch')); }); }); }\n\n  function setMode(mode){\n    tabs.forEach(function(t){ t.classList.toggle('active', t.dataset.tab===mode); });\n    var showExtra = mode==='signup';\n    [nameField, confirmField].forEach(function(f){ f.style.maxHeight = showExtra ? f.scrollHeight+'px' : '0px'; f.style.opacity = showExtra?1:0; });\n    signinOnlyRow.style.display = mode==='signin' ? 'flex' : 'none';\n    submitLabel.textContent = COPY[mode].submit;\n    footNote.innerHTML = COPY[mode].foot;\n    bindSwitchLinks();\n  }\n  tabs.forEach(function(t){ t.addEventListener('click', function(){ setMode(t.dataset.tab); }); });\n  bindSwitchLinks();\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--gold', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "bordeaux-press", "file": "forms/bordeaux-press.html", "title": "The Bordeaux Press", "layout": "Page Flip", "layout_key": "page-flip", "palette": "Wine & Ivory", "palette_key": "wine-ivory", "blurb": "A literary subscription desk: sign-in and sign-up sit on either side of a real 3D page turn.", "n": 4, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>The Bordeaux Press \u2014 Reader Sign In</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,500;0,9..144,600;1,9..144,500&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --paper:#f7f1e6; --card:#fffdf8; --line:#ddccae; --wine:#6e2331; --wine-bright:#8c3244;\n    --ink:#241a16; --dim:#8a7458;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--paper); color:var(--ink); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:flex; align-items:center; justify-content:center; padding:60px 24px; perspective:1800px;\n  }\n\n  .masthead{\n    text-align:center; margin-bottom:34px;\n    opacity:0; animation:fadeIn .7s ease forwards; animation-delay:.1s;\n  }\n  .masthead .name{ font-family:'Fraunces', serif; font-size:15px; letter-spacing:.24em; color:var(--wine); }\n  .masthead .rule-pair{ display:flex; align-items:center; gap:10px; margin-top:10px; }\n  .masthead .rule-pair span{ flex:1; height:1px; background:var(--line); }\n  .masthead .rule-pair::before, .masthead .rule-pair::after{ content:\"\u25c6\"; font-size:8px; color:var(--wine); }\n  @keyframes fadeIn{ to{ opacity:1; } }\n\n  .flip-stage{ width:100%; max-width:400px; position:relative; height:600px;\n    opacity:0; transform:translateY(14px); animation:fadeUp .8s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.25s; }\n  @keyframes fadeUp{ to{ opacity:1; transform:none; } }\n\n  .flip-inner{ position:relative; width:100%; height:600px; transition:transform .75s cubic-bezier(.65,0,.35,1); transform-style:preserve-3d; }\n  .flip-stage.flipped .flip-inner{ transform:rotateY(-180deg); }\n\n  .page{\n    position:absolute; inset:0; backface-visibility:hidden; background:var(--card); border:1px solid var(--line);\n    padding:42px 38px; box-shadow:0 30px 60px -30px rgba(110,35,49,0.25);\n  }\n  .page.back{ transform:rotateY(180deg); }\n\n  h1{ font-family:'Fraunces', serif; font-weight:600; font-size:27px; line-height:1.15; margin-bottom:8px; }\n  .sub{ font-size:13.5px; color:var(--dim); margin-bottom:30px; line-height:1.5; }\n\n  .field{ position:relative; margin-bottom:24px; }\n  .field label{ position:absolute; left:0; top:11px; font-size:14px; color:var(--dim); pointer-events:none; transition:transform .3s cubic-bezier(.4,0,.2,1), font-size .3s ease, color .3s ease; transform-origin:left top; }\n  .field input{ width:100%; background:none; border:none; border-bottom:1px solid var(--line); color:var(--ink); font-size:15px; padding:10px 0; outline:none; transition:border-color .3s ease; }\n  .field .underline-accent{ position:absolute; left:0; right:0; bottom:-1px; height:1.5px; background:var(--wine); transform:scaleX(0); transition:transform .4s cubic-bezier(.65,0,.35,1); }\n  .field input:focus ~ .underline-accent{ transform:scaleX(1); }\n  .field input:focus{ border-color:transparent; }\n  .field input:focus + label, .field input:not(:placeholder-shown) + label{ transform:translateY(-19px); font-size:11px; color:var(--wine); }\n  .field input::placeholder{ color:transparent; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--dim); margin:0 0 28px; }\n  .row-between a{ color:var(--dim); text-decoration:none; border-bottom:1px solid var(--line); }\n  .row-between a:hover{ color:var(--wine); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--wine); width:13px; height:13px; }\n\n  button.enter{ position:relative; width:100%; background:var(--wine); border:none; color:var(--card);\n    font-family:'Fraunces', serif; font-style:italic; font-size:17px; padding:14px; cursor:pointer; transition:background .3s ease, transform .1s ease; }\n  button.enter:hover{ background:var(--wine-bright); }\n  button.enter:active{ transform:scale(.99); }\n\n  .divider{ display:flex; align-items:center; gap:14px; margin:24px 0; color:var(--dim); font-size:11px; }\n  .divider::before,.divider::after{ content:\"\"; flex:1; height:1px; background:var(--line); }\n  button.ghost{ width:100%; background:none; border:1px solid var(--line); color:var(--ink); font-size:13px; padding:12px; cursor:pointer; transition:border-color .2s ease; }\n  button.ghost:hover{ border-color:var(--wine); }\n\n  .foot{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:22px; }\n  .foot a{ color:var(--wine); text-decoration:none; cursor:pointer; font-weight:600; }\n  .foot a:hover{ text-decoration:underline; }\n  :focus-visible{ outline:1px solid var(--wine); outline-offset:2px; }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n\n  .field{ position:relative; }\n  .eye-btn{\n    position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer;\n    color:var(--dim); display:flex; align-items:center; justify-content:center; transition:color .2s ease; z-index:2;\n  }\n  .eye-btn:hover{ color:var(--wine-bright); }\n  .eye-btn svg{ width:15px; height:15px; }\n  input.has-eye{ padding-right:32px !important; }\n</style>\n</head>\n<body>\n\n<div>\n  <div class=\"masthead\">\n    <div class=\"name\">THE BORDEAUX PRESS</div>\n    <div class=\"rule-pair\"><span></span></div>\n  </div>\n\n  <div class=\"flip-stage\" id=\"flipStage\">\n    <div class=\"flip-inner\">\n      <div class=\"page front\">\n        <h1>Reader sign in</h1>\n        <p class=\"sub\">Your subscription, your annotations, your reading list.</p>\n        <form onsubmit=\"return false;\">\n          <div class=\"field\">\n            <input type=\"email\" placeholder=\" \" id=\"emailInputA\" required  autocomplete=\"email\" />\n            <label for=\"emailInputA\">Email address</label>\n            <span class=\"underline-accent\"></span>\n          </div>\n          <div class=\"field\">\n            <input type=\"password\" placeholder=\" \" id=\"pwInputA\" required  autocomplete=\"current-password\"  class=\"has-eye\" />\n            <label for=\"pwInputA\">Password</label>\n            <span class=\"underline-accent\"></span><button type=\"button\" class=\"eye-btn\" data-for=\"pwInputA\" aria-label=\"Show password\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n          </div>\n          <div class=\"row-between\">\n            <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n            <a href=\"#\">Forgot password?</a>\n          </div>\n          <button class=\"enter\" type=\"submit\">Sign in</button>\n        </form>\n        <div class=\"divider\">or continue with</div>\n        <button class=\"ghost\" type=\"button\">Google</button>\n        <p class=\"foot\">New reader? <a data-flip>Start a subscription</a></p>\n      </div>\n\n      <div class=\"page back\">\n        <h1>Start your subscription</h1>\n        <p class=\"sub\">Full archive access, delivered weekly.</p>\n        <form onsubmit=\"return false;\">\n          <div class=\"field\">\n            <input type=\"text\" placeholder=\" \" id=\"nameInputB\"  autocomplete=\"name\" />\n            <label for=\"nameInputB\">Full name</label>\n            <span class=\"underline-accent\"></span>\n          </div>\n          <div class=\"field\">\n            <input type=\"email\" placeholder=\" \" id=\"emailInputB\" required  autocomplete=\"email\" />\n            <label for=\"emailInputB\">Email address</label>\n            <span class=\"underline-accent\"></span>\n          </div>\n          <div class=\"field\">\n            <input type=\"password\" placeholder=\" \" id=\"pwInputB\" required  autocomplete=\"new-password\"  class=\"has-eye\" />\n            <label for=\"pwInputB\">Password</label>\n            <span class=\"underline-accent\"></span><button type=\"button\" class=\"eye-btn\" data-for=\"pwInputB\" aria-label=\"Show password\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n          </div>\n          <button class=\"enter\" type=\"submit\" style=\"margin-top:6px;\">Subscribe</button>\n        </form>\n        <p class=\"foot\" style=\"margin-top:24px;\">Already a reader? <a data-flip>Sign in</a></p>\n      </div>\n    </div>\n  </div>\n</div>\n\n<script>\n(function(){\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    if(!input) return;\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n      btn.innerHTML = showing ? '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M17.94 17.94A10.94 10.94 0 0112 19c-7 0-11-7-11-7a20.6 20.6 0 015.06-5.94M9.9 4.24A10.4 10.4 0 0112 4c7 0 11 7 11 7a20.6 20.6 0 01-2.16 3.19M14.12 14.12a3 3 0 11-4.24-4.24\"/><line x1=\"1\" y1=\"1\" x2=\"23\" y2=\"23\"/></svg>' : '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>';\n    });\n  });\n\n  var stage = document.getElementById('flipStage');\n  document.querySelectorAll('[data-flip]').forEach(function(a){\n    a.addEventListener('click', function(e){ e.preventDefault(); stage.classList.toggle('flipped'); });\n  });\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--wine', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "copper-oak", "file": "forms/copper-oak.html", "title": "Copper & Oak", "layout": "Pill Tab + Boxed Fields", "layout_key": "pill-boxed", "palette": "Copper & Parchment", "palette_key": "copper-parchment", "blurb": "A boutique workshop: boxed inputs with static labels, a pill toggle, and a button that presses down with a hard offset shadow.", "n": 5, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Copper &amp; Oak \u2014 Suite Access</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --stone:#efe7d8; --card:#fffdf9; --ink:#241a12; --dim:#7c6c56; --copper:#a85a2e; --copper-bright:#c97a4a;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--stone); color:var(--ink); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:flex; align-items:center; justify-content:center; padding:60px 24px;\n  }\n\n  .frame{ position:relative; width:100%; max-width:420px; padding:54px 44px 44px;\n    opacity:0; animation:fadeIn .6s ease forwards; animation-delay:.5s; }\n  @keyframes fadeIn{ to{ opacity:1; } }\n\n  .frame-line{ position:absolute; background:var(--copper); }\n  .fl-top{ top:0; left:0; height:1.5px; width:0; animation:growX .6s cubic-bezier(.65,0,.35,1) forwards; animation-delay:0s; }\n  .fl-right{ top:0; right:0; width:1.5px; height:0; animation:growY .6s cubic-bezier(.65,0,.35,1) forwards; animation-delay:.6s; }\n  .fl-bottom{ bottom:0; right:0; height:1.5px; width:0; animation:growXr .6s cubic-bezier(.65,0,.35,1) forwards; animation-delay:1.2s; }\n  .fl-left{ bottom:0; left:0; width:1.5px; height:0; animation:growYr .6s cubic-bezier(.65,0,.35,1) forwards; animation-delay:1.8s; }\n  @keyframes growX{ from{width:0;} to{width:100%;} }\n  @keyframes growXr{ from{width:0;} to{width:100%;} }\n  @keyframes growY{ from{height:0;} to{height:100%;} }\n  @keyframes growYr{ from{height:0;} to{height:100%;} }\n\n  .suite-no{ font-size:11px; letter-spacing:.14em; color:var(--copper); margin-bottom:16px;\n    opacity:0; animation:fadeUp .7s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.15s; }\n  h1{ font-family:'Fraunces', serif; font-weight:600; font-size:28px; line-height:1.15; margin-bottom:8px;\n    opacity:0; animation:fadeUp .7s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.22s; }\n  .sub{ font-size:13.5px; color:var(--dim); margin-bottom:32px;\n    opacity:0; animation:fadeUp .7s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.28s; }\n  @keyframes fadeUp{ to{ opacity:1; transform:none; } }\n  h1, .sub, .suite-no{ transform:translateY(8px); }\n\n  .tabs{ position:relative; display:flex; gap:4px; margin-bottom:30px; background:transparent; border:2px solid var(--ink); padding:4px;\n    opacity:0; animation:fadeUp .7s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.34s; }\n  .tabs button{ position:relative; z-index:2; flex:1; background:none; border:none; color:var(--dim); font-size:11.5px; font-weight:600; padding:9px 0; cursor:pointer; transition:color .3s ease; text-transform:uppercase; letter-spacing:.03em; }\n  .tabs button.active{ color:var(--stone); }\n  .tab-indicator{ position:absolute; top:4px; bottom:4px; z-index:1; background:var(--copper); transition:transform .4s cubic-bezier(.65,0,.35,1), width .4s cubic-bezier(.65,0,.35,1); }\n\n  form{ opacity:0; animation:fadeUp .7s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.4s; }\n\n  .field{ position:relative; margin-bottom:20px; }\n  .field label{ display:block; font-size:10.5px; letter-spacing:.06em; text-transform:uppercase; color:var(--dim); margin-bottom:7px; }\n  .field input{ width:100%; background:var(--stone); border:2px solid rgba(36,26,18,0.22); color:var(--ink); font-size:15px; padding:11px 12px; outline:none; transition:border-color .2s ease; }\n  .field input:focus{ border-color:var(--copper); }\n  .field input::placeholder{ color:rgba(36,26,18,0.35); }\n  .extra{ max-height:0; opacity:0; overflow:hidden; transition:max-height .5s cubic-bezier(.4,0,.2,1), opacity .35s ease; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--dim); margin:0 0 24px; }\n  .row-between a{ color:var(--dim); text-decoration:none; border-bottom:1px solid rgba(36,26,18,0.18); }\n  .row-between a:hover{ color:var(--copper); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--copper); width:13px; height:13px; }\n\n  button.enter{ position:relative; width:100%; background:var(--ink); border:2px solid var(--ink); color:var(--stone);\n    font-size:13.5px; font-weight:600; letter-spacing:.04em; text-transform:uppercase; padding:14px; cursor:pointer;\n    box-shadow:4px 4px 0 var(--copper); transition:transform .15s ease, box-shadow .15s ease; }\n  button.enter span{ position:relative; }\n  button.enter:hover{ transform:translate(-2px,-2px); box-shadow:6px 6px 0 var(--copper); }\n  button.enter:active{ transform:translate(2px,2px); box-shadow:1px 1px 0 var(--copper); }\n\n  .divider{ display:flex; align-items:center; gap:14px; margin:24px 0; color:var(--dim); font-size:11px; }\n  .divider::before,.divider::after{ content:\"\"; flex:1; height:1px; background:rgba(36,26,18,0.12); }\n  button.ghost{ width:100%; background:none; border:1px solid rgba(36,26,18,0.18); color:var(--ink); font-size:13px; padding:12px; cursor:pointer; transition:border-color .2s ease; }\n  button.ghost:hover{ border-color:var(--copper); }\n\n  .foot{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:22px; }\n  .foot a{ color:var(--copper); text-decoration:none; cursor:pointer; font-weight:600; }\n  .foot a:hover{ text-decoration:underline; }\n  :focus-visible{ outline:1px solid var(--copper); outline-offset:2px; }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n\n  .field{ position:relative; }\n  .eye-btn{\n    position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer;\n    color:var(--dim); display:flex; align-items:center; justify-content:center; transition:color .2s ease; z-index:2;\n  }\n  .eye-btn:hover{ color:var(--copper); }\n  .eye-btn svg{ width:15px; height:15px; }\n  input.has-eye{ padding-right:32px !important; }\n</style>\n</head>\n<body>\n\n<div class=\"frame\">\n  <div class=\"frame-line fl-top\"></div>\n  <div class=\"frame-line fl-right\"></div>\n  <div class=\"frame-line fl-bottom\"></div>\n  <div class=\"frame-line fl-left\"></div>\n\n  <div class=\"suite-no\">SUITE No. 04 \u00b7 MEMBER ENTRANCE</div>\n  <h1 id=\"heading\">Welcome back</h1>\n  <p class=\"sub\" id=\"subhead\">Your workshop, your commissions, your ledger.</p>\n\n  <div class=\"tabs\" id=\"tabs\">\n    <button class=\"active\" data-tab=\"signin\" type=\"button\">Sign in</button>\n    <button data-tab=\"signup\" type=\"button\">Register</button>\n    <span class=\"tab-indicator\" id=\"tabIndicator\"></span>\n  </div>\n\n  <form onsubmit=\"return false;\">\n    <div class=\"field extra\" id=\"nameField\">\n      <label for=\"nameInput\">Full name</label>\n      <input type=\"text\" placeholder=\"Jordan Rivera\" id=\"nameInput\"  autocomplete=\"name\" />\n    </div>\n    <div class=\"field\">\n      <label for=\"emailInput\">Email address</label>\n      <input type=\"email\" placeholder=\"you@company.com\" id=\"emailInput\" required  autocomplete=\"email\" />\n    </div>\n    <div class=\"field\">\n      <label for=\"pwInput\">Password</label>\n      <input type=\"password\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\" id=\"pwInput\" required  autocomplete=\"current-password\"  class=\"has-eye\" /><button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n    </div>\n    <div class=\"field extra\" id=\"confirmField\">\n      <label for=\"confirmInput\">Confirm password</label>\n      <input type=\"password\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\" id=\"confirmInput\"  autocomplete=\"new-password\" />\n    </div>\n    <div class=\"row-between\" id=\"signinOnlyRow\">\n      <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n      <a href=\"#\">Forgot password?</a>\n    </div>\n    <button class=\"enter\" type=\"submit\"><span id=\"submitLabel\">Sign in</span></button>\n  </form>\n\n  <div class=\"divider\">or continue with</div>\n  <button class=\"ghost\" type=\"button\">Google</button>\n\n  <p class=\"foot\" id=\"footNote\">New to the workshop? <a data-switch=\"signup\">Register</a></p>\n</div>\n\n<script>\n(function(){\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    if(!input) return;\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n      btn.innerHTML = showing ? '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M17.94 17.94A10.94 10.94 0 0112 19c-7 0-11-7-11-7a20.6 20.6 0 015.06-5.94M9.9 4.24A10.4 10.4 0 0112 4c7 0 11 7 11 7a20.6 20.6 0 01-2.16 3.19M14.12 14.12a3 3 0 11-4.24-4.24\"/><line x1=\"1\" y1=\"1\" x2=\"23\" y2=\"23\"/></svg>' : '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>';\n    });\n  });\n\n  var tabs = document.querySelectorAll('#tabs button[data-tab]');\n  var indicator = document.getElementById('tabIndicator');\n  var nameField = document.getElementById('nameField');\n  var confirmField = document.getElementById('confirmField');\n  var signinOnlyRow = document.getElementById('signinOnlyRow');\n  var heading = document.getElementById('heading');\n  var subhead = document.getElementById('subhead');\n  var submitLabel = document.getElementById('submitLabel');\n  var footNote = document.getElementById('footNote');\n\n  var COPY = {\n    signin: { heading:'Welcome back', sub:'Your workshop, your commissions, your ledger.', submit:'Sign in', foot:'New to the workshop? <a data-switch=\"signup\">Register</a>' },\n    signup: { heading:'Register your account', sub:'Set up your workshop profile in a minute.', submit:'Register', foot:'Already registered? <a data-switch=\"signin\">Sign in</a>' }\n  };\n\n  function positionIndicator(el){ indicator.style.width = el.offsetWidth+'px'; indicator.style.transform = 'translateX('+el.offsetLeft+'px)'; }\n  function bindSwitchLinks(){ document.querySelectorAll('[data-switch]').forEach(function(a){ a.addEventListener('click', function(e){ e.preventDefault(); setMode(a.getAttribute('data-switch')); }); }); }\n\n  function setMode(mode){\n    tabs.forEach(function(t){ t.classList.toggle('active', t.dataset.tab===mode); if(t.dataset.tab===mode) positionIndicator(t); });\n    var showExtra = mode==='signup';\n    [nameField, confirmField].forEach(function(f){ f.style.maxHeight = showExtra ? f.scrollHeight+'px' : '0px'; f.style.opacity = showExtra?1:0; });\n    signinOnlyRow.style.display = mode==='signin' ? 'flex' : 'none';\n    heading.textContent = COPY[mode].heading;\n    subhead.textContent = COPY[mode].sub;\n    submitLabel.textContent = COPY[mode].submit;\n    footNote.innerHTML = COPY[mode].foot;\n    bindSwitchLinks();\n  }\n  tabs.forEach(function(t){ t.addEventListener('click', function(){ setMode(t.dataset.tab); }); });\n  bindSwitchLinks();\n  window.addEventListener('load', function(){ positionIndicator(document.querySelector('#tabs button.active')); });\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--copper', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "the-vault", "file": "forms/the-vault.html", "title": "The Vault", "layout": "Dial-Notch Tab", "layout_key": "dial-notch-tab", "palette": "Ink & Gold", "palette_key": "ink-gold-2", "blurb": "Private holdings: a small dot marker slides along a dial track instead of a bar; a mechanical dial rotates in on load.", "n": 6, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>The Vault \u2014 Access</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;1,500&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --ink:#0c0b09; --card:#141210; --line:rgba(201,162,74,0.14); --gold:#c9a24a; --gold-bright:#e7cb8a;\n    --cream:#efe9db; --dim:#8b8270;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:\n      linear-gradient(var(--ink), var(--ink)) padding-box,\n      repeating-linear-gradient(0deg, rgba(201,162,74,0.03) 0 1px, transparent 1px 64px),\n      repeating-linear-gradient(90deg, rgba(201,162,74,0.03) 0 1px, transparent 1px 64px),\n      var(--ink);\n    color:var(--cream); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:flex; align-items:center; justify-content:center; padding:60px 24px;\n  }\n\n  .stage{ width:100%; max-width:380px; text-align:center; }\n\n  .dial-wrap{ display:flex; justify-content:center; margin-bottom:30px; }\n  .dial{ width:76px; height:76px; animation:dialIn 1.1s cubic-bezier(.65,0,.35,1) forwards; transform:rotate(-260deg); opacity:0; }\n  @keyframes dialIn{ 0%{ transform:rotate(-260deg); opacity:0; } 60%{ opacity:1; } 100%{ transform:rotate(0deg); opacity:1; } }\n  .dial circle{ fill:none; stroke:var(--gold); stroke-width:1; }\n  .dial .tick{ stroke:var(--gold); stroke-width:1.2; opacity:.6; }\n  .dial .pointer{ stroke:var(--gold-bright); stroke-width:2; stroke-linecap:round; }\n\n  h1{ font-family:'Cormorant Garamond', serif; font-weight:500; font-size:29px; margin-bottom:8px;\n    opacity:0; animation:fadeUp .8s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.55s; }\n  .sub{ font-size:13.5px; color:var(--dim); margin-bottom:32px;\n    opacity:0; animation:fadeUp .8s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.62s; }\n  @keyframes fadeUp{ to{ opacity:1; transform:none; } }\n  h1, .sub{ transform:translateY(8px); }\n\n  .panel{ text-align:left; background:var(--card); border:1px solid var(--line); padding:36px 32px; border-radius:2px;\n    opacity:0; animation:fadeUp .8s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.7s; }\n\n  .tabs{ position:relative; display:flex; gap:36px; margin-bottom:30px; justify-content:center; padding-bottom:14px; border-bottom:1px solid var(--line); }\n  .tabs button{ background:none; border:none; color:var(--dim); font-size:11px; letter-spacing:.09em; text-transform:uppercase; padding:0; cursor:pointer; transition:color .3s ease; }\n  .tabs button.active{ color:var(--gold-bright); }\n  .tab-indicator{ position:absolute; bottom:-1px; width:5px; height:5px; border-radius:50%; background:var(--gold-bright); box-shadow:0 0 8px var(--gold); transition:transform .45s cubic-bezier(.65,0,.35,1); }\n\n  .field{ position:relative; margin-bottom:24px; }\n  .field label{ position:absolute; left:0; top:11px; font-size:14px; color:var(--dim); pointer-events:none; transition:transform .3s cubic-bezier(.4,0,.2,1), font-size .3s ease, color .3s ease; transform-origin:left top; }\n  .field input{ width:100%; background:none; border:none; border-bottom:1px solid var(--line); color:var(--cream); font-size:15px; padding:10px 0; outline:none; transition:border-color .3s ease; }\n  .field .underline-accent{ position:absolute; left:0; right:0; bottom:-1px; height:1.5px; background:var(--gold-bright); transform:scaleX(0); transition:transform .4s cubic-bezier(.65,0,.35,1); box-shadow:0 0 8px var(--gold); }\n  .field input:focus ~ .underline-accent{ transform:scaleX(1); }\n  .field input:focus{ border-color:transparent; }\n  .field input:focus + label, .field input:not(:placeholder-shown) + label{ transform:translateY(-19px); font-size:11px; color:var(--gold-bright); }\n  .field input::placeholder{ color:transparent; }\n  .extra{ max-height:0; opacity:0; overflow:hidden; transition:max-height .5s cubic-bezier(.4,0,.2,1), opacity .35s ease; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--dim); margin:0 0 28px; }\n  .row-between a{ color:var(--dim); text-decoration:none; border-bottom:1px solid var(--line); }\n  .row-between a:hover{ color:var(--gold-bright); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--gold); width:13px; height:13px; }\n\n  button.enter{ position:relative; width:100%; background:var(--gold); border:none; color:#171008; font-weight:600; font-size:13.5px; letter-spacing:.02em; padding:14px; cursor:pointer; overflow:hidden; transition:filter .3s ease, transform .1s ease; }\n  button.enter:hover{ filter:brightness(1.1); }\n  button.enter:active{ transform:scale(.99); }\n  button.enter::after{ content:\"\"; position:absolute; top:0; left:-60%; width:40%; height:100%; background:linear-gradient(120deg, transparent, rgba(255,255,255,.4), transparent); transform:skewX(-20deg); transition:left .6s ease; }\n  button.enter:hover::after{ left:120%; }\n\n  .divider{ display:flex; align-items:center; gap:14px; margin:24px 0; color:var(--dim); font-size:11px; }\n  .divider::before,.divider::after{ content:\"\"; flex:1; height:1px; background:var(--line); }\n  button.ghost{ width:100%; background:none; border:1px solid var(--line); color:var(--cream); font-size:13px; padding:12px; cursor:pointer; transition:border-color .2s ease; }\n  button.ghost:hover{ border-color:var(--gold); }\n\n  .foot{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:22px; }\n  .foot a{ color:var(--gold-bright); text-decoration:none; cursor:pointer; }\n  .foot a:hover{ text-decoration:underline; }\n  :focus-visible{ outline:1px solid var(--gold-bright); outline-offset:2px; }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n\n  .field{ position:relative; }\n  .eye-btn{\n    position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer;\n    color:var(--dim); display:flex; align-items:center; justify-content:center; transition:color .2s ease; z-index:2;\n  }\n  .eye-btn:hover{ color:var(--gold-bright); }\n  .eye-btn svg{ width:15px; height:15px; }\n  input.has-eye{ padding-right:32px !important; }\n</style>\n</head>\n<body>\n\n<div class=\"stage\">\n  <div class=\"dial-wrap\">\n    <svg class=\"dial\" viewBox=\"0 0 76 76\">\n      <circle cx=\"38\" cy=\"38\" r=\"34\"/>\n      <circle cx=\"38\" cy=\"38\" r=\"27\"/>\n      <g class=\"tick\">\n        <line x1=\"38\" y1=\"6\" x2=\"38\" y2=\"12\"/>\n        <line x1=\"38\" y1=\"64\" x2=\"38\" y2=\"70\"/>\n        <line x1=\"6\" y1=\"38\" x2=\"12\" y2=\"38\"/>\n        <line x1=\"64\" y1=\"38\" x2=\"70\" y2=\"38\"/>\n      </g>\n      <line class=\"pointer\" x1=\"38\" y1=\"38\" x2=\"38\" y2=\"16\"/>\n      <circle cx=\"38\" cy=\"38\" r=\"2.4\" fill=\"#e7cb8a\" stroke=\"none\"/>\n    </svg>\n  </div>\n\n  <h1 id=\"heading\">The Vault</h1>\n  <p class=\"sub\" id=\"subhead\">Enter your credentials to unlock your holdings.</p>\n\n  <div class=\"panel\">\n    <div class=\"tabs\" id=\"tabs\">\n      <button class=\"active\" data-tab=\"signin\" type=\"button\">Sign in</button>\n      <button data-tab=\"signup\" type=\"button\">Open account</button>\n      <span class=\"tab-indicator\" id=\"tabIndicator\"></span>\n    </div>\n\n    <form onsubmit=\"return false;\">\n      <div class=\"field extra\" id=\"nameField\">\n        <input type=\"text\" placeholder=\" \" id=\"nameInput\"  autocomplete=\"name\" />\n        <label for=\"nameInput\">Full name</label>\n        <span class=\"underline-accent\"></span>\n      </div>\n      <div class=\"field\">\n        <input type=\"email\" placeholder=\" \" id=\"emailInput\" required  autocomplete=\"email\" />\n        <label for=\"emailInput\">Email address</label>\n        <span class=\"underline-accent\"></span>\n      </div>\n      <div class=\"field\">\n        <input type=\"password\" placeholder=\" \" id=\"pwInput\" required  autocomplete=\"current-password\"  class=\"has-eye\" />\n        <label for=\"pwInput\">Password</label>\n        <span class=\"underline-accent\"></span><button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n      </div>\n      <div class=\"field extra\" id=\"confirmField\">\n        <input type=\"password\" placeholder=\" \" id=\"confirmInput\"  autocomplete=\"new-password\" />\n        <label for=\"confirmInput\">Confirm password</label>\n        <span class=\"underline-accent\"></span>\n      </div>\n      <div class=\"row-between\" id=\"signinOnlyRow\">\n        <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n        <a href=\"#\">Forgot password?</a>\n      </div>\n      <button class=\"enter\" type=\"submit\"><span id=\"submitLabel\">Unlock</span></button>\n    </form>\n\n    <div class=\"divider\">or continue with</div>\n    <button class=\"ghost\" type=\"button\">Google</button>\n\n    <p class=\"foot\" id=\"footNote\">New here? <a data-switch=\"signup\">Open an account</a></p>\n  </div>\n</div>\n\n<script>\n(function(){\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    if(!input) return;\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n      btn.innerHTML = showing ? '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M17.94 17.94A10.94 10.94 0 0112 19c-7 0-11-7-11-7a20.6 20.6 0 015.06-5.94M9.9 4.24A10.4 10.4 0 0112 4c7 0 11 7 11 7a20.6 20.6 0 01-2.16 3.19M14.12 14.12a3 3 0 11-4.24-4.24\"/><line x1=\"1\" y1=\"1\" x2=\"23\" y2=\"23\"/></svg>' : '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>';\n    });\n  });\n\n  var tabs = document.querySelectorAll('#tabs button[data-tab]');\n  var indicator = document.getElementById('tabIndicator');\n  var nameField = document.getElementById('nameField');\n  var confirmField = document.getElementById('confirmField');\n  var signinOnlyRow = document.getElementById('signinOnlyRow');\n  var heading = document.getElementById('heading');\n  var subhead = document.getElementById('subhead');\n  var submitLabel = document.getElementById('submitLabel');\n  var footNote = document.getElementById('footNote');\n\n  var COPY = {\n    signin: { heading:'The Vault', sub:'Enter your credentials to unlock your holdings.', submit:'Unlock', foot:'New here? <a data-switch=\"signup\">Open an account</a>' },\n    signup: { heading:'Open an account', sub:'A minute of setup, then straight in.', submit:'Open account', foot:'Already have an account? <a data-switch=\"signin\">Sign in</a>' }\n  };\n\n  function positionIndicator(el){ indicator.style.transform = 'translateX('+(el.offsetLeft + el.offsetWidth/2 - 2.5)+'px)'; }\n  function bindSwitchLinks(){ document.querySelectorAll('[data-switch]').forEach(function(a){ a.addEventListener('click', function(e){ e.preventDefault(); setMode(a.getAttribute('data-switch')); }); }); }\n\n  function setMode(mode){\n    tabs.forEach(function(t){ t.classList.toggle('active', t.dataset.tab===mode); if(t.dataset.tab===mode) positionIndicator(t); });\n    var showExtra = mode==='signup';\n    [nameField, confirmField].forEach(function(f){ f.style.maxHeight = showExtra ? f.scrollHeight+'px' : '0px'; f.style.opacity = showExtra?1:0; });\n    signinOnlyRow.style.display = mode==='signin' ? 'flex' : 'none';\n    heading.textContent = COPY[mode].heading;\n    subhead.textContent = COPY[mode].sub;\n    submitLabel.textContent = COPY[mode].submit;\n    footNote.innerHTML = COPY[mode].foot;\n    bindSwitchLinks();\n  }\n  tabs.forEach(function(t){ t.addEventListener('click', function(){ setMode(t.dataset.tab); }); });\n  bindSwitchLinks();\n  window.addEventListener('load', function(){ positionIndicator(document.querySelector('#tabs button.active')); });\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--gold', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "ambergris", "file": "forms/ambergris.html", "title": "Ambergris & Co.", "layout": "Pill Tab + Liquid Button", "layout_key": "pill-liquid", "palette": "Amber & Ink", "palette_key": "amber-ink", "blurb": "A perfumery: the button fills upward like liquid on hover, tying back to the vial that fills on load.", "n": 7, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Ambergris \u2014 Member Sign In</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;1,500&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --ink:#160f09; --card:#1c140c; --line:rgba(212,158,79,0.16); --amber:#d49e4f; --amber-bright:#f0c581;\n    --cream:#f1e6d3; --dim:#9c8a6e;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:radial-gradient(ellipse at 50% -10%, rgba(212,158,79,0.12), transparent 55%), var(--ink);\n    color:var(--cream); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:flex; align-items:center; justify-content:center; padding:60px 24px;\n  }\n  .stage{ width:100%; max-width:380px; text-align:center; }\n\n  .vial-wrap{ display:flex; justify-content:center; margin-bottom:22px; }\n  .vial{ width:46px; height:80px; }\n  .vial .glass{ fill:none; stroke:var(--line); stroke-width:1.5; }\n  .vial .liquid{ fill:var(--amber); opacity:.85; }\n  .vial .liquid-clip{ animation:fill 1.4s cubic-bezier(.65,0,.35,1) forwards; animation-delay:.2s; }\n  @keyframes fill{ from{ transform:translateY(46px); } to{ transform:translateY(0); } }\n  .vial .stopper{ fill:var(--amber-bright); }\n\n  .brand{ font-size:11px; letter-spacing:.22em; color:var(--amber); margin-bottom:14px;\n    opacity:0; animation:fadeIn .7s ease forwards; animation-delay:.9s; }\n  h1{ font-family:'Cormorant Garamond', serif; font-weight:500; font-style:italic; font-size:30px; margin-bottom:8px;\n    opacity:0; animation:fadeUp .8s cubic-bezier(.16,1,.3,1) forwards; animation-delay:1s; }\n  .sub{ font-size:13.5px; color:var(--dim); margin-bottom:30px;\n    opacity:0; animation:fadeUp .8s cubic-bezier(.16,1,.3,1) forwards; animation-delay:1.06s; }\n  @keyframes fadeIn{ to{ opacity:1; } }\n  @keyframes fadeUp{ to{ opacity:1; transform:none; } }\n  h1, .sub{ transform:translateY(8px); }\n\n  .panel{ text-align:left; background:var(--card); border:1px solid var(--line); padding:36px 32px; border-radius:3px;\n    opacity:0; animation:fadeUp .8s cubic-bezier(.16,1,.3,1) forwards; animation-delay:1.12s; }\n\n  .tabs{ position:relative; display:flex; gap:4px; margin-bottom:28px; background:rgba(0,0,0,0.18); border:1px solid var(--line); border-radius:999px; padding:4px; }\n  .tabs button{ position:relative; z-index:2; flex:1; background:none; border:none; color:var(--dim); font-size:12px; font-weight:600; padding:9px 0; cursor:pointer; transition:color .3s ease; border-radius:999px; }\n  .tabs button.active{ color:#1c140c; }\n  .tab-indicator{ position:absolute; top:4px; bottom:4px; z-index:1; border-radius:999px; background:var(--amber); box-shadow:0 4px 14px -4px rgba(212,158,79,0.5); transition:transform .45s cubic-bezier(.65,0,.35,1), width .45s cubic-bezier(.65,0,.35,1); }\n\n  .field{ position:relative; margin-bottom:24px; }\n  .field label{ position:absolute; left:0; top:11px; font-size:14px; color:var(--dim); pointer-events:none; transition:transform .3s cubic-bezier(.4,0,.2,1), font-size .3s ease, color .3s ease; transform-origin:left top; }\n  .field input{ width:100%; background:none; border:none; border-bottom:1px solid var(--line); color:var(--cream); font-size:15px; padding:10px 0; outline:none; transition:border-color .3s ease; }\n  .field .underline-accent{ position:absolute; left:0; right:0; bottom:-1px; height:1.5px; background:var(--amber-bright); transform:scaleX(0); transition:transform .4s cubic-bezier(.65,0,.35,1); box-shadow:0 0 8px var(--amber); }\n  .field input:focus ~ .underline-accent{ transform:scaleX(1); }\n  .field input:focus{ border-color:transparent; }\n  .field input:focus + label, .field input:not(:placeholder-shown) + label{ transform:translateY(-19px); font-size:11px; color:var(--amber-bright); }\n  .field input::placeholder{ color:transparent; }\n  .extra{ max-height:0; opacity:0; overflow:hidden; transition:max-height .5s cubic-bezier(.4,0,.2,1), opacity .35s ease; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--dim); margin:0 0 28px; }\n  .row-between a{ color:var(--dim); text-decoration:none; border-bottom:1px solid var(--line); }\n  .row-between a:hover{ color:var(--amber-bright); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--amber); width:13px; height:13px; }\n\n  button.enter{ position:relative; width:100%; background:transparent; border:1px solid var(--amber); color:var(--amber-bright);\n    font-family:'Cormorant Garamond', serif; font-style:italic; font-size:18px; padding:14px; cursor:pointer; overflow:hidden; isolation:isolate; transition:color .5s ease; }\n  button.enter::before{ content:\"\"; position:absolute; left:0; right:0; bottom:0; height:0%; background:linear-gradient(180deg, var(--amber-bright), var(--amber)); transition:height .5s cubic-bezier(.65,0,.35,1); z-index:-1; }\n  button.enter:hover{ color:#1c140c; }\n  button.enter:hover::before{ height:100%; }\n  button.enter:active{ transform:scale(.99); }\n\n  .divider{ display:flex; align-items:center; gap:14px; margin:24px 0; color:var(--dim); font-size:11px; }\n  .divider::before,.divider::after{ content:\"\"; flex:1; height:1px; background:var(--line); }\n  button.ghost{ width:100%; background:none; border:1px solid var(--line); color:var(--cream); font-size:13px; padding:12px; cursor:pointer; transition:border-color .2s ease; }\n  button.ghost:hover{ border-color:var(--amber); }\n\n  .foot{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:22px; }\n  .foot a{ color:var(--amber-bright); text-decoration:none; cursor:pointer; }\n  .foot a:hover{ text-decoration:underline; }\n  :focus-visible{ outline:1px solid var(--amber-bright); outline-offset:2px; }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n\n  .field{ position:relative; }\n  .eye-btn{\n    position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer;\n    color:var(--dim); display:flex; align-items:center; justify-content:center; transition:color .2s ease; z-index:2;\n  }\n  .eye-btn:hover{ color:var(--amber-bright); }\n  .eye-btn svg{ width:15px; height:15px; }\n  input.has-eye{ padding-right:32px !important; }\n</style>\n</head>\n<body>\n\n<div class=\"stage\">\n  <div class=\"vial-wrap\">\n    <svg class=\"vial\" viewBox=\"0 0 46 80\">\n      <defs><clipPath id=\"vialClip\"><rect x=\"10\" y=\"20\" width=\"26\" height=\"50\" rx=\"4\"/></clipPath></defs>\n      <rect class=\"glass\" x=\"10\" y=\"20\" width=\"26\" height=\"50\" rx=\"4\"/>\n      <rect class=\"glass\" x=\"18\" y=\"6\" width=\"10\" height=\"16\"/>\n      <rect class=\"stopper\" x=\"16\" y=\"2\" width=\"14\" height=\"6\" rx=\"1\"/>\n      <g clip-path=\"url(#vialClip)\">\n        <rect class=\"liquid liquid-clip\" x=\"10\" y=\"34\" width=\"26\" height=\"36\"/>\n      </g>\n    </svg>\n  </div>\n\n  <div class=\"brand\">AMBERGRIS &amp; CO.</div>\n  <h1 id=\"heading\">Member sign in</h1>\n  <p class=\"sub\" id=\"subhead\">Your fragrance profile and reserve list.</p>\n\n  <div class=\"panel\">\n    <div class=\"tabs\" id=\"tabs\">\n      <button class=\"active\" data-tab=\"signin\" type=\"button\">Sign in</button>\n      <button data-tab=\"signup\" type=\"button\">Join</button>\n      <span class=\"tab-indicator\" id=\"tabIndicator\"></span>\n    </div>\n\n    <form onsubmit=\"return false;\">\n      <div class=\"field extra\" id=\"nameField\">\n        <input type=\"text\" placeholder=\" \" id=\"nameInput\"  autocomplete=\"name\" />\n        <label for=\"nameInput\">Full name</label>\n        <span class=\"underline-accent\"></span>\n      </div>\n      <div class=\"field\">\n        <input type=\"email\" placeholder=\" \" id=\"emailInput\" required  autocomplete=\"email\" />\n        <label for=\"emailInput\">Email address</label>\n        <span class=\"underline-accent\"></span>\n      </div>\n      <div class=\"field\">\n        <input type=\"password\" placeholder=\" \" id=\"pwInput\" required  autocomplete=\"current-password\"  class=\"has-eye\" />\n        <label for=\"pwInput\">Password</label>\n        <span class=\"underline-accent\"></span><button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n      </div>\n      <div class=\"field extra\" id=\"confirmField\">\n        <input type=\"password\" placeholder=\" \" id=\"confirmInput\"  autocomplete=\"new-password\" />\n        <label for=\"confirmInput\">Confirm password</label>\n        <span class=\"underline-accent\"></span>\n      </div>\n      <div class=\"row-between\" id=\"signinOnlyRow\">\n        <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n        <a href=\"#\">Forgot password?</a>\n      </div>\n      <button class=\"enter\" type=\"submit\"><span id=\"submitLabel\">Enter</span></button>\n    </form>\n\n    <div class=\"divider\">or continue with</div>\n    <button class=\"ghost\" type=\"button\">Google</button>\n\n    <p class=\"foot\" id=\"footNote\">New here? <a data-switch=\"signup\">Join Ambergris</a></p>\n  </div>\n</div>\n\n<script>\n(function(){\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    if(!input) return;\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n      btn.innerHTML = showing ? '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M17.94 17.94A10.94 10.94 0 0112 19c-7 0-11-7-11-7a20.6 20.6 0 015.06-5.94M9.9 4.24A10.4 10.4 0 0112 4c7 0 11 7 11 7a20.6 20.6 0 01-2.16 3.19M14.12 14.12a3 3 0 11-4.24-4.24\"/><line x1=\"1\" y1=\"1\" x2=\"23\" y2=\"23\"/></svg>' : '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>';\n    });\n  });\n\n  var tabs = document.querySelectorAll('#tabs button[data-tab]');\n  var indicator = document.getElementById('tabIndicator');\n  var nameField = document.getElementById('nameField');\n  var confirmField = document.getElementById('confirmField');\n  var signinOnlyRow = document.getElementById('signinOnlyRow');\n  var heading = document.getElementById('heading');\n  var subhead = document.getElementById('subhead');\n  var submitLabel = document.getElementById('submitLabel');\n  var footNote = document.getElementById('footNote');\n\n  var COPY = {\n    signin: { heading:'Member sign in', sub:'Your fragrance profile and reserve list.', submit:'Enter', foot:'New here? <a data-switch=\"signup\">Join Ambergris</a>' },\n    signup: { heading:'Join Ambergris', sub:'Create a profile to reserve limited pours.', submit:'Join', foot:'Already a member? <a data-switch=\"signin\">Sign in</a>' }\n  };\n\n  function positionIndicator(el){ indicator.style.width = el.offsetWidth+'px'; indicator.style.transform = 'translateX('+el.offsetLeft+'px)'; }\n  function bindSwitchLinks(){ document.querySelectorAll('[data-switch]').forEach(function(a){ a.addEventListener('click', function(e){ e.preventDefault(); setMode(a.getAttribute('data-switch')); }); }); }\n\n  function setMode(mode){\n    tabs.forEach(function(t){ t.classList.toggle('active', t.dataset.tab===mode); if(t.dataset.tab===mode) positionIndicator(t); });\n    var showExtra = mode==='signup';\n    [nameField, confirmField].forEach(function(f){ f.style.maxHeight = showExtra ? f.scrollHeight+'px' : '0px'; f.style.opacity = showExtra?1:0; });\n    signinOnlyRow.style.display = mode==='signin' ? 'flex' : 'none';\n    heading.textContent = COPY[mode].heading;\n    subhead.textContent = COPY[mode].sub;\n    submitLabel.textContent = COPY[mode].submit;\n    footNote.innerHTML = COPY[mode].foot;\n    bindSwitchLinks();\n  }\n  tabs.forEach(function(t){ t.addEventListener('click', function(){ setMode(t.dataset.tab); }); });\n  bindSwitchLinks();\n  window.addEventListener('load', function(){ positionIndicator(document.querySelector('#tabs button.active')); });\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--amber', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "marbleworks", "file": "forms/marbleworks.html", "title": "Marbleworks Studio", "layout": "Quiet Toggle + Seam Split", "layout_key": "quiet-seam", "palette": "Verdigris & Stone", "palette_key": "verdigris-stone", "blurb": "An architecture studio: the card opens along a horizontal seam; static labels, plain-text mode switch, solid button.", "n": 8, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Marbleworks \u2014 Studio Sign In</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --stone:#f2f0ec; --card:#ffffff; --line:#dcd8d0; --verdigris:#4f7a70; --verdigris-bright:#6b9c8f;\n    --ink:#242220; --dim:#82796f;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--stone); color:var(--ink); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:flex; align-items:center; justify-content:center; padding:60px 24px; overflow:hidden;\n  }\n\n  .seam-wrap{ position:relative; width:100%; max-width:400px; }\n  .seam-top, .seam-bottom{\n    position:relative; background:var(--card); border:1px solid var(--line);\n    animation:none;\n  }\n  .seam-top{ padding:44px 38px 24px; border-bottom:none; transform:translateY(0); animation:openUp .7s cubic-bezier(.65,0,.35,1) forwards; animation-delay:.15s; }\n  .seam-bottom{ padding:24px 38px 40px; border-top:none; animation:openDown .7s cubic-bezier(.65,0,.35,1) forwards; animation-delay:.15s; }\n  @keyframes openUp{ from{ transform:translateY(40px); } to{ transform:translateY(0); } }\n  @keyframes openDown{ from{ transform:translateY(-40px); } to{ transform:translateY(0); } }\n  .seam-wrap{ opacity:0; animation:fadeIn .3s ease forwards; }\n  @keyframes fadeIn{ to{ opacity:1; } }\n\n  .seam-line{ height:1px; background:linear-gradient(90deg, transparent, var(--verdigris), transparent);\n    transform:scaleX(0); animation:growSeam .6s cubic-bezier(.65,0,.35,1) forwards; animation-delay:.75s; }\n  @keyframes growSeam{ to{ transform:scaleX(1); } }\n\n  .brand{ font-size:11px; letter-spacing:.18em; color:var(--verdigris); margin-bottom:16px;\n    opacity:0; animation:fadeUp .6s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.5s; }\n  h1{ font-family:'Fraunces', serif; font-weight:600; font-size:27px; margin-bottom:8px;\n    opacity:0; animation:fadeUp .6s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.56s; }\n  .sub{ font-size:13.5px; color:var(--dim); margin-bottom:8px;\n    opacity:0; animation:fadeUp .6s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.6s; }\n  @keyframes fadeUp{ to{ opacity:1; transform:none; } }\n  .brand, h1, .sub{ transform:translateY(6px); }\n\n  .tabs{ display:flex; gap:26px; margin-top:26px;\n    opacity:0; animation:fadeUp .6s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.85s; }\n  .tabs button{ background:none; border:1.5px solid transparent; color:var(--dim); font-size:12px; font-weight:600; padding:6px 0 8px; cursor:pointer; transition:color .3s ease, border-color .3s ease; }\n  .tabs button.active{ color:var(--ink); border-bottom-color:var(--verdigris); }\n\n  form{ opacity:0; animation:fadeUp .6s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.95s; margin-top:24px; }\n\n  .field{ position:relative; margin-bottom:20px; }\n  .field label{ display:block; font-size:11px; letter-spacing:.04em; color:var(--dim); margin-bottom:6px; }\n  .field input{ width:100%; background:var(--stone); border:1.5px solid var(--line); color:var(--ink); font-size:15px; padding:10px 12px; outline:none; transition:border-color .2s ease; }\n  .field input:focus{ border-color:var(--verdigris); }\n  .field input::placeholder{ color:var(--dim); opacity:.55; }\n  .extra{ max-height:0; opacity:0; overflow:hidden; transition:max-height .5s cubic-bezier(.4,0,.2,1), opacity .35s ease; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--dim); margin:0 0 24px; }\n  .row-between a{ color:var(--dim); text-decoration:none; border-bottom:1px solid var(--line); }\n  .row-between a:hover{ color:var(--verdigris); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--verdigris); width:13px; height:13px; }\n\n  button.enter{ width:100%; background:var(--verdigris); border:none; color:var(--stone); font-size:13.5px; font-weight:600; padding:14px; cursor:pointer; transition:background .25s ease, transform .1s ease; }\n  button.enter:hover{ background:#5c8a7f; }\n  button.enter:active{ transform:scale(.99); }\n\n  .divider{ display:flex; align-items:center; gap:14px; margin:24px 0; color:var(--dim); font-size:11px; }\n  .divider::before,.divider::after{ content:\"\"; flex:1; height:1px; background:var(--line); }\n  button.ghost{ width:100%; background:none; border:1px solid var(--line); color:var(--ink); font-size:13px; padding:12px; cursor:pointer; transition:border-color .2s ease; }\n  button.ghost:hover{ border-color:var(--verdigris); }\n\n  .foot{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:22px; }\n  .foot a{ color:var(--verdigris); text-decoration:none; cursor:pointer; font-weight:600; }\n  .foot a:hover{ text-decoration:underline; }\n  :focus-visible{ outline:1px solid var(--verdigris); outline-offset:2px; }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n\n  .field{ position:relative; }\n  .eye-btn{\n    position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer;\n    color:var(--dim); display:flex; align-items:center; justify-content:center; transition:color .2s ease; z-index:2;\n  }\n  .eye-btn:hover{ color:var(--verdigris); }\n  .eye-btn svg{ width:15px; height:15px; }\n  input.has-eye{ padding-right:32px !important; }\n</style>\n</head>\n<body>\n\n<div class=\"seam-wrap\">\n  <div class=\"seam-top\">\n    <div class=\"brand\">MARBLEWORKS STUDIO</div>\n    <h1 id=\"heading\">Studio sign in</h1>\n    <p class=\"sub\" id=\"subhead\">Drawings, schedules, and site notes.</p>\n  </div>\n  <div class=\"seam-line\"></div>\n  <div class=\"seam-bottom\">\n    <div class=\"tabs\" id=\"tabs\">\n      <button class=\"active\" data-tab=\"signin\" type=\"button\">Sign in</button>\n      <button data-tab=\"signup\" type=\"button\">Create account</button>\n    </div>\n\n    <form onsubmit=\"return false;\">\n      <div class=\"field extra\" id=\"nameField\">\n        <label for=\"nameInput\">Full name</label>\n        <input type=\"text\" placeholder=\"Jordan Rivera\" id=\"nameInput\"  autocomplete=\"name\" />\n      </div>\n      <div class=\"field\">\n        <label for=\"emailInput\">Email address</label>\n        <input type=\"email\" placeholder=\"you@company.com\" id=\"emailInput\" required  autocomplete=\"email\" />\n      </div>\n      <div class=\"field\">\n        <label for=\"pwInput\">Password</label>\n        <input type=\"password\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\" id=\"pwInput\" required  autocomplete=\"current-password\"  class=\"has-eye\" /><button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n      </div>\n      <div class=\"field extra\" id=\"confirmField\">\n        <label for=\"confirmInput\">Confirm password</label>\n        <input type=\"password\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\" id=\"confirmInput\"  autocomplete=\"new-password\" />\n      </div>\n      <div class=\"row-between\" id=\"signinOnlyRow\">\n        <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n        <a href=\"#\">Forgot password?</a>\n      </div>\n      <button class=\"enter\" type=\"submit\"><span id=\"submitLabel\">Sign in</span></button>\n    </form>\n\n    <div class=\"divider\">or continue with</div>\n    <button class=\"ghost\" type=\"button\">Google</button>\n\n    <p class=\"foot\" id=\"footNote\">New to the studio? <a data-switch=\"signup\">Create an account</a></p>\n  </div>\n</div>\n\n<script>\n(function(){\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    if(!input) return;\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n      btn.innerHTML = showing ? '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M17.94 17.94A10.94 10.94 0 0112 19c-7 0-11-7-11-7a20.6 20.6 0 015.06-5.94M9.9 4.24A10.4 10.4 0 0112 4c7 0 11 7 11 7a20.6 20.6 0 01-2.16 3.19M14.12 14.12a3 3 0 11-4.24-4.24\"/><line x1=\"1\" y1=\"1\" x2=\"23\" y2=\"23\"/></svg>' : '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>';\n    });\n  });\n\n  var tabs = document.querySelectorAll('#tabs button[data-tab]');\n  var nameField = document.getElementById('nameField');\n  var confirmField = document.getElementById('confirmField');\n  var signinOnlyRow = document.getElementById('signinOnlyRow');\n  var heading = document.getElementById('heading');\n  var subhead = document.getElementById('subhead');\n  var submitLabel = document.getElementById('submitLabel');\n  var footNote = document.getElementById('footNote');\n\n  var COPY = {\n    signin: { heading:'Studio sign in', sub:'Drawings, schedules, and site notes.', submit:'Sign in', foot:'New to the studio? <a data-switch=\"signup\">Create an account</a>' },\n    signup: { heading:'Create your account', sub:'Set up studio access in under a minute.', submit:'Create account', foot:'Already have an account? <a data-switch=\"signin\">Sign in</a>' }\n  };\n\n  function bindSwitchLinks(){ document.querySelectorAll('[data-switch]').forEach(function(a){ a.addEventListener('click', function(e){ e.preventDefault(); setMode(a.getAttribute('data-switch')); }); }); }\n\n  function setMode(mode){\n    tabs.forEach(function(t){ t.classList.toggle('active', t.dataset.tab===mode); });\n    var showExtra = mode==='signup';\n    [nameField, confirmField].forEach(function(f){ f.style.maxHeight = showExtra ? f.scrollHeight+'px' : '0px'; f.style.opacity = showExtra?1:0; });\n    signinOnlyRow.style.display = mode==='signin' ? 'flex' : 'none';\n    heading.textContent = COPY[mode].heading;\n    subhead.textContent = COPY[mode].sub;\n    submitLabel.textContent = COPY[mode].submit;\n    footNote.innerHTML = COPY[mode].foot;\n    bindSwitchLinks();\n  }\n  tabs.forEach(function(t){ t.addEventListener('click', function(){ setMode(t.dataset.tab); }); });\n  bindSwitchLinks();\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--verdigris', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "hour-and-co", "file": "forms/hour-and-co.html", "title": "Hour & Co.", "layout": "Underline Tab + Radial Button", "layout_key": "underline-radial", "palette": "Ink & Gold", "palette_key": "ink-gold-3", "blurb": "A watchmaker: a fine gold hand sweeps continuously behind the panel; the button fills via a circle expanding from its center.", "n": 9, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Hour &amp; Co. \u2014 Client Sign In</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;1,500&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --ink:#0a0a0b; --card:#131315; --line:rgba(201,162,74,0.14); --gold:#c9a24a; --gold-bright:#e7cb8a;\n    --cream:#eeece7; --dim:#84807a;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--ink); color:var(--cream); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:flex; align-items:center; justify-content:center; padding:60px 24px; position:relative; overflow:hidden;\n  }\n\n  .dial-bg{ position:fixed; width:900px; height:900px; border-radius:50%; border:1px solid var(--line); top:50%; left:50%;\n    transform:translate(-50%,-50%); opacity:.5; }\n  .dial-bg::before{ content:\"\"; position:absolute; inset:60px; border-radius:50%; border:1px solid var(--line); }\n  .sweep{ position:fixed; top:50%; left:50%; width:1px; height:450px; background:linear-gradient(to top, var(--gold), transparent 60%);\n    transform-origin:top center; animation:sweep 40s linear infinite; opacity:.55; }\n  @keyframes sweep{ from{ transform:translate(-50%,0) rotate(0deg); } to{ transform:translate(-50%,0) rotate(360deg); } }\n\n  .stage{ position:relative; z-index:1; width:100%; max-width:380px;\n    opacity:0; transform:translateY(14px); animation:reveal .9s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.2s; }\n  @keyframes reveal{ to{ opacity:1; transform:none; } }\n\n  .brand{ font-size:11px; letter-spacing:.22em; color:var(--gold); text-align:center; margin-bottom:16px; }\n  h1{ font-family:'Cormorant Garamond', serif; font-weight:500; font-size:29px; text-align:center; margin-bottom:8px; }\n  .sub{ font-size:13.5px; color:var(--dim); text-align:center; margin-bottom:34px; }\n\n  .panel{ background:var(--card); border:1px solid var(--line); padding:36px 32px; border-radius:2px; }\n\n  .tabs{ position:relative; display:flex; gap:24px; margin-bottom:28px; border-bottom:1px solid var(--line); }\n  .tabs button{ background:none; border:none; color:var(--dim); font-size:12.5px; font-weight:500; padding:0 0 12px; cursor:pointer; transition:color .3s ease; }\n  .tabs button.active{ color:var(--gold-bright); }\n  .tab-indicator{ position:absolute; bottom:-1px; height:1.5px; background:var(--gold-bright); box-shadow:0 0 8px var(--gold); transition:transform .5s cubic-bezier(.65,0,.35,1), width .5s cubic-bezier(.65,0,.35,1); }\n\n  .field{ position:relative; margin-bottom:24px; }\n  .field label{ position:absolute; left:0; top:11px; font-size:14px; color:var(--dim); pointer-events:none; transition:transform .3s cubic-bezier(.4,0,.2,1), font-size .3s ease, color .3s ease; transform-origin:left top; }\n  .field input{ width:100%; background:none; border:none; border-bottom:1px solid var(--line); color:var(--cream); font-size:15px; padding:10px 0; outline:none; transition:border-color .3s ease; }\n  .field .underline-accent{ position:absolute; left:0; right:0; bottom:-1px; height:1.5px; background:var(--gold-bright); transform:scaleX(0); transition:transform .4s cubic-bezier(.65,0,.35,1); box-shadow:0 0 8px var(--gold); }\n  .field input:focus ~ .underline-accent{ transform:scaleX(1); }\n  .field input:focus{ border-color:transparent; }\n  .field input:focus + label, .field input:not(:placeholder-shown) + label{ transform:translateY(-19px); font-size:11px; color:var(--gold-bright); }\n  .field input::placeholder{ color:transparent; }\n  .extra{ max-height:0; opacity:0; overflow:hidden; transition:max-height .5s cubic-bezier(.4,0,.2,1), opacity .35s ease; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--dim); margin:0 0 28px; }\n  .row-between a{ color:var(--dim); text-decoration:none; border-bottom:1px solid var(--line); }\n  .row-between a:hover{ color:var(--gold-bright); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--gold); width:13px; height:13px; }\n\n  button.enter{ position:relative; width:100%; background:transparent; border:1.5px solid var(--gold); color:var(--gold-bright); font-weight:600; font-size:13.5px; letter-spacing:.02em; padding:14px; cursor:pointer; overflow:hidden; isolation:isolate; transition:color .4s ease .1s; }\n  button.enter::before{ content:\"\"; position:absolute; left:50%; top:50%; width:0; height:0; border-radius:50%; background:var(--gold); transform:translate(-50%,-50%); transition:width .5s cubic-bezier(.65,0,.35,1), height .5s cubic-bezier(.65,0,.35,1); z-index:-1; }\n  button.enter:hover{ color:#171008; }\n  button.enter:hover::before{ width:340px; height:340px; }\n  button.enter:active{ transform:scale(.99); }\n\n  .divider{ display:flex; align-items:center; gap:14px; margin:24px 0; color:var(--dim); font-size:11px; }\n  .divider::before,.divider::after{ content:\"\"; flex:1; height:1px; background:var(--line); }\n  button.ghost{ width:100%; background:none; border:1px solid var(--line); color:var(--cream); font-size:13px; padding:12px; cursor:pointer; transition:border-color .2s ease; }\n  button.ghost:hover{ border-color:var(--gold); }\n\n  .foot{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:22px; }\n  .foot a{ color:var(--gold-bright); text-decoration:none; cursor:pointer; }\n  .foot a:hover{ text-decoration:underline; }\n  :focus-visible{ outline:1px solid var(--gold-bright); outline-offset:2px; }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } .sweep{ display:none; } }\n\n  .field{ position:relative; }\n  .eye-btn{\n    position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer;\n    color:var(--dim); display:flex; align-items:center; justify-content:center; transition:color .2s ease; z-index:2;\n  }\n  .eye-btn:hover{ color:var(--gold-bright); }\n  .eye-btn svg{ width:15px; height:15px; }\n  input.has-eye{ padding-right:32px !important; }\n</style>\n</head>\n<body>\n\n<div class=\"dial-bg\"></div>\n<div class=\"sweep\"></div>\n\n<div class=\"stage\">\n  <div class=\"brand\">HOUR &amp; CO.</div>\n  <h1 id=\"heading\">Client sign in</h1>\n  <p class=\"sub\" id=\"subhead\">Your collection, service history, and provenance.</p>\n\n  <div class=\"panel\">\n    <div class=\"tabs\" id=\"tabs\">\n      <button class=\"active\" data-tab=\"signin\" type=\"button\">Sign in</button>\n      <button data-tab=\"signup\" type=\"button\">Register</button>\n      <span class=\"tab-indicator\" id=\"tabIndicator\"></span>\n    </div>\n\n    <form onsubmit=\"return false;\">\n      <div class=\"field extra\" id=\"nameField\">\n        <input type=\"text\" placeholder=\" \" id=\"nameInput\"  autocomplete=\"name\" />\n        <label for=\"nameInput\">Full name</label>\n        <span class=\"underline-accent\"></span>\n      </div>\n      <div class=\"field\">\n        <input type=\"email\" placeholder=\" \" id=\"emailInput\" required  autocomplete=\"email\" />\n        <label for=\"emailInput\">Email address</label>\n        <span class=\"underline-accent\"></span>\n      </div>\n      <div class=\"field\">\n        <input type=\"password\" placeholder=\" \" id=\"pwInput\" required  autocomplete=\"current-password\"  class=\"has-eye\" />\n        <label for=\"pwInput\">Password</label>\n        <span class=\"underline-accent\"></span><button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n      </div>\n      <div class=\"field extra\" id=\"confirmField\">\n        <input type=\"password\" placeholder=\" \" id=\"confirmInput\"  autocomplete=\"new-password\" />\n        <label for=\"confirmInput\">Confirm password</label>\n        <span class=\"underline-accent\"></span>\n      </div>\n      <div class=\"row-between\" id=\"signinOnlyRow\">\n        <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n        <a href=\"#\">Forgot password?</a>\n      </div>\n      <button class=\"enter\" type=\"submit\"><span id=\"submitLabel\">Sign in</span></button>\n    </form>\n\n    <div class=\"divider\">or continue with</div>\n    <button class=\"ghost\" type=\"button\">Google</button>\n\n    <p class=\"foot\" id=\"footNote\">New client? <a data-switch=\"signup\">Register</a></p>\n  </div>\n</div>\n\n<script>\n(function(){\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    if(!input) return;\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n      btn.innerHTML = showing ? '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M17.94 17.94A10.94 10.94 0 0112 19c-7 0-11-7-11-7a20.6 20.6 0 015.06-5.94M9.9 4.24A10.4 10.4 0 0112 4c7 0 11 7 11 7a20.6 20.6 0 01-2.16 3.19M14.12 14.12a3 3 0 11-4.24-4.24\"/><line x1=\"1\" y1=\"1\" x2=\"23\" y2=\"23\"/></svg>' : '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>';\n    });\n  });\n\n  var tabs = document.querySelectorAll('#tabs button[data-tab]');\n  var indicator = document.getElementById('tabIndicator');\n  var nameField = document.getElementById('nameField');\n  var confirmField = document.getElementById('confirmField');\n  var signinOnlyRow = document.getElementById('signinOnlyRow');\n  var heading = document.getElementById('heading');\n  var subhead = document.getElementById('subhead');\n  var submitLabel = document.getElementById('submitLabel');\n  var footNote = document.getElementById('footNote');\n\n  var COPY = {\n    signin: { heading:'Client sign in', sub:'Your collection, service history, and provenance.', submit:'Sign in', foot:'New client? <a data-switch=\"signup\">Register</a>' },\n    signup: { heading:'Register as a client', sub:'A minute of setup, then straight to your collection.', submit:'Register', foot:'Already registered? <a data-switch=\"signin\">Sign in</a>' }\n  };\n\n  function positionIndicator(el){ indicator.style.width = el.offsetWidth+'px'; indicator.style.transform = 'translateX('+el.offsetLeft+'px)'; }\n  function bindSwitchLinks(){ document.querySelectorAll('[data-switch]').forEach(function(a){ a.addEventListener('click', function(e){ e.preventDefault(); setMode(a.getAttribute('data-switch')); }); }); }\n\n  function setMode(mode){\n    tabs.forEach(function(t){ t.classList.toggle('active', t.dataset.tab===mode); if(t.dataset.tab===mode) positionIndicator(t); });\n    var showExtra = mode==='signup';\n    [nameField, confirmField].forEach(function(f){ f.style.maxHeight = showExtra ? f.scrollHeight+'px' : '0px'; f.style.opacity = showExtra?1:0; });\n    signinOnlyRow.style.display = mode==='signin' ? 'flex' : 'none';\n    heading.textContent = COPY[mode].heading;\n    subhead.textContent = COPY[mode].sub;\n    submitLabel.textContent = COPY[mode].submit;\n    footNote.innerHTML = COPY[mode].foot;\n    bindSwitchLinks();\n  }\n  tabs.forEach(function(t){ t.addEventListener('click', function(){ setMode(t.dataset.tab); }); });\n  bindSwitchLinks();\n  window.addEventListener('load', function(){ positionIndicator(document.querySelector('#tabs button.active')); });\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--gold', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "ink-and-linen", "file": "forms/ink-and-linen.html", "title": "Ink & Linen Co.", "layout": "Quiet Toggle + Static Labels", "layout_key": "quiet-static-2", "palette": "Navy & Linen", "palette_key": "navy-linen", "blurb": "A letterpress stationer: the header stamps into focus on load; static labels, plain-text mode switch, solid button.", "n": 10, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Ink &amp; Linen \u2014 Sign In</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,600;1,9..144,500&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --linen:#f4efe4; --card:#fbf8f0; --line:#ddd4bd; --navy:#1f2b46; --navy-bright:#33456e;\n    --ink:#241f18; --dim:#8a8069;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background-color:var(--linen);\n    background-image:\n      repeating-linear-gradient(0deg, rgba(36,31,24,0.015) 0 1px, transparent 1px 3px),\n      repeating-linear-gradient(90deg, rgba(36,31,24,0.015) 0 1px, transparent 1px 3px);\n    color:var(--ink); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:flex; align-items:center; justify-content:center; padding:60px 24px;\n  }\n\n  .stage{ width:100%; max-width:390px; text-align:center; }\n\n  .stamp{ opacity:0; filter:blur(6px); transform:scale(1.12);\n    animation:press .5s cubic-bezier(.2,.9,.3,1.1) forwards; animation-delay:.15s; }\n  @keyframes press{ to{ opacity:1; filter:blur(0); transform:scale(1); } }\n\n  .brand{ font-size:11px; letter-spacing:.2em; color:var(--navy); margin-bottom:14px; }\n  h1{ font-family:'Fraunces', serif; font-weight:600; font-size:32px; margin-bottom:10px; }\n  .sub{ font-size:13.5px; color:var(--dim); margin-bottom:8px; }\n\n  .rule{ height:1px; background:var(--line); margin:26px 0 30px; transform:scaleX(0); transform-origin:center;\n    animation:growRule .6s cubic-bezier(.65,0,.35,1) forwards; animation-delay:.55s; }\n  @keyframes growRule{ to{ transform:scaleX(1); } }\n\n  .panel{ text-align:left; opacity:0; animation:fadeUp .7s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.6s; }\n  @keyframes fadeUp{ to{ opacity:1; transform:none; } }\n  .panel{ transform:translateY(8px); }\n\n  .tabs{ display:flex; gap:24px; margin-bottom:28px; }\n  .tabs button{ background:none; border:1.5px solid transparent; color:var(--dim); font-size:12px; font-weight:600; padding:6px 0 8px; cursor:pointer; transition:color .3s ease, border-color .3s ease; }\n  .tabs button.active{ color:var(--ink); border-bottom-color:var(--navy); }\n\n  .field{ position:relative; margin-bottom:20px; }\n  .field label{ display:block; font-size:11px; letter-spacing:.04em; color:var(--dim); margin-bottom:6px; }\n  .field input{ width:100%; background:var(--linen); border:1.5px solid var(--line); color:var(--ink); font-size:15px; padding:9px 11px; outline:none; transition:border-color .2s ease; }\n  .field input:focus{ border-color:var(--navy); }\n  .field input::placeholder{ color:var(--dim); opacity:.5; }\n  .extra{ max-height:0; opacity:0; overflow:hidden; transition:max-height .5s cubic-bezier(.4,0,.2,1), opacity .35s ease; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--dim); margin:0 0 28px; }\n  .row-between a{ color:var(--dim); text-decoration:none; border-bottom:1px solid var(--line); }\n  .row-between a:hover{ color:var(--navy); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--navy); width:13px; height:13px; }\n\n  button.enter{ position:relative; width:100%; background:var(--navy); border:none; color:var(--linen); font-size:13.5px; font-weight:600; padding:14px; cursor:pointer; transition:background .3s ease, transform .1s ease; }\n  button.enter:hover{ background:var(--navy-bright); }\n  button.enter:active{ transform:scale(.99); }\n\n  .divider{ display:flex; align-items:center; gap:14px; margin:24px 0; color:var(--dim); font-size:11px; }\n  .divider::before,.divider::after{ content:\"\"; flex:1; height:1px; background:var(--line); }\n  button.ghost{ width:100%; background:none; border:1px solid var(--line); color:var(--ink); font-size:13px; padding:12px; cursor:pointer; transition:border-color .2s ease; }\n  button.ghost:hover{ border-color:var(--navy); }\n\n  .foot{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:22px; }\n  .foot a{ color:var(--navy); text-decoration:none; cursor:pointer; font-weight:600; }\n  .foot a:hover{ text-decoration:underline; }\n  :focus-visible{ outline:1px solid var(--navy); outline-offset:2px; }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n\n  .field{ position:relative; }\n  .eye-btn{\n    position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer;\n    color:var(--dim); display:flex; align-items:center; justify-content:center; transition:color .2s ease; z-index:2;\n  }\n  .eye-btn:hover{ color:var(--navy); }\n  .eye-btn svg{ width:15px; height:15px; }\n  input.has-eye{ padding-right:32px !important; }\n</style>\n</head>\n<body>\n\n<div class=\"stage\">\n  <div class=\"stamp\">\n    <div class=\"brand\">INK &amp; LINEN CO.</div>\n    <h1 id=\"heading\">Sign in</h1>\n    <p class=\"sub\" id=\"subhead\">Your orders, proofs, and saved stock.</p>\n  </div>\n\n  <div class=\"rule\"></div>\n\n  <div class=\"panel\">\n    <div class=\"tabs\" id=\"tabs\">\n      <button class=\"active\" data-tab=\"signin\" type=\"button\">Sign in</button>\n      <button data-tab=\"signup\" type=\"button\">Create account</button>\n    </div>\n\n    <form onsubmit=\"return false;\">\n      <div class=\"field extra\" id=\"nameField\">\n        <label for=\"nameInput\">Full name</label>\n        <input type=\"text\" placeholder=\"Jordan Rivera\" id=\"nameInput\"  autocomplete=\"name\" />\n      </div>\n      <div class=\"field\">\n        <label for=\"emailInput\">Email address</label>\n        <input type=\"email\" placeholder=\"you@company.com\" id=\"emailInput\" required  autocomplete=\"email\" />\n      </div>\n      <div class=\"field\">\n        <label for=\"pwInput\">Password</label>\n        <input type=\"password\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\" id=\"pwInput\" required  autocomplete=\"current-password\"  class=\"has-eye\" /><button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n      </div>\n      <div class=\"field extra\" id=\"confirmField\">\n        <label for=\"confirmInput\">Confirm password</label>\n        <input type=\"password\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\" id=\"confirmInput\"  autocomplete=\"new-password\" />\n      </div>\n      <div class=\"row-between\" id=\"signinOnlyRow\">\n        <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n        <a href=\"#\">Forgot password?</a>\n      </div>\n      <button class=\"enter\" type=\"submit\"><span id=\"submitLabel\">Sign in</span></button>\n    </form>\n\n    <div class=\"divider\">or continue with</div>\n    <button class=\"ghost\" type=\"button\">Google</button>\n\n    <p class=\"foot\" id=\"footNote\">New here? <a data-switch=\"signup\">Create an account</a></p>\n  </div>\n</div>\n\n<script>\n(function(){\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    if(!input) return;\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n      btn.innerHTML = showing ? '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M17.94 17.94A10.94 10.94 0 0112 19c-7 0-11-7-11-7a20.6 20.6 0 015.06-5.94M9.9 4.24A10.4 10.4 0 0112 4c7 0 11 7 11 7a20.6 20.6 0 01-2.16 3.19M14.12 14.12a3 3 0 11-4.24-4.24\"/><line x1=\"1\" y1=\"1\" x2=\"23\" y2=\"23\"/></svg>' : '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>';\n    });\n  });\n\n  var tabs = document.querySelectorAll('#tabs button[data-tab]');\n  var nameField = document.getElementById('nameField');\n  var confirmField = document.getElementById('confirmField');\n  var signinOnlyRow = document.getElementById('signinOnlyRow');\n  var heading = document.getElementById('heading');\n  var subhead = document.getElementById('subhead');\n  var submitLabel = document.getElementById('submitLabel');\n  var footNote = document.getElementById('footNote');\n\n  var COPY = {\n    signin: { heading:'Sign in', sub:'Your orders, proofs, and saved stock.', submit:'Sign in', foot:'New here? <a data-switch=\"signup\">Create an account</a>' },\n    signup: { heading:'Create your account', sub:'Set up your account in under a minute.', submit:'Create account', foot:'Already have an account? <a data-switch=\"signin\">Sign in</a>' }\n  };\n\n  function bindSwitchLinks(){ document.querySelectorAll('[data-switch]').forEach(function(a){ a.addEventListener('click', function(e){ e.preventDefault(); setMode(a.getAttribute('data-switch')); }); }); }\n\n  function setMode(mode){\n    tabs.forEach(function(t){ t.classList.toggle('active', t.dataset.tab===mode); });\n    var showExtra = mode==='signup';\n    [nameField, confirmField].forEach(function(f){ f.style.maxHeight = showExtra ? f.scrollHeight+'px' : '0px'; f.style.opacity = showExtra?1:0; });\n    signinOnlyRow.style.display = mode==='signin' ? 'flex' : 'none';\n    heading.textContent = COPY[mode].heading;\n    subhead.textContent = COPY[mode].sub;\n    submitLabel.textContent = COPY[mode].submit;\n    footNote.innerHTML = COPY[mode].foot;\n    bindSwitchLinks();\n  }\n  tabs.forEach(function(t){ t.addEventListener('click', function(){ setMode(t.dataset.tab); }); });\n  bindSwitchLinks();\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--navy', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "solstice-club", "file": "forms/solstice-club.html", "title": "Solstice Club", "layout": "Underline Tab + Glow Button", "layout_key": "underline-glow", "palette": "Terracotta & Charcoal", "palette_key": "terracotta-charcoal", "blurb": "A private club: the button blooms with a soft glow on hover instead of filling; sun-rays rotate slowly behind the emblem.", "n": 11, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Solstice Club \u2014 Member Sign In</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;1,500&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --charcoal:#161311; --card:#1c1815; --line:rgba(212,141,79,0.16); --terracotta:#d48d4f; --terracotta-bright:#eeb27e;\n    --cream:#f0e8db; --dim:#93887a;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--charcoal); color:var(--cream); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:flex; align-items:center; justify-content:center; padding:60px 24px; position:relative; overflow:hidden;\n  }\n\n  .rays{ position:absolute; top:-260px; left:50%; width:900px; height:900px; transform:translateX(-50%);\n    animation:rotateRays 90s linear infinite; opacity:.5; }\n  .rays div{ position:absolute; top:50%; left:50%; width:1px; height:420px; background:linear-gradient(to top, var(--terracotta), transparent);\n    transform-origin:top center; }\n  @keyframes rotateRays{ from{ transform:translateX(-50%) rotate(0deg); } to{ transform:translateX(-50%) rotate(360deg); } }\n\n  .stage{ position:relative; z-index:1; width:100%; max-width:380px; text-align:center;\n    opacity:0; transform:translateY(14px); animation:reveal .9s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.2s; }\n  @keyframes reveal{ to{ opacity:1; transform:none; } }\n\n  .emblem{ width:48px; height:48px; margin:0 auto 20px; }\n  .emblem circle{ fill:none; stroke:var(--terracotta); stroke-width:1; }\n  .emblem .core{ fill:var(--terracotta-bright); }\n\n  .brand{ font-size:11px; letter-spacing:.24em; color:var(--terracotta); margin-bottom:14px; }\n  h1{ font-family:'Cormorant Garamond', serif; font-weight:500; font-size:29px; margin-bottom:8px; }\n  .sub{ font-size:13.5px; color:var(--dim); margin-bottom:34px; }\n\n  .panel{ text-align:left; background:var(--card); border:1px solid var(--line); padding:36px 32px; border-radius:2px; }\n\n  .tabs{ position:relative; display:flex; gap:24px; margin-bottom:28px; border-bottom:1px solid var(--line); }\n  .tabs button{ background:none; border:none; color:var(--dim); font-size:12.5px; font-weight:500; padding:0 0 12px; cursor:pointer; transition:color .3s ease; }\n  .tabs button.active{ color:var(--terracotta-bright); }\n  .tab-indicator{ position:absolute; bottom:-1px; height:1.5px; background:var(--terracotta-bright); box-shadow:0 0 8px var(--terracotta); transition:transform .5s cubic-bezier(.65,0,.35,1), width .5s cubic-bezier(.65,0,.35,1); }\n\n  .field{ position:relative; margin-bottom:24px; }\n  .field label{ position:absolute; left:0; top:11px; font-size:14px; color:var(--dim); pointer-events:none; transition:transform .3s cubic-bezier(.4,0,.2,1), font-size .3s ease, color .3s ease; transform-origin:left top; }\n  .field input{ width:100%; background:none; border:none; border-bottom:1px solid var(--line); color:var(--cream); font-size:15px; padding:10px 0; outline:none; transition:border-color .3s ease; }\n  .field .underline-accent{ position:absolute; left:0; right:0; bottom:-1px; height:1.5px; background:var(--terracotta-bright); transform:scaleX(0); transition:transform .4s cubic-bezier(.65,0,.35,1); box-shadow:0 0 8px var(--terracotta); }\n  .field input:focus ~ .underline-accent{ transform:scaleX(1); }\n  .field input:focus{ border-color:transparent; }\n  .field input:focus + label, .field input:not(:placeholder-shown) + label{ transform:translateY(-19px); font-size:11px; color:var(--terracotta-bright); }\n  .field input::placeholder{ color:transparent; }\n  .extra{ max-height:0; opacity:0; overflow:hidden; transition:max-height .5s cubic-bezier(.4,0,.2,1), opacity .35s ease; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--dim); margin:0 0 28px; }\n  .row-between a{ color:var(--dim); text-decoration:none; border-bottom:1px solid var(--line); }\n  .row-between a:hover{ color:var(--terracotta-bright); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--terracotta); width:13px; height:13px; }\n\n  button.enter{ position:relative; width:100%; background:var(--terracotta); border:none; color:#1c1815;\n    font-family:'Cormorant Garamond', serif; font-style:italic; font-size:18px; padding:14px; cursor:pointer;\n    box-shadow:0 0 0 0 rgba(212,141,79,0.45); transition:box-shadow .35s ease, transform .1s ease, background .3s ease; }\n  button.enter:hover{ background:var(--terracotta-bright); box-shadow:0 0 0 9px rgba(212,141,79,0.16), 0 0 30px 6px rgba(212,141,79,0.3); }\n  button.enter:active{ transform:scale(.99); }\n\n  .divider{ display:flex; align-items:center; gap:14px; margin:24px 0; color:var(--dim); font-size:11px; }\n  .divider::before,.divider::after{ content:\"\"; flex:1; height:1px; background:var(--line); }\n  button.ghost{ width:100%; background:none; border:1px solid var(--line); color:var(--cream); font-size:13px; padding:12px; cursor:pointer; transition:border-color .2s ease; }\n  button.ghost:hover{ border-color:var(--terracotta); }\n\n  .foot{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:22px; }\n  .foot a{ color:var(--terracotta-bright); text-decoration:none; cursor:pointer; }\n  .foot a:hover{ text-decoration:underline; }\n  :focus-visible{ outline:1px solid var(--terracotta-bright); outline-offset:2px; }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } .rays{ display:none; } }\n\n  .field{ position:relative; }\n  .eye-btn{\n    position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer;\n    color:var(--dim); display:flex; align-items:center; justify-content:center; transition:color .2s ease; z-index:2;\n  }\n  .eye-btn:hover{ color:var(--terracotta-bright); }\n  .eye-btn svg{ width:15px; height:15px; }\n  input.has-eye{ padding-right:32px !important; }\n</style>\n</head>\n<body>\n\n<div class=\"rays\" id=\"rays\"></div>\n\n<div class=\"stage\">\n  <svg class=\"emblem\" viewBox=\"0 0 48 48\">\n    <circle cx=\"24\" cy=\"24\" r=\"21\"/>\n    <circle cx=\"24\" cy=\"24\" r=\"14\"/>\n    <circle class=\"core\" cx=\"24\" cy=\"24\" r=\"3\" stroke=\"none\"/>\n  </svg>\n\n  <div class=\"brand\">SOLSTICE CLUB</div>\n  <h1 id=\"heading\">Member sign in</h1>\n  <p class=\"sub\" id=\"subhead\">Reservations, guest passes, and the season's calendar.</p>\n\n  <div class=\"panel\">\n    <div class=\"tabs\" id=\"tabs\">\n      <button class=\"active\" data-tab=\"signin\" type=\"button\">Sign in</button>\n      <button data-tab=\"signup\" type=\"button\">Request membership</button>\n      <span class=\"tab-indicator\" id=\"tabIndicator\"></span>\n    </div>\n\n    <form onsubmit=\"return false;\">\n      <div class=\"field extra\" id=\"nameField\">\n        <input type=\"text\" placeholder=\" \" id=\"nameInput\"  autocomplete=\"name\" />\n        <label for=\"nameInput\">Full name</label>\n        <span class=\"underline-accent\"></span>\n      </div>\n      <div class=\"field\">\n        <input type=\"email\" placeholder=\" \" id=\"emailInput\" required  autocomplete=\"email\" />\n        <label for=\"emailInput\">Email address</label>\n        <span class=\"underline-accent\"></span>\n      </div>\n      <div class=\"field\">\n        <input type=\"password\" placeholder=\" \" id=\"pwInput\" required  autocomplete=\"current-password\"  class=\"has-eye\" />\n        <label for=\"pwInput\">Password</label>\n        <span class=\"underline-accent\"></span><button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n      </div>\n      <div class=\"field extra\" id=\"confirmField\">\n        <input type=\"password\" placeholder=\" \" id=\"confirmInput\"  autocomplete=\"new-password\" />\n        <label for=\"confirmInput\">Confirm password</label>\n        <span class=\"underline-accent\"></span>\n      </div>\n      <div class=\"row-between\" id=\"signinOnlyRow\">\n        <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n        <a href=\"#\">Forgot password?</a>\n      </div>\n      <button class=\"enter\" type=\"submit\"><span id=\"submitLabel\">Enter</span></button>\n    </form>\n\n    <div class=\"divider\">or continue with</div>\n    <button class=\"ghost\" type=\"button\">Google</button>\n\n    <p class=\"foot\" id=\"footNote\">Not a member? <a data-switch=\"signup\">Request membership</a></p>\n  </div>\n</div>\n\n<script>\n(function(){\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    if(!input) return;\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n      btn.innerHTML = showing ? '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M17.94 17.94A10.94 10.94 0 0112 19c-7 0-11-7-11-7a20.6 20.6 0 015.06-5.94M9.9 4.24A10.4 10.4 0 0112 4c7 0 11 7 11 7a20.6 20.6 0 01-2.16 3.19M14.12 14.12a3 3 0 11-4.24-4.24\"/><line x1=\"1\" y1=\"1\" x2=\"23\" y2=\"23\"/></svg>' : '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>';\n    });\n  });\n\n  var rays = document.getElementById('rays');\n  for(var i=0;i<28;i++){\n    var r = document.createElement('div');\n    r.style.transform = 'rotate('+(i*(360/28))+'deg)';\n    rays.appendChild(r);\n  }\n\n  var tabs = document.querySelectorAll('#tabs button[data-tab]');\n  var indicator = document.getElementById('tabIndicator');\n  var nameField = document.getElementById('nameField');\n  var confirmField = document.getElementById('confirmField');\n  var signinOnlyRow = document.getElementById('signinOnlyRow');\n  var heading = document.getElementById('heading');\n  var subhead = document.getElementById('subhead');\n  var submitLabel = document.getElementById('submitLabel');\n  var footNote = document.getElementById('footNote');\n\n  var COPY = {\n    signin: { heading:\"Member sign in\", sub:\"Reservations, guest passes, and the season's calendar.\", submit:'Enter', foot:'Not a member? <a data-switch=\"signup\">Request membership</a>' },\n    signup: { heading:'Request membership', sub:'Applications are reviewed within a week.', submit:'Request membership', foot:'Already a member? <a data-switch=\"signin\">Sign in</a>' }\n  };\n\n  function positionIndicator(el){ indicator.style.width = el.offsetWidth+'px'; indicator.style.transform = 'translateX('+el.offsetLeft+'px)'; }\n  function bindSwitchLinks(){ document.querySelectorAll('[data-switch]').forEach(function(a){ a.addEventListener('click', function(e){ e.preventDefault(); setMode(a.getAttribute('data-switch')); }); }); }\n\n  function setMode(mode){\n    tabs.forEach(function(t){ t.classList.toggle('active', t.dataset.tab===mode); if(t.dataset.tab===mode) positionIndicator(t); });\n    var showExtra = mode==='signup';\n    [nameField, confirmField].forEach(function(f){ f.style.maxHeight = showExtra ? f.scrollHeight+'px' : '0px'; f.style.opacity = showExtra?1:0; });\n    signinOnlyRow.style.display = mode==='signin' ? 'flex' : 'none';\n    heading.textContent = COPY[mode].heading;\n    subhead.textContent = COPY[mode].sub;\n    submitLabel.textContent = COPY[mode].submit;\n    footNote.innerHTML = COPY[mode].foot;\n    bindSwitchLinks();\n  }\n  tabs.forEach(function(t){ t.addEventListener('click', function(){ setMode(t.dataset.tab); }); });\n  bindSwitchLinks();\n  window.addEventListener('load', function(){ positionIndicator(document.querySelector('#tabs button.active')); });\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--terracotta', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "cellar-no9", "file": "forms/cellar-no9.html", "title": "Cellar No. 9", "layout": "Underline Tab + Flicker Button", "layout_key": "underline-flicker", "palette": "Cork & Wine", "palette_key": "cork-wine", "blurb": "A wine cellar: the button carries a continuous slow flicker, like it's lit from within, echoing the candlelight glow behind the card.", "n": 12, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Cellar No. 9 \u2014 Member Sign In</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;1,500&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --ink:#150a0c; --card:#1c0f12; --line:rgba(196,124,90,0.16); --cork:#c47c5a; --cork-bright:#e2a37c;\n    --cream:#efe4dc; --dim:#8f7a72;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--ink); color:var(--cream); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:flex; align-items:center; justify-content:center; padding:60px 24px; position:relative; overflow:hidden;\n  }\n\n  .candle-glow{\n    position:fixed; top:50%; left:50%; width:640px; height:640px; transform:translate(-50%,-50%); border-radius:50%;\n    background:radial-gradient(circle, rgba(196,124,90,0.16), transparent 70%);\n    animation:flicker 5s ease-in-out infinite;\n  }\n  @keyframes flicker{\n    0%,100%{ opacity:1; transform:translate(-50%,-50%) scale(1); }\n    18%{ opacity:.85; transform:translate(-50%,-50%) scale(.98); }\n    36%{ opacity:1; transform:translate(-50%,-50%) scale(1.02); }\n    52%{ opacity:.9; transform:translate(-50%,-50%) scale(.99); }\n    74%{ opacity:1; transform:translate(-50%,-50%) scale(1.01); }\n  }\n\n  .stage{ position:relative; z-index:1; width:100%; max-width:380px; text-align:center;\n    opacity:0; transform:translateY(14px); animation:reveal .9s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.2s; }\n  @keyframes reveal{ to{ opacity:1; transform:none; } }\n\n  .tag{ display:inline-block; border:1px solid var(--line); border-radius:999px; padding:6px 16px; font-size:11px; letter-spacing:.1em; color:var(--cork); margin-bottom:22px; }\n  h1{ font-family:'Cormorant Garamond', serif; font-weight:500; font-style:italic; font-size:31px; margin-bottom:8px; }\n  .sub{ font-size:13.5px; color:var(--dim); margin-bottom:34px; }\n\n  .panel{ text-align:left; background:var(--card); border:1px solid var(--line); padding:36px 32px; border-radius:3px; }\n\n  .tabs{ position:relative; display:flex; gap:24px; margin-bottom:28px; border-bottom:1px solid var(--line); }\n  .tabs button{ background:none; border:none; color:var(--dim); font-size:12.5px; font-weight:500; padding:0 0 12px; cursor:pointer; transition:color .3s ease; }\n  .tabs button.active{ color:var(--cork-bright); }\n  .tab-indicator{ position:absolute; bottom:-1px; height:1.5px; background:var(--cork-bright); box-shadow:0 0 8px var(--cork); transition:transform .5s cubic-bezier(.65,0,.35,1), width .5s cubic-bezier(.65,0,.35,1); }\n\n  .field{ position:relative; margin-bottom:24px; }\n  .field label{ position:absolute; left:0; top:11px; font-size:14px; color:var(--dim); pointer-events:none; transition:transform .3s cubic-bezier(.4,0,.2,1), font-size .3s ease, color .3s ease; transform-origin:left top; }\n  .field input{ width:100%; background:none; border:none; border-bottom:1px solid var(--line); color:var(--cream); font-size:15px; padding:10px 0; outline:none; transition:border-color .3s ease; }\n  .field .underline-accent{ position:absolute; left:0; right:0; bottom:-1px; height:1.5px; background:var(--cork-bright); transform:scaleX(0); transition:transform .4s cubic-bezier(.65,0,.35,1); box-shadow:0 0 8px var(--cork); }\n  .field input:focus ~ .underline-accent{ transform:scaleX(1); }\n  .field input:focus{ border-color:transparent; }\n  .field input:focus + label, .field input:not(:placeholder-shown) + label{ transform:translateY(-19px); font-size:11px; color:var(--cork-bright); }\n  .field input::placeholder{ color:transparent; }\n  .extra{ max-height:0; opacity:0; overflow:hidden; transition:max-height .5s cubic-bezier(.4,0,.2,1), opacity .35s ease; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--dim); margin:0 0 28px; }\n  .row-between a{ color:var(--dim); text-decoration:none; border-bottom:1px solid var(--line); }\n  .row-between a:hover{ color:var(--cork-bright); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--cork); width:13px; height:13px; }\n\n  @keyframes buttonFlicker{ 0%,100%{ box-shadow:0 0 14px 2px rgba(196,124,90,0.22); } 50%{ box-shadow:0 0 20px 5px rgba(196,124,90,0.38); } }\n  button.enter{ position:relative; width:100%; background:var(--cork); border:none; color:#1c0f12;\n    font-family:'Cormorant Garamond', serif; font-style:italic; font-size:18px; padding:14px; cursor:pointer;\n    animation:buttonFlicker 3s ease-in-out infinite; transition:transform .1s ease, background .3s ease; }\n  button.enter:hover{ background:var(--cork-bright); }\n  button.enter:active{ transform:scale(.99); }\n\n  .divider{ display:flex; align-items:center; gap:14px; margin:24px 0; color:var(--dim); font-size:11px; }\n  .divider::before,.divider::after{ content:\"\"; flex:1; height:1px; background:var(--line); }\n  button.ghost{ width:100%; background:none; border:1px solid var(--line); color:var(--cream); font-size:13px; padding:12px; cursor:pointer; transition:border-color .2s ease; }\n  button.ghost:hover{ border-color:var(--cork); }\n\n  .foot{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:22px; }\n  .foot a{ color:var(--cork-bright); text-decoration:none; cursor:pointer; }\n  .foot a:hover{ text-decoration:underline; }\n  :focus-visible{ outline:1px solid var(--cork-bright); outline-offset:2px; }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n\n  .field{ position:relative; }\n  .eye-btn{\n    position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer;\n    color:var(--dim); display:flex; align-items:center; justify-content:center; transition:color .2s ease; z-index:2;\n  }\n  .eye-btn:hover{ color:var(--cork-bright); }\n  .eye-btn svg{ width:15px; height:15px; }\n  input.has-eye{ padding-right:32px !important; }\n</style>\n</head>\n<body>\n\n<div class=\"candle-glow\"></div>\n\n<div class=\"stage\">\n  <div class=\"tag\">CELLAR No. 9</div>\n  <h1 id=\"heading\">Welcome back</h1>\n  <p class=\"sub\" id=\"subhead\">Your reserve list and tasting notes.</p>\n\n  <div class=\"panel\">\n    <div class=\"tabs\" id=\"tabs\">\n      <button class=\"active\" data-tab=\"signin\" type=\"button\">Sign in</button>\n      <button data-tab=\"signup\" type=\"button\">Join the list</button>\n      <span class=\"tab-indicator\" id=\"tabIndicator\"></span>\n    </div>\n\n    <form onsubmit=\"return false;\">\n      <div class=\"field extra\" id=\"nameField\">\n        <input type=\"text\" placeholder=\" \" id=\"nameInput\"  autocomplete=\"name\" />\n        <label for=\"nameInput\">Full name</label>\n        <span class=\"underline-accent\"></span>\n      </div>\n      <div class=\"field\">\n        <input type=\"email\" placeholder=\" \" id=\"emailInput\" required  autocomplete=\"email\" />\n        <label for=\"emailInput\">Email address</label>\n        <span class=\"underline-accent\"></span>\n      </div>\n      <div class=\"field\">\n        <input type=\"password\" placeholder=\" \" id=\"pwInput\" required  autocomplete=\"current-password\"  class=\"has-eye\" />\n        <label for=\"pwInput\">Password</label>\n        <span class=\"underline-accent\"></span><button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n      </div>\n      <div class=\"field extra\" id=\"confirmField\">\n        <input type=\"password\" placeholder=\" \" id=\"confirmInput\"  autocomplete=\"new-password\" />\n        <label for=\"confirmInput\">Confirm password</label>\n        <span class=\"underline-accent\"></span>\n      </div>\n      <div class=\"row-between\" id=\"signinOnlyRow\">\n        <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n        <a href=\"#\">Forgot password?</a>\n      </div>\n      <button class=\"enter\" type=\"submit\"><span id=\"submitLabel\">Enter</span></button>\n    </form>\n\n    <div class=\"divider\">or continue with</div>\n    <button class=\"ghost\" type=\"button\">Google</button>\n\n    <p class=\"foot\" id=\"footNote\">New here? <a data-switch=\"signup\">Join the list</a></p>\n  </div>\n</div>\n\n<script>\n(function(){\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    if(!input) return;\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n      btn.innerHTML = showing ? '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M17.94 17.94A10.94 10.94 0 0112 19c-7 0-11-7-11-7a20.6 20.6 0 015.06-5.94M9.9 4.24A10.4 10.4 0 0112 4c7 0 11 7 11 7a20.6 20.6 0 01-2.16 3.19M14.12 14.12a3 3 0 11-4.24-4.24\"/><line x1=\"1\" y1=\"1\" x2=\"23\" y2=\"23\"/></svg>' : '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>';\n    });\n  });\n\n  var tabs = document.querySelectorAll('#tabs button[data-tab]');\n  var indicator = document.getElementById('tabIndicator');\n  var nameField = document.getElementById('nameField');\n  var confirmField = document.getElementById('confirmField');\n  var signinOnlyRow = document.getElementById('signinOnlyRow');\n  var heading = document.getElementById('heading');\n  var subhead = document.getElementById('subhead');\n  var submitLabel = document.getElementById('submitLabel');\n  var footNote = document.getElementById('footNote');\n\n  var COPY = {\n    signin: { heading:'Welcome back', sub:'Your reserve list and tasting notes.', submit:'Enter', foot:'New here? <a data-switch=\"signup\">Join the list</a>' },\n    signup: { heading:'Join the list', sub:'Get first access to limited releases.', submit:'Join the list', foot:'Already on the list? <a data-switch=\"signin\">Sign in</a>' }\n  };\n\n  function positionIndicator(el){ indicator.style.width = el.offsetWidth+'px'; indicator.style.transform = 'translateX('+el.offsetLeft+'px)'; }\n  function bindSwitchLinks(){ document.querySelectorAll('[data-switch]').forEach(function(a){ a.addEventListener('click', function(e){ e.preventDefault(); setMode(a.getAttribute('data-switch')); }); }); }\n\n  function setMode(mode){\n    tabs.forEach(function(t){ t.classList.toggle('active', t.dataset.tab===mode); if(t.dataset.tab===mode) positionIndicator(t); });\n    var showExtra = mode==='signup';\n    [nameField, confirmField].forEach(function(f){ f.style.maxHeight = showExtra ? f.scrollHeight+'px' : '0px'; f.style.opacity = showExtra?1:0; });\n    signinOnlyRow.style.display = mode==='signin' ? 'flex' : 'none';\n    heading.textContent = COPY[mode].heading;\n    subhead.textContent = COPY[mode].sub;\n    submitLabel.textContent = COPY[mode].submit;\n    footNote.innerHTML = COPY[mode].foot;\n    bindSwitchLinks();\n  }\n  tabs.forEach(function(t){ t.addEventListener('click', function(){ setMode(t.dataset.tab); }); });\n  bindSwitchLinks();\n  window.addEventListener('load', function(){ positionIndicator(document.querySelector('#tabs button.active')); });\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--cork', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "meridian-verify", "file": "forms/meridian-verify.html", "title": "Meridian Exchange", "layout": "Six-Digit OTP", "layout_key": "otp-verify", "palette": "Sapphire & Gold", "palette_key": "sapphire-gold", "blurb": "A private exchange's verification step: auto-advancing digit boxes, full paste support, and a resend timer that actually counts down.", "n": 13, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Meridian Exchange \u2014 Verify</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,600;1,500&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --navy:#0e1526; --card:#141d34; --line:rgba(202,169,104,0.16);\n    --gold:#caa968; --gold-bright:#e8d3a0; --cream:#eef0f7; --dim:#7c869e;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--navy); color:var(--cream); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:flex; align-items:center; justify-content:center; padding:60px 24px;\n  }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n  :focus-visible{ outline:1px solid var(--gold-bright); outline-offset:2px; }\n\n  .stage{ width:100%; max-width:380px; text-align:center;\n    opacity:0; transform:translateY(14px); animation:reveal .9s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.1s; }\n  @keyframes reveal{ to{ opacity:1; transform:none; } }\n\n  .brand{ font-size:11px; letter-spacing:.22em; color:var(--gold); margin-bottom:22px; }\n  h1{ font-family:'Playfair Display', serif; font-weight:600; font-size:26px; margin-bottom:10px; }\n  .sub{ font-size:13.5px; color:var(--dim); margin-bottom:6px; line-height:1.5; }\n  .sub b{ color:var(--cream); font-weight:600; }\n\n  .panel{ background:var(--card); border:1px solid var(--line); padding:38px 32px; border-radius:3px; margin-top:28px; }\n\n  .otp-row{ display:flex; gap:9px; justify-content:center; margin-bottom:24px; }\n  .otp-row input{\n    width:44px; height:54px; text-align:center; font-size:22px; font-family:'Inter', sans-serif; font-weight:600;\n    background:rgba(255,255,255,0.03); border:1.5px solid var(--line); border-radius:3px; color:var(--cream); outline:none;\n    transition:border-color .25s ease, box-shadow .25s ease;\n  }\n  .otp-row input:focus{ border-color:var(--gold); box-shadow:0 0 0 3px rgba(202,169,104,0.15); }\n  .otp-row input.filled{ border-color:var(--gold-bright); }\n\n  .status{ font-size:12px; color:var(--dim); margin-bottom:22px; min-height:16px; }\n  .status.error{ color:#d1786a; }\n\n  button.enter{ position:relative; width:100%; background:var(--gold); border:none; color:#171008; font-weight:600; font-size:13.5px; letter-spacing:.02em; padding:14px; border-radius:3px; cursor:pointer; transition:filter .3s ease, transform .1s ease, opacity .3s ease; }\n  button.enter:hover{ filter:brightness(1.08); }\n  button.enter:active{ transform:scale(.99); }\n  button.enter:disabled{ opacity:.4; cursor:not-allowed; filter:none; }\n\n  .resend{ margin-top:20px; font-size:12.5px; color:var(--dim); }\n  .resend button{ background:none; border:none; color:var(--gold-bright); cursor:pointer; font-size:12.5px; padding:0; text-decoration:underline; }\n  .resend button:disabled{ color:var(--dim); text-decoration:none; cursor:default; }\n\n  .foot{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:22px; }\n  .foot a{ color:var(--gold-bright); text-decoration:none; }\n  .foot a:hover{ text-decoration:underline; }\n</style>\n</head>\n<body>\n\n<div class=\"stage\">\n  <div class=\"brand\">MERIDIAN EXCHANGE</div>\n  <h1>Check your inbox</h1>\n  <p class=\"sub\">We sent a 6-digit code to <b id=\"emailDisplay\">j***@company.com</b></p>\n\n  <div class=\"panel\">\n    <div class=\"otp-row\" id=\"otpRow\">\n      <input type=\"text\" inputmode=\"numeric\" maxlength=\"1\" autocomplete=\"one-time-code\" aria-label=\"Digit 1\" />\n      <input type=\"text\" inputmode=\"numeric\" maxlength=\"1\" aria-label=\"Digit 2\" />\n      <input type=\"text\" inputmode=\"numeric\" maxlength=\"1\" aria-label=\"Digit 3\" />\n      <input type=\"text\" inputmode=\"numeric\" maxlength=\"1\" aria-label=\"Digit 4\" />\n      <input type=\"text\" inputmode=\"numeric\" maxlength=\"1\" aria-label=\"Digit 5\" />\n      <input type=\"text\" inputmode=\"numeric\" maxlength=\"1\" aria-label=\"Digit 6\" />\n    </div>\n    <p class=\"status\" id=\"status\" role=\"status\" aria-live=\"polite\"></p>\n    <button class=\"enter\" id=\"verifyBtn\" type=\"button\" disabled>Verify code</button>\n    <p class=\"resend\">Didn't get it? <button id=\"resendBtn\" type=\"button\" disabled>Resend in <span id=\"timer\">30</span>s</button></p>\n  </div>\n\n  <p class=\"foot\">Wrong email? <a href=\"#\">Start over</a></p>\n</div>\n\n<script>\n(function(){\n  var inputs = [].slice.call(document.querySelectorAll('#otpRow input'));\n  var verifyBtn = document.getElementById('verifyBtn');\n  var resendBtn = document.getElementById('resendBtn');\n  var statusEl = document.getElementById('status');\n  var timerEl = document.getElementById('timer');\n\n  function updateVerifyState(){\n    var filled = inputs.every(function(i){ return i.value.length === 1; });\n    verifyBtn.disabled = !filled;\n  }\n\n  inputs.forEach(function(input, idx){\n    input.addEventListener('input', function(){\n      input.value = input.value.replace(/[^0-9]/g, '').slice(0, 1);\n      input.classList.toggle('filled', input.value.length === 1);\n      if(input.value && idx < inputs.length - 1) inputs[idx + 1].focus();\n      updateVerifyState();\n    });\n    input.addEventListener('keydown', function(e){\n      if(e.key === 'Backspace' && !input.value && idx > 0){\n        inputs[idx - 1].focus();\n      }\n    });\n    input.addEventListener('paste', function(e){\n      e.preventDefault();\n      var text = (e.clipboardData || window.clipboardData).getData('text').replace(/[^0-9]/g, '');\n      if(!text) return;\n      text.split('').slice(0, inputs.length).forEach(function(ch, i){\n        inputs[i].value = ch;\n        inputs[i].classList.add('filled');\n      });\n      var next = Math.min(text.length, inputs.length - 1);\n      inputs[next].focus();\n      updateVerifyState();\n    });\n  });\n\n  verifyBtn.addEventListener('click', function(){\n    var code = inputs.map(function(i){ return i.value; }).join('');\n    statusEl.textContent = 'Verifying ' + code + '\u2026 (demo only, no real request is sent)';\n    statusEl.classList.remove('error');\n  });\n\n  var seconds = 30;\n  var countdown = setInterval(function(){\n    seconds--;\n    timerEl.textContent = seconds;\n    if(seconds <= 0){\n      clearInterval(countdown);\n      resendBtn.disabled = false;\n      resendBtn.textContent = 'Resend code';\n    }\n  }, 1000);\n\n  resendBtn.addEventListener('click', function(){\n    if(resendBtn.disabled) return;\n    statusEl.textContent = 'A new code was sent.';\n    statusEl.classList.remove('error');\n    resendBtn.disabled = true;\n    seconds = 30;\n    var el = document.createElement('span');\n    el.id = 'timer';\n    el.textContent = seconds;\n    resendBtn.textContent = '';\n    resendBtn.appendChild(document.createTextNode('Resend in '));\n    resendBtn.appendChild(el);\n    resendBtn.appendChild(document.createTextNode('s'));\n    countdown = setInterval(function(){\n      seconds--;\n      el.textContent = seconds;\n      if(seconds <= 0){\n        clearInterval(countdown);\n        resendBtn.disabled = false;\n        resendBtn.textContent = 'Resend code';\n      }\n    }, 1000);\n  });\n\n  window.addEventListener('message', function(e){\n    if(e.data && e.data.type === 'loginkit-accent'){\n      document.documentElement.style.setProperty('--gold', e.data.color);\n    }\n  });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "the-keep-session-lock", "file": "forms/the-keep-session-lock.html", "title": "The Keep", "layout": "Session Lock", "layout_key": "session-lock", "palette": "Forest & Ivory", "palette_key": "forest-ivory", "blurb": "The screen a returning user sees far more than a real login: your name and avatar are known, only the password is missing.", "n": 14, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>The Keep \u2014 Session Locked</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,600&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --forest:#122019; --card:#f6f1e6; --line:#ddccae;\n    --gold:#8a6a35; --ink:#241a16; --dim:#8a7458;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--forest); color:var(--ink); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:flex; align-items:center; justify-content:center; padding:60px 24px;\n  }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n  :focus-visible{ outline:1px solid var(--gold); outline-offset:2px; }\n\n  .card{\n    width:100%; max-width:360px; background:var(--card); border-radius:3px; padding:44px 36px; text-align:center;\n    box-shadow:0 40px 90px -30px rgba(0,0,0,0.6);\n    opacity:0; transform:translateY(16px) scale(.98); animation:reveal .85s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.15s;\n  }\n  @keyframes reveal{ to{ opacity:1; transform:none; } }\n\n  .avatar{\n    width:64px; height:64px; border-radius:50%; margin:0 auto 18px; background:linear-gradient(160deg, #2d4a3a, #122019);\n    display:flex; align-items:center; justify-content:center; font-family:'Fraunces', serif; font-size:24px; color:#e8dfc8;\n    border:2px solid var(--line);\n  }\n  .name{ font-family:'Fraunces', serif; font-weight:600; font-size:19px; margin-bottom:4px; }\n  .email{ font-size:12.5px; color:var(--dim); margin-bottom:28px; }\n\n  .field{ position:relative; margin-bottom:8px; text-align:left; }\n  .field label{ display:block; font-size:11px; letter-spacing:.04em; color:var(--dim); margin-bottom:7px; }\n  .field input{ width:100%; background:#fffdf8; border:1.5px solid var(--line); color:var(--ink); font-size:15px; padding:11px 34px 11px 12px; border-radius:3px; outline:none; transition:border-color .2s ease; }\n  .field input:focus{ border-color:var(--gold); }\n  .eye-btn{ position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer; color:var(--dim); display:flex; align-items:center; justify-content:center; }\n  .eye-btn:hover{ color:var(--gold); }\n  .eye-btn svg{ width:15px; height:15px; }\n\n  .error-msg{ font-size:12px; color:#b5453a; text-align:left; min-height:16px; margin:6px 0 14px; }\n\n  button.enter{ width:100%; background:var(--ink); border:none; color:#fdf8ef; font-size:13.5px; font-weight:600; padding:14px; border-radius:3px; cursor:pointer; margin-top:8px; transition:background .25s ease, transform .1s ease; }\n  button.enter:hover{ background:#3a281f; }\n  button.enter:active{ transform:scale(.99); }\n\n  .alt{ margin-top:22px; display:flex; flex-direction:column; gap:10px; }\n  .alt button{ background:none; border:1px solid var(--line); color:var(--ink); font-size:12.5px; padding:10px; border-radius:3px; cursor:pointer; transition:border-color .2s ease; }\n  .alt button:hover{ border-color:var(--gold); }\n  .switch{ margin-top:18px; font-size:12px; color:var(--dim); }\n  .switch a{ color:var(--gold); text-decoration:none; }\n  .switch a:hover{ text-decoration:underline; }\n</style>\n</head>\n<body>\n\n<div class=\"card\">\n  <div class=\"avatar\">JR</div>\n  <div class=\"name\">Welcome back, Jordan</div>\n  <div class=\"email\">jordan.rivera@company.com</div>\n\n  <form onsubmit=\"return false;\" id=\"lockForm\">\n    <div class=\"field\">\n      <label for=\"pwInput\">Password</label>\n      <input type=\"password\" id=\"pwInput\" placeholder=\"Enter your password\" required autocomplete=\"current-password\" class=\"has-eye\" />\n      <button type=\"button\" class=\"eye-btn\" id=\"eyeBtn\" aria-label=\"Show password\" aria-pressed=\"false\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>\n      </button>\n    </div>\n    <p class=\"error-msg\" id=\"errorMsg\"></p>\n    <button class=\"enter\" type=\"submit\">Unlock</button>\n  </form>\n\n  <div class=\"alt\">\n    <button type=\"button\">Use a passkey instead</button>\n  </div>\n\n  <p class=\"switch\">Not Jordan? <a href=\"#\">Sign in as someone else</a></p>\n</div>\n\n<script>\n(function(){\n  var eyeBtn = document.getElementById('eyeBtn');\n  var pwInput = document.getElementById('pwInput');\n  var showing = false;\n  eyeBtn.addEventListener('click', function(){\n    showing = !showing;\n    pwInput.type = showing ? 'text' : 'password';\n    eyeBtn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n    eyeBtn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n  });\n\n  document.getElementById('lockForm').addEventListener('submit', function(){\n    document.getElementById('errorMsg').textContent = '';\n  });\n\n  window.addEventListener('message', function(e){\n    if(e.data && e.data.type === 'loginkit-accent'){\n      document.documentElement.style.setProperty('--gold', e.data.color);\n    }\n  });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "fielding-magic-link", "file": "forms/fielding-magic-link.html", "title": "Fielding & Co.", "layout": "Passwordless Magic Link", "layout_key": "magic-link", "palette": "Linen & Terracotta", "palette_key": "linen-terracotta", "blurb": "No password to type or leak: one email field, one link sent, and a real confirmation state with a resend option.", "n": 15, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Fielding &amp; Co. \u2014 Sign In</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,600;1,9..144,500&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --linen:#f7f1e4; --card:#fffdf8; --line:#ddccae; --terracotta:#b5552e; --terracotta-bright:#d47245;\n    --ink:#241a16; --dim:#8a7458;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--linen); color:var(--ink); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:flex; align-items:center; justify-content:center; padding:60px 24px;\n  }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n  :focus-visible{ outline:1px solid var(--terracotta); outline-offset:2px; }\n\n  .card{\n    width:100%; max-width:380px; background:var(--card); border:1px solid var(--line); border-radius:3px; padding:44px 38px;\n    box-shadow:0 30px 70px -34px rgba(110,60,35,0.3);\n    opacity:0; transform:translateY(14px); animation:reveal .85s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.1s;\n  }\n  @keyframes reveal{ to{ opacity:1; transform:none; } }\n\n  .mark{ font-size:11px; letter-spacing:.2em; color:var(--terracotta); margin-bottom:20px; }\n\n  .view{ display:block; }\n  .view[hidden]{ display:none; }\n\n  h1{ font-family:'Fraunces', serif; font-weight:600; font-size:27px; margin-bottom:8px; }\n  .sub{ font-size:13.5px; color:var(--dim); margin-bottom:30px; line-height:1.5; }\n\n  .field{ margin-bottom:22px; }\n  .field label{ display:block; font-size:11px; letter-spacing:.04em; color:var(--dim); margin-bottom:7px; }\n  .field input{ width:100%; background:none; border:none; border-bottom:1.5px solid var(--line); color:var(--ink); font-size:16px; padding:10px 0; outline:none; transition:border-color .25s ease; }\n  .field input:focus{ border-color:var(--terracotta); }\n\n  button.enter{ position:relative; width:100%; background:var(--terracotta); border:none; color:#fdf6ee; font-family:'Fraunces', serif; font-style:italic; font-weight:600; font-size:17px; padding:14px; border-radius:3px; cursor:pointer; overflow:hidden; transition:background .25s ease, transform .1s ease; }\n  button.enter:hover{ background:var(--terracotta-bright); }\n  button.enter:active{ transform:scale(.99); }\n\n  .foot{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:26px; }\n  .foot a{ color:var(--terracotta); text-decoration:none; font-weight:600; }\n  .foot a:hover{ text-decoration:underline; }\n\n  /* success state */\n  .icon-wrap{ display:flex; justify-content:center; margin-bottom:22px; }\n  .icon-wrap svg{ width:52px; height:52px; }\n  .icon-wrap circle{ fill:none; stroke:var(--line); stroke-width:1.5; }\n  .icon-wrap path{ fill:none; stroke:var(--terracotta); stroke-width:2; stroke-linecap:round; stroke-linejoin:round;\n    stroke-dasharray:24; stroke-dashoffset:24; animation:draw .5s ease forwards; animation-delay:.3s; }\n  @keyframes draw{ to{ stroke-dashoffset:0; } }\n  .success h1{ text-align:center; }\n  .success .sub{ text-align:center; }\n  .success .sub b{ color:var(--ink); }\n  .resend-line{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:24px; }\n  .resend-line button{ background:none; border:none; color:var(--terracotta); font-size:12.5px; cursor:pointer; text-decoration:underline; padding:0; }\n</style>\n</head>\n<body>\n\n<div class=\"card\">\n  <div class=\"mark\">FIELDING &amp; CO.</div>\n\n  <div class=\"view\" id=\"requestView\">\n    <h1>Sign in without a password</h1>\n    <p class=\"sub\">We'll email you a one-time link \u2014 no password to remember or leak.</p>\n    <form id=\"magicForm\" onsubmit=\"return false;\">\n      <div class=\"field\">\n        <label for=\"emailInput\">Email address</label>\n        <input type=\"email\" id=\"emailInput\" placeholder=\"you@company.com\" required autocomplete=\"email\" />\n      </div>\n      <button class=\"enter\" type=\"submit\">Send magic link</button>\n    </form>\n    <p class=\"foot\">Prefer a password? <a href=\"#\">Use one instead</a></p>\n  </div>\n\n  <div class=\"view success\" id=\"sentView\" hidden>\n    <div class=\"icon-wrap\">\n      <svg viewBox=\"0 0 52 52\"><circle cx=\"26\" cy=\"26\" r=\"24\"/><path d=\"M15 27l7 7 15-15\"/></svg>\n    </div>\n    <h1>Check your inbox</h1>\n    <p class=\"sub\">We sent a sign-in link to <b id=\"sentEmail\">you@company.com</b>. It expires in 15 minutes.</p>\n    <p class=\"resend-line\">Didn't get it? <button type=\"button\" id=\"resendBtn\">Resend link</button></p>\n  </div>\n</div>\n\n<script>\n(function(){\n  var form = document.getElementById('magicForm');\n  var requestView = document.getElementById('requestView');\n  var sentView = document.getElementById('sentView');\n  var emailInput = document.getElementById('emailInput');\n  var sentEmail = document.getElementById('sentEmail');\n  var resendBtn = document.getElementById('resendBtn');\n\n  form.addEventListener('submit', function(){\n    sentEmail.textContent = emailInput.value || 'you@company.com';\n    requestView.hidden = true;\n    sentView.hidden = false;\n  });\n\n  resendBtn.addEventListener('click', function(){\n    resendBtn.textContent = 'Link resent \u2713';\n    resendBtn.disabled = true;\n    setTimeout(function(){\n      resendBtn.textContent = 'Resend link';\n      resendBtn.disabled = false;\n    }, 3000);\n  });\n\n  window.addEventListener('message', function(e){\n    if(e.data && e.data.type === 'loginkit-accent'){\n      document.documentElement.style.setProperty('--terracotta', e.data.color);\n    }\n  });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "atelier-noir", "file": "forms/atelier-noir.html", "title": "Atelier Noir", "layout": "Split Screen + Drape Reveal", "layout_key": "split-drape", "palette": "Monochrome Chalk", "palette_key": "mono-chalk", "blurb": "A fashion house: a silk drape unfurls via clip-path on load; the button's letter-spacing widens instead of filling with color.", "n": 16, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Atelier Noir \u2014 Sign In</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;1,500&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --ink:#0d0d0d; --card:#151515; --line:rgba(255,255,255,0.1); --chalk:#f2efe9; --chalk-dim:#8f8b83;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--ink); color:var(--chalk); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:grid; grid-template-columns:1fr 1fr; overflow:hidden;\n  }\n  @media(max-width:860px){ body{ grid-template-columns:1fr; } .drape-side{ display:none; } }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n  :focus-visible{ outline:1px solid var(--chalk); outline-offset:2px; }\n\n  .drape-side{ position:relative; background:#000; overflow:hidden; }\n  .drape{\n    position:absolute; inset:-10%; background:linear-gradient(150deg, #1c1c1c, #050505 60%);\n    clip-path:polygon(0 0, 100% 0, 100% 55%, 60% 70%, 100% 85%, 100% 100%, 0 100%);\n    animation:drapeIn 1.4s cubic-bezier(.16,1,.3,1) forwards;\n  }\n  @keyframes drapeIn{\n    from{ clip-path:polygon(0 0, 100% 0, 100% 0%, 60% 0%, 100% 0%, 100% 0%, 0 0%); }\n    to{ clip-path:polygon(0 0, 100% 0, 100% 55%, 60% 70%, 100% 85%, 100% 100%, 0 100%); }\n  }\n  .drape-label{ position:absolute; bottom:50px; left:50px; font-family:'Cormorant Garamond', serif; font-style:italic; font-size:22px; color:var(--chalk-dim);\n    opacity:0; animation:fadeIn .8s ease forwards; animation-delay:1.2s; }\n  @keyframes fadeIn{ to{ opacity:1; } }\n\n  .form-side{ display:flex; align-items:center; justify-content:center; padding:48px; }\n  .panel{ width:100%; max-width:360px;\n    opacity:0; transform:translateY(14px); animation:reveal .9s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.2s; }\n  @keyframes reveal{ to{ opacity:1; transform:none; } }\n\n  .brand{ font-size:11px; letter-spacing:.28em; color:var(--chalk-dim); margin-bottom:26px; }\n  h1{ font-family:'Cormorant Garamond', serif; font-weight:500; font-size:30px; margin-bottom:8px; }\n  .sub{ font-size:13.5px; color:var(--chalk-dim); margin-bottom:32px; }\n\n  .tabs{ display:flex; gap:26px; margin-bottom:30px; }\n  .tabs button{ background:none; border:1px solid transparent; color:var(--chalk-dim); font-size:11px; letter-spacing:.1em; text-transform:uppercase; padding:0 0 8px; cursor:pointer; transition:color .3s ease, border-color .3s ease; }\n  .tabs button.active{ color:var(--chalk); border-bottom-color:var(--chalk); }\n\n  .field{ margin-bottom:22px; }\n  .field label{ display:block; font-size:10.5px; letter-spacing:.08em; text-transform:uppercase; color:var(--chalk-dim); margin-bottom:8px; }\n  .field input{ width:100%; background:none; border:none; border-bottom:1px solid var(--line); color:var(--chalk); font-size:15px; padding:8px 32px 8px 0; outline:none; transition:border-color .3s ease; }\n  .field input:focus{ border-color:var(--chalk); }\n  .field input::placeholder{ color:var(--chalk-dim); opacity:.4; }\n  .extra{ max-height:0; opacity:0; overflow:hidden; transition:max-height .5s cubic-bezier(.4,0,.2,1), opacity .35s ease; }\n  .eye-btn{ position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer; color:var(--chalk-dim); display:flex; }\n  .eye-btn:hover{ color:var(--chalk); }\n  .eye-btn svg{ width:15px; height:15px; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--chalk-dim); margin:0 0 30px; }\n  .row-between a{ color:var(--chalk-dim); text-decoration:none; border-bottom:1px solid var(--line); }\n  .row-between a:hover{ color:var(--chalk); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--chalk); width:13px; height:13px; }\n\n  button.enter{\n    width:100%; background:none; border:1px solid var(--chalk); color:var(--chalk); font-size:12px; font-weight:500;\n    letter-spacing:.14em; text-transform:uppercase; padding:15px; cursor:pointer; transition:letter-spacing .35s ease, background .35s ease, color .35s ease;\n  }\n  button.enter:hover{ letter-spacing:.22em; background:var(--chalk); color:#0d0d0d; }\n  button.enter:active{ letter-spacing:.14em; }\n\n  .divider{ display:flex; align-items:center; gap:14px; margin:26px 0; color:var(--chalk-dim); font-size:10.5px; letter-spacing:.08em; text-transform:uppercase; }\n  .divider::before,.divider::after{ content:\"\"; flex:1; height:1px; background:var(--line); }\n  button.ghost{ width:100%; background:none; border:1px solid var(--line); color:var(--chalk); font-size:13px; padding:12px; cursor:pointer; transition:border-color .2s ease; }\n  button.ghost:hover{ border-color:var(--chalk); }\n  .foot{ text-align:center; font-size:12px; color:var(--chalk-dim); margin-top:24px; }\n  .foot a{ color:var(--chalk); text-decoration:none; cursor:pointer; border-bottom:1px solid var(--chalk); }\n</style>\n</head>\n<body>\n\n<div class=\"drape-side\"><div class=\"drape\"></div><div class=\"drape-label\">Collection No. 12</div></div>\n\n<div class=\"form-side\">\n  <div class=\"panel\">\n    <div class=\"brand\">ATELIER NOIR</div>\n    <h1 id=\"heading\">Sign in</h1>\n    <p class=\"sub\" id=\"subhead\">Private client access and fitting schedule.</p>\n\n    <div class=\"tabs\" id=\"tabs\">\n      <button class=\"active\" data-tab=\"signin\" type=\"button\">Sign In</button>\n      <button data-tab=\"signup\" type=\"button\">Register</button>\n    </div>\n\n    <form onsubmit=\"return false;\">\n      <div class=\"field extra\" id=\"nameField\" style=\"position:relative;\">\n        <label for=\"nameInput\">Full name</label>\n        <input type=\"text\" id=\"nameInput\" placeholder=\"Jordan Rivera\" autocomplete=\"name\" />\n      </div>\n      <div class=\"field\" style=\"position:relative;\">\n        <label for=\"emailInput\">Email address</label>\n        <input type=\"email\" id=\"emailInput\" placeholder=\"you@company.com\" required autocomplete=\"email\" />\n      </div>\n      <div class=\"field\" style=\"position:relative;\">\n        <label for=\"pwInput\">Password</label>\n        <input type=\"password\" id=\"pwInput\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\" required autocomplete=\"current-password\" class=\"has-eye\" />\n        <button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n      </div>\n      <div class=\"row-between\" id=\"signinOnlyRow\">\n        <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n        <a href=\"#\">Forgot password?</a>\n      </div>\n      <button class=\"enter\" type=\"submit\"><span id=\"submitLabel\">Sign In</span></button>\n    </form>\n\n    <div class=\"divider\">or continue with</div>\n    <button class=\"ghost\" type=\"button\">Google</button>\n\n    <p class=\"foot\" id=\"footNote\">New client? <a data-switch=\"signup\">Register</a></p>\n  </div>\n</div>\n\n<script>\n(function(){\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n    });\n  });\n\n  var tabs = document.querySelectorAll('#tabs button[data-tab]');\n  var nameField = document.getElementById('nameField');\n  var signinOnlyRow = document.getElementById('signinOnlyRow');\n  var heading = document.getElementById('heading');\n  var subhead = document.getElementById('subhead');\n  var submitLabel = document.getElementById('submitLabel');\n  var footNote = document.getElementById('footNote');\n\n  var COPY = {\n    signin: { heading:'Sign in', sub:'Private client access and fitting schedule.', submit:'Sign In', foot:'New client? <a data-switch=\"signup\">Register</a>' },\n    signup: { heading:'Register', sub:'Create a client profile in under a minute.', submit:'Register', foot:'Already a client? <a data-switch=\"signin\">Sign in</a>' }\n  };\n  function bindSwitchLinks(){ document.querySelectorAll('[data-switch]').forEach(function(a){ a.addEventListener('click', function(e){ e.preventDefault(); setMode(a.getAttribute('data-switch')); }); }); }\n  function setMode(mode){\n    tabs.forEach(function(t){ t.classList.toggle('active', t.dataset.tab===mode); });\n    var showExtra = mode==='signup';\n    nameField.style.maxHeight = showExtra ? nameField.scrollHeight+'px' : '0px';\n    nameField.style.opacity = showExtra?1:0;\n    signinOnlyRow.style.display = mode==='signin' ? 'flex' : 'none';\n    heading.textContent = COPY[mode].heading;\n    subhead.textContent = COPY[mode].sub;\n    submitLabel.textContent = COPY[mode].submit;\n    footNote.innerHTML = COPY[mode].foot;\n    bindSwitchLinks();\n  }\n  tabs.forEach(function(t){ t.addEventListener('click', function(){ setMode(t.dataset.tab); }); });\n  bindSwitchLinks();\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--chalk', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "the-cartographer", "file": "forms/the-cartographer.html", "title": "The Cartographer's Society", "layout": "Pill Tab + Compass Entrance", "layout_key": "pill-compass", "palette": "Parchment & Teal", "palette_key": "parchment-teal", "blurb": "A travel society: a compass needle swings and settles to north before the form appears.", "n": 17, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>The Cartographer's Society \u2014 Sign In</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,600;1,500&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --parchment:#ede0c0; --card:#f7f0da; --teal:#1f4d47; --teal-bright:#2c6a61; --line:#d8c898; --ink:#2b2415; --dim:#8a7d55;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--parchment); color:var(--ink); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:flex; align-items:center; justify-content:center; padding:60px 24px; position:relative; overflow:hidden;\n  }\n  body::before{\n    content:\"\"; position:fixed; inset:0; opacity:.5; pointer-events:none;\n    background-image:radial-gradient(circle at 20% 30%, transparent 0, transparent 60px, rgba(31,77,71,0.04) 61px, transparent 63px),\n      radial-gradient(circle at 80% 70%, transparent 0, transparent 90px, rgba(31,77,71,0.04) 91px, transparent 93px);\n  }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n  :focus-visible{ outline:1px solid var(--teal); outline-offset:2px; }\n\n  .stage{ position:relative; z-index:1; width:100%; max-width:380px; text-align:center; }\n\n  .compass-wrap{ display:flex; justify-content:center; margin-bottom:20px; }\n  .compass{ width:58px; height:58px; }\n  .compass circle{ fill:none; stroke:var(--teal); stroke-width:1; opacity:.5; }\n  .compass .tick{ stroke:var(--teal); stroke-width:1; opacity:.4; }\n  .needle{ transform-origin:29px 29px; animation:settle 1.3s cubic-bezier(.34,1.56,.64,1) forwards; }\n  @keyframes settle{ 0%{ transform:rotate(-140deg); } 60%{ transform:rotate(20deg); } 100%{ transform:rotate(0deg); } }\n  .needle path{ fill:var(--teal); }\n\n  .brand{ font-size:11px; letter-spacing:.2em; color:var(--teal); margin-bottom:14px;\n    opacity:0; animation:fadeIn .7s ease forwards; animation-delay:.9s; }\n  h1{ font-family:'Playfair Display', serif; font-weight:600; font-size:27px; margin-bottom:8px;\n    opacity:0; animation:fadeUp .7s cubic-bezier(.16,1,.3,1) forwards; animation-delay:1s; }\n  .sub{ font-size:13.5px; color:var(--dim); margin-bottom:30px;\n    opacity:0; animation:fadeUp .7s cubic-bezier(.16,1,.3,1) forwards; animation-delay:1.06s; }\n  @keyframes fadeIn{ to{ opacity:1; } }\n  @keyframes fadeUp{ to{ opacity:1; transform:none; } }\n  h1, .sub{ transform:translateY(8px); }\n\n  .panel{ text-align:left; background:var(--card); border:1px solid var(--line); padding:36px 32px; border-radius:2px;\n    opacity:0; animation:fadeUp .8s cubic-bezier(.16,1,.3,1) forwards; animation-delay:1.12s; }\n\n  .tabs{ position:relative; display:flex; gap:4px; margin-bottom:28px; background:rgba(31,77,71,0.06); border-radius:999px; padding:4px; }\n  .tabs button{ position:relative; z-index:2; flex:1; background:none; border:none; color:var(--dim); font-size:12px; font-weight:600; padding:9px 0; cursor:pointer; transition:color .3s ease; border-radius:999px; }\n  .tabs button.active{ color:#f7f0da; }\n  .tab-indicator{ position:absolute; top:4px; bottom:4px; z-index:1; border-radius:999px; background:var(--teal); transition:transform .45s cubic-bezier(.65,0,.35,1), width .45s cubic-bezier(.65,0,.35,1); }\n\n  .field{ position:relative; margin-bottom:22px; }\n  .field label{ display:block; font-size:11px; letter-spacing:.04em; color:var(--dim); margin-bottom:7px; }\n  .field input{ width:100%; background:var(--parchment); border:1.5px solid var(--line); color:var(--ink); font-size:15px; padding:10px 12px; outline:none; transition:border-color .2s ease; }\n  .field input:focus{ border-color:var(--teal); }\n  .field input::placeholder{ color:var(--dim); opacity:.5; }\n  .extra{ max-height:0; opacity:0; overflow:hidden; transition:max-height .5s cubic-bezier(.4,0,.2,1), opacity .35s ease; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--dim); margin:0 0 26px; }\n  .row-between a{ color:var(--dim); text-decoration:none; border-bottom:1px solid var(--line); }\n  .row-between a:hover{ color:var(--teal); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--teal); width:13px; height:13px; }\n\n  button.enter{ width:100%; background:var(--teal); border:none; color:#f7f0da; font-size:13.5px; font-weight:600; padding:14px; border-radius:2px; cursor:pointer; transition:background .25s ease, transform .1s ease; }\n  button.enter:hover{ background:var(--teal-bright); }\n  button.enter:active{ transform:scale(.99); }\n\n  .divider{ display:flex; align-items:center; gap:14px; margin:24px 0; color:var(--dim); font-size:11px; }\n  .divider::before,.divider::after{ content:\"\"; flex:1; height:1px; background:var(--line); }\n  button.ghost{ width:100%; background:none; border:1px solid var(--line); color:var(--ink); font-size:13px; padding:12px; cursor:pointer; transition:border-color .2s ease; }\n  button.ghost:hover{ border-color:var(--teal); }\n  .foot{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:22px; }\n  .foot a{ color:var(--teal); text-decoration:none; font-weight:600; }\n  .foot a:hover{ text-decoration:underline; }\n</style>\n</head>\n<body>\n\n<div class=\"stage\">\n  <div class=\"compass-wrap\">\n    <svg class=\"compass\" viewBox=\"0 0 58 58\">\n      <circle cx=\"29\" cy=\"29\" r=\"26\"/><circle cx=\"29\" cy=\"29\" r=\"19\"/>\n      <g class=\"tick\"><line x1=\"29\" y1=\"4\" x2=\"29\" y2=\"10\"/><line x1=\"29\" y1=\"48\" x2=\"29\" y2=\"54\"/><line x1=\"4\" y1=\"29\" x2=\"10\" y2=\"29\"/><line x1=\"48\" y1=\"29\" x2=\"54\" y2=\"29\"/></g>\n      <g class=\"needle\"><path d=\"M29 12 L33 29 L29 46 L25 29 Z\"/></g>\n    </svg>\n  </div>\n\n  <div class=\"brand\">THE CARTOGRAPHER'S SOCIETY</div>\n  <h1 id=\"heading\">Sign in</h1>\n  <p class=\"sub\" id=\"subhead\">Your expeditions, charts, and field notes.</p>\n\n  <div class=\"panel\">\n    <div class=\"tabs\" id=\"tabs\">\n      <button class=\"active\" data-tab=\"signin\" type=\"button\">Sign In</button>\n      <button data-tab=\"signup\" type=\"button\">Join</button>\n      <span class=\"tab-indicator\" id=\"tabIndicator\"></span>\n    </div>\n\n    <form onsubmit=\"return false;\">\n      <div class=\"field extra\" id=\"nameField\">\n        <label for=\"nameInput\">Full name</label>\n        <input type=\"text\" id=\"nameInput\" placeholder=\"Jordan Rivera\" autocomplete=\"name\" />\n      </div>\n      <div class=\"field\">\n        <label for=\"emailInput\">Email address</label>\n        <input type=\"email\" id=\"emailInput\" placeholder=\"you@company.com\" required autocomplete=\"email\" />\n      </div>\n      <div class=\"field\">\n        <label for=\"pwInput\">Password</label>\n        <input type=\"password\" id=\"pwInput\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\" required autocomplete=\"current-password\" class=\"has-eye\" style=\"padding-right:34px;\" />\n        <button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\" style=\"position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer; color:var(--dim);\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" width=\"15\" height=\"15\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n      </div>\n      <div class=\"row-between\" id=\"signinOnlyRow\">\n        <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n        <a href=\"#\">Forgot password?</a>\n      </div>\n      <button class=\"enter\" type=\"submit\"><span id=\"submitLabel\">Sign In</span></button>\n    </form>\n\n    <div class=\"divider\">or continue with</div>\n    <button class=\"ghost\" type=\"button\">Google</button>\n\n    <p class=\"foot\" id=\"footNote\">New here? <a data-switch=\"signup\">Join the Society</a></p>\n  </div>\n</div>\n\n<script>\n(function(){\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n    });\n  });\n\n  var tabs = document.querySelectorAll('#tabs button[data-tab]');\n  var indicator = document.getElementById('tabIndicator');\n  var nameField = document.getElementById('nameField');\n  var signinOnlyRow = document.getElementById('signinOnlyRow');\n  var heading = document.getElementById('heading');\n  var subhead = document.getElementById('subhead');\n  var submitLabel = document.getElementById('submitLabel');\n  var footNote = document.getElementById('footNote');\n\n  var COPY = {\n    signin: { heading:'Sign in', sub:'Your expeditions, charts, and field notes.', submit:'Sign In', foot:'New here? <a data-switch=\"signup\">Join the Society</a>' },\n    signup: { heading:'Join the Society', sub:'Membership includes the annual atlas.', submit:'Join', foot:'Already a member? <a data-switch=\"signin\">Sign in</a>' }\n  };\n  function positionIndicator(el){ indicator.style.width = el.offsetWidth+'px'; indicator.style.transform = 'translateX('+el.offsetLeft+'px)'; }\n  function bindSwitchLinks(){ document.querySelectorAll('[data-switch]').forEach(function(a){ a.addEventListener('click', function(e){ e.preventDefault(); setMode(a.getAttribute('data-switch')); }); }); }\n  function setMode(mode){\n    tabs.forEach(function(t){ t.classList.toggle('active', t.dataset.tab===mode); if(t.dataset.tab===mode) positionIndicator(t); });\n    var showExtra = mode==='signup';\n    nameField.style.maxHeight = showExtra ? nameField.scrollHeight+'px' : '0px';\n    nameField.style.opacity = showExtra?1:0;\n    signinOnlyRow.style.display = mode==='signin' ? 'flex' : 'none';\n    heading.textContent = COPY[mode].heading;\n    subhead.textContent = COPY[mode].sub;\n    submitLabel.textContent = COPY[mode].submit;\n    footNote.innerHTML = COPY[mode].foot;\n    bindSwitchLinks();\n  }\n  tabs.forEach(function(t){ t.addEventListener('click', function(){ setMode(t.dataset.tab); }); });\n  bindSwitchLinks();\n  window.addEventListener('load', function(){ positionIndicator(document.querySelector('#tabs button.active')); });\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--teal', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "lumen-optics", "file": "forms/lumen-optics.html", "title": "Lumen Optics", "layout": "Underline Tab + Iris Reveal", "layout_key": "underline-iris", "palette": "Graphite & Steel", "palette_key": "graphite-steel", "blurb": "An eyewear brand: six camera-aperture blades snap open to reveal the page, echoed again in the button's radial hover fill.", "n": 18, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Lumen Optics \u2014 Sign In</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,600&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --graphite:#161819; --card:#1d2022; --steel:#b9c2c4; --steel-bright:#e2e8e9; --line:rgba(185,194,196,0.14); --dim:#7d8688;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--graphite); color:var(--steel-bright); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:flex; align-items:center; justify-content:center; padding:60px 24px; position:relative; overflow:hidden;\n  }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n  :focus-visible{ outline:1px solid var(--steel-bright); outline-offset:2px; }\n\n  .iris{ position:fixed; inset:0; pointer-events:none; z-index:2; }\n  .iris path{ fill:var(--graphite); }\n  .blade{ transform-origin:50% 50%; animation:open .9s cubic-bezier(.65,0,.35,1) forwards; }\n  .blade:nth-child(1){ animation-delay:0s; } .blade:nth-child(2){ animation-delay:.03s; }\n  .blade:nth-child(3){ animation-delay:.06s; } .blade:nth-child(4){ animation-delay:.09s; }\n  .blade:nth-child(5){ animation-delay:.12s; } .blade:nth-child(6){ animation-delay:.15s; }\n  @keyframes open{ from{ transform:scale(1); } to{ transform:scale(2.4); } }\n\n  .stage{ position:relative; z-index:1; width:100%; max-width:370px; text-align:center;\n    opacity:0; animation:fadeIn .6s ease forwards; animation-delay:.7s; }\n  @keyframes fadeIn{ to{ opacity:1; } }\n\n  .brand{ font-size:11px; letter-spacing:.24em; color:var(--steel); margin-bottom:16px; }\n  h1{ font-family:'Fraunces', serif; font-weight:600; font-size:27px; margin-bottom:8px; }\n  .sub{ font-size:13.5px; color:var(--dim); margin-bottom:32px; }\n\n  .panel{ text-align:left; }\n\n  .tabs{ position:relative; display:flex; gap:24px; margin-bottom:28px; border-bottom:1px solid var(--line); }\n  .tabs button{ background:none; border:none; color:var(--dim); font-size:12.5px; font-weight:500; padding:0 0 12px; cursor:pointer; transition:color .3s ease; }\n  .tabs button.active{ color:var(--steel-bright); }\n  .tab-indicator{ position:absolute; bottom:-1px; height:1.5px; background:var(--steel-bright); transition:transform .5s cubic-bezier(.65,0,.35,1), width .5s cubic-bezier(.65,0,.35,1); }\n\n  .field{ position:relative; margin-bottom:24px; }\n  .field label{ position:absolute; left:0; top:11px; font-size:14px; color:var(--dim); pointer-events:none; transition:transform .3s cubic-bezier(.4,0,.2,1), font-size .3s ease, color .3s ease; transform-origin:left top; }\n  .field input{ width:100%; background:none; border:none; border-bottom:1px solid var(--line); color:var(--steel-bright); font-size:15px; padding:10px 0; outline:none; transition:border-color .3s ease; }\n  .field input:focus{ border-color:var(--steel-bright); }\n  .field input:focus + label, .field input:not(:placeholder-shown) + label{ transform:translateY(-19px); font-size:11px; color:var(--steel-bright); }\n  .field input::placeholder{ color:transparent; }\n  .extra{ max-height:0; opacity:0; overflow:hidden; transition:max-height .5s cubic-bezier(.4,0,.2,1), opacity .35s ease; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--dim); margin:0 0 28px; }\n  .row-between a{ color:var(--dim); text-decoration:none; border-bottom:1px solid var(--line); }\n  .row-between a:hover{ color:var(--steel-bright); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--steel); width:13px; height:13px; }\n\n  button.enter{\n    position:relative; width:100%; background:none; border:1px solid var(--steel); color:var(--steel-bright); font-size:13.5px; font-weight:600;\n    padding:14px; cursor:pointer; overflow:hidden; isolation:isolate; transition:color .4s ease .1s;\n  }\n  button.enter::before{ content:\"\"; position:absolute; left:50%; top:50%; width:0; height:0; border-radius:50%; background:var(--steel-bright); transform:translate(-50%,-50%); transition:width .5s cubic-bezier(.65,0,.35,1), height .5s cubic-bezier(.65,0,.35,1); z-index:-1; }\n  button.enter:hover{ color:#161819; }\n  button.enter:hover::before{ width:340px; height:340px; }\n\n  .divider{ display:flex; align-items:center; gap:14px; margin:24px 0; color:var(--dim); font-size:11px; }\n  .divider::before,.divider::after{ content:\"\"; flex:1; height:1px; background:var(--line); }\n  button.ghost{ width:100%; background:none; border:1px solid var(--line); color:var(--steel-bright); font-size:13px; padding:12px; cursor:pointer; transition:border-color .2s ease; }\n  button.ghost:hover{ border-color:var(--steel); }\n  .foot{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:22px; }\n  .foot a{ color:var(--steel-bright); text-decoration:none; cursor:pointer; }\n  .foot a:hover{ text-decoration:underline; }\n</style>\n</head>\n<body>\n\n<svg class=\"iris\" viewBox=\"0 0 100 100\" preserveAspectRatio=\"xMidYMid slice\">\n  <g transform=\"translate(50 50)\">\n    <path class=\"blade\" d=\"M0 0 L60 -10 A62 62 0 0 1 60 10 Z\"/>\n    <path class=\"blade\" d=\"M0 0 L52 32 A62 62 0 0 1 32 52 Z\"/>\n    <path class=\"blade\" d=\"M0 0 L-10 60 A62 62 0 0 1 -32 52 Z\"/>\n    <path class=\"blade\" d=\"M0 0 L-60 10 A62 62 0 0 1 -60 -10 Z\"/>\n    <path class=\"blade\" d=\"M0 0 L-32 -52 A62 62 0 0 1 -10 -60 Z\"/>\n    <path class=\"blade\" d=\"M0 0 L32 -52 A62 62 0 0 1 52 -32 Z\"/>\n  </g>\n</svg>\n\n<div class=\"stage\">\n  <div class=\"brand\">LUMEN OPTICS</div>\n  <h1 id=\"heading\">Sign in</h1>\n  <p class=\"sub\" id=\"subhead\">Your prescriptions, orders, and fitting history.</p>\n\n  <div class=\"panel\">\n    <div class=\"tabs\" id=\"tabs\">\n      <button class=\"active\" data-tab=\"signin\" type=\"button\">Sign in</button>\n      <button data-tab=\"signup\" type=\"button\">Create account</button>\n      <span class=\"tab-indicator\" id=\"tabIndicator\"></span>\n    </div>\n\n    <form onsubmit=\"return false;\">\n      <div class=\"field extra\" id=\"nameField\">\n        <input type=\"text\" placeholder=\" \" id=\"nameInput\" autocomplete=\"name\" />\n        <label for=\"nameInput\">Full name</label>\n      </div>\n      <div class=\"field\">\n        <input type=\"email\" placeholder=\" \" id=\"emailInput\" required autocomplete=\"email\" />\n        <label for=\"emailInput\">Email address</label>\n      </div>\n      <div class=\"field\">\n        <input type=\"password\" placeholder=\" \" id=\"pwInput\" required autocomplete=\"current-password\" class=\"has-eye\" style=\"padding-right:34px;\" />\n        <label for=\"pwInput\">Password</label>\n        <button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\" style=\"position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer; color:var(--dim);\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" width=\"15\" height=\"15\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n      </div>\n      <div class=\"row-between\" id=\"signinOnlyRow\">\n        <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n        <a href=\"#\">Forgot password?</a>\n      </div>\n      <button class=\"enter\" type=\"submit\"><span id=\"submitLabel\">Sign in</span></button>\n    </form>\n\n    <div class=\"divider\">or continue with</div>\n    <button class=\"ghost\" type=\"button\">Google</button>\n\n    <p class=\"foot\" id=\"footNote\">New here? <a data-switch=\"signup\">Create an account</a></p>\n  </div>\n</div>\n\n<script>\n(function(){\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n    });\n  });\n\n  var tabs = document.querySelectorAll('#tabs button[data-tab]');\n  var indicator = document.getElementById('tabIndicator');\n  var nameField = document.getElementById('nameField');\n  var signinOnlyRow = document.getElementById('signinOnlyRow');\n  var heading = document.getElementById('heading');\n  var subhead = document.getElementById('subhead');\n  var submitLabel = document.getElementById('submitLabel');\n  var footNote = document.getElementById('footNote');\n\n  var COPY = {\n    signin: { heading:'Sign in', sub:'Your prescriptions, orders, and fitting history.', submit:'Sign in', foot:'New here? <a data-switch=\"signup\">Create an account</a>' },\n    signup: { heading:'Create your account', sub:'Save your prescription for faster reordering.', submit:'Create account', foot:'Already have an account? <a data-switch=\"signin\">Sign in</a>' }\n  };\n  function positionIndicator(el){ indicator.style.width = el.offsetWidth+'px'; indicator.style.transform = 'translateX('+el.offsetLeft+'px)'; }\n  function bindSwitchLinks(){ document.querySelectorAll('[data-switch]').forEach(function(a){ a.addEventListener('click', function(e){ e.preventDefault(); setMode(a.getAttribute('data-switch')); }); }); }\n  function setMode(mode){\n    tabs.forEach(function(t){ t.classList.toggle('active', t.dataset.tab===mode); if(t.dataset.tab===mode) positionIndicator(t); });\n    var showExtra = mode==='signup';\n    nameField.style.maxHeight = showExtra ? nameField.scrollHeight+'px' : '0px';\n    nameField.style.opacity = showExtra?1:0;\n    signinOnlyRow.style.display = mode==='signin' ? 'flex' : 'none';\n    heading.textContent = COPY[mode].heading;\n    subhead.textContent = COPY[mode].sub;\n    submitLabel.textContent = COPY[mode].submit;\n    footNote.innerHTML = COPY[mode].foot;\n    bindSwitchLinks();\n  }\n  tabs.forEach(function(t){ t.addEventListener('click', function(){ setMode(t.dataset.tab); }); });\n  bindSwitchLinks();\n  window.addEventListener('load', function(){ positionIndicator(document.querySelector('#tabs button.active')); });\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--steel-bright', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "sable-and-fox", "file": "forms/sable-and-fox.html", "title": "Sable & Fox", "layout": "Split Screen, Sign-In Only", "layout_key": "split-signin-only", "palette": "Charcoal & Copper", "palette_key": "charcoal-copper", "blurb": "A leather goods maker: a dashed stitch line draws itself around a frame on load, and again around the button on hover.", "n": 19, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Sable &amp; Fox \u2014 Client Sign In</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,600;1,9..144,500&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --charcoal:#171310; --card:#1f1a15; --copper:#b0714a; --copper-bright:#d3966a; --line:rgba(176,113,74,0.18); --cream:#f0e6da; --dim:#8f8073;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--charcoal); color:var(--cream); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:grid; grid-template-columns:1fr 1fr;\n  }\n  @media(max-width:860px){ body{ grid-template-columns:1fr; } .stitch-side{ display:none; } }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n  :focus-visible{ outline:1px solid var(--copper-bright); outline-offset:2px; }\n\n  .stitch-side{ position:relative; background:linear-gradient(160deg, #221b15, #171310); display:flex; align-items:center; justify-content:center; overflow:hidden; }\n  .stitch-frame{ width:70%; aspect-ratio:1; }\n  .stitch-frame rect{ fill:none; stroke:var(--copper); stroke-width:1.5; stroke-dasharray:6 5; stroke-dashoffset:600; animation:stitchDraw 2.2s ease forwards; animation-delay:.2s; }\n  @keyframes stitchDraw{ to{ stroke-dashoffset:0; } }\n  .stitch-mono{ font-family:'Fraunces', serif; font-style:italic; font-size:15px; color:var(--dim); text-align:center; margin-top:22px;\n    opacity:0; animation:fadeIn .7s ease forwards; animation-delay:2.3s; }\n  @keyframes fadeIn{ to{ opacity:1; } }\n  .stitch-wrap{ text-align:center; }\n\n  .form-side{ display:flex; align-items:center; justify-content:center; padding:48px; }\n  .panel{ width:100%; max-width:360px;\n    opacity:0; transform:translateY(14px); animation:reveal .9s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.15s; }\n  @keyframes reveal{ to{ opacity:1; transform:none; } }\n\n  .brand{ font-size:11px; letter-spacing:.22em; color:var(--copper); margin-bottom:16px; }\n  h1{ font-family:'Fraunces', serif; font-weight:600; font-size:27px; margin-bottom:8px; }\n  .sub{ font-size:13.5px; color:var(--dim); margin-bottom:32px; }\n\n  .field{ position:relative; margin-bottom:24px; }\n  .field label{ display:block; font-size:11px; letter-spacing:.04em; color:var(--dim); margin-bottom:8px; }\n  .field input{ width:100%; background:none; border:none; border-bottom:1px solid var(--line); color:var(--cream); font-size:15px; padding:9px 32px 9px 0; outline:none; transition:border-color .3s ease; }\n  .field input:focus{ border-color:var(--copper); }\n  .field input::placeholder{ color:var(--dim); opacity:.5; }\n  .eye-btn{ position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer; color:var(--dim); display:flex; }\n  .eye-btn:hover{ color:var(--copper-bright); }\n  .eye-btn svg{ width:15px; height:15px; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--dim); margin:0 0 28px; }\n  .row-between a{ color:var(--dim); text-decoration:none; border-bottom:1px solid var(--line); }\n  .row-between a:hover{ color:var(--copper-bright); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--copper); width:13px; height:13px; }\n\n  button.enter{\n    position:relative; width:100%; background:none; border:1.5px solid var(--copper); color:var(--copper-bright);\n    font-size:13.5px; font-weight:600; padding:13px; cursor:pointer; isolation:isolate; overflow:hidden;\n  }\n  button.enter .stitch-outline{ position:absolute; inset:-1.5px; pointer-events:none; }\n  button.enter .stitch-outline rect{ fill:none; stroke:var(--copper-bright); stroke-width:1.5; stroke-dasharray:4 4; stroke-dashoffset:200; transition:stroke-dashoffset .5s ease; }\n  button.enter:hover .stitch-outline rect{ stroke-dashoffset:0; }\n  button.enter span{ position:relative; }\n\n  .foot{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:26px; }\n  .foot a{ color:var(--copper-bright); text-decoration:none; font-weight:600; cursor:pointer; }\n  .foot a:hover{ text-decoration:underline; }\n</style>\n</head>\n<body>\n\n<div class=\"stitch-side\">\n  <div class=\"stitch-wrap\">\n    <svg class=\"stitch-frame\" viewBox=\"0 0 200 200\"><rect x=\"20\" y=\"20\" width=\"160\" height=\"160\" rx=\"4\"/></svg>\n    <div class=\"stitch-mono\">Sable &amp; Fox \u2014 Est. Leather Goods</div>\n  </div>\n</div>\n\n<div class=\"form-side\">\n  <div class=\"panel\">\n    <div class=\"brand\">SABLE &amp; FOX</div>\n    <h1>Client sign in</h1>\n    <p class=\"sub\">Your commissions, repairs, and care records.</p>\n\n    <form onsubmit=\"return false;\" id=\"signinForm\">\n      <div class=\"field\">\n        <label for=\"emailInput\">Email address</label>\n        <input type=\"email\" id=\"emailInput\" placeholder=\"you@company.com\" required autocomplete=\"email\" />\n      </div>\n      <div class=\"field\">\n        <label for=\"pwInput\">Password</label>\n        <input type=\"password\" id=\"pwInput\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\" required autocomplete=\"current-password\" class=\"has-eye\" />\n        <button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n      </div>\n      <div class=\"row-between\">\n        <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n        <a href=\"#\">Forgot password?</a>\n      </div>\n      <button class=\"enter\" type=\"submit\">\n        <span>Sign in</span>\n        <svg class=\"stitch-outline\" viewBox=\"0 0 100 46\" preserveAspectRatio=\"none\"><rect x=\"1\" y=\"1\" width=\"98\" height=\"44\"/></svg>\n      </button>\n    </form>\n\n    <p class=\"foot\">By appointment or referral. <a href=\"#\">Request an introduction</a></p>\n  </div>\n</div>\n\n<script>\n(function(){\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n    });\n  });\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--copper', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "northbound-post", "file": "forms/northbound-post.html", "title": "Northbound Post", "layout": "Wax Seal + Hard Shadow", "layout_key": "seal-hardshadow", "palette": "Cream & Crimson", "palette_key": "cream-crimson", "blurb": "A courier service: a wax seal stamps down onto the card before it settles, and the button presses with a hard offset shadow.", "n": 20, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Northbound Post \u2014 Sign In</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,600&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --cream:#f6ede0; --card:#fffaf0; --crimson:#8a2432; --crimson-bright:#a8394a; --line:#e3cfae; --ink:#241a16; --dim:#8a7458;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--cream); color:var(--ink); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:flex; align-items:center; justify-content:center; padding:60px 24px;\n  }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n  :focus-visible{ outline:1px solid var(--crimson); outline-offset:2px; }\n\n  .stage{ width:100%; max-width:380px; }\n\n  .seal-wrap{ display:flex; justify-content:center; margin-bottom:8px; position:relative; z-index:2; }\n  .seal{ width:56px; height:56px; border-radius:50%; background:radial-gradient(circle at 35% 30%, var(--crimson-bright), var(--crimson) 70%);\n    display:flex; align-items:center; justify-content:center; font-family:'Fraunces', serif; color:#f6ede0; font-size:20px; font-weight:600;\n    box-shadow:0 8px 20px -6px rgba(138,36,50,0.5);\n    transform:scale(2.6) translateY(-10px); opacity:0; animation:stamp .5s cubic-bezier(.3,1.6,.4,1) forwards; animation-delay:.15s;\n  }\n  @keyframes stamp{ 0%{ transform:scale(2.6) translateY(-30px); opacity:0; } 60%{ transform:scale(.92) translateY(2px); opacity:1; } 100%{ transform:scale(1) translateY(0); opacity:1; } }\n\n  .card{\n    position:relative; margin-top:-28px; background:var(--card); border:1px solid var(--line); border-radius:3px; padding:44px 36px 36px;\n    box-shadow:0 30px 70px -34px rgba(138,36,50,0.22);\n    opacity:0; transform:translateY(10px); animation:fadeUp .7s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.5s;\n  }\n  @keyframes fadeUp{ to{ opacity:1; transform:none; } }\n\n  .brand{ text-align:center; font-size:11px; letter-spacing:.2em; color:var(--crimson); margin-bottom:16px; }\n  h1{ font-family:'Fraunces', serif; font-weight:600; font-size:24px; margin-bottom:6px; text-align:center; }\n  .sub{ font-size:13px; color:var(--dim); margin-bottom:28px; text-align:center; }\n\n  .tabs{ display:flex; gap:24px; justify-content:center; margin-bottom:26px; }\n  .tabs button{ background:none; border:1.5px solid transparent; color:var(--dim); font-size:12px; font-weight:600; padding:6px 0 8px; cursor:pointer; transition:color .3s ease, border-color .3s ease; }\n  .tabs button.active{ color:var(--crimson); border-bottom-color:var(--crimson); }\n\n  .field{ margin-bottom:20px; }\n  .field label{ display:block; font-size:11px; letter-spacing:.04em; color:var(--dim); margin-bottom:6px; }\n  .field input{ width:100%; background:var(--cream); border:1.5px solid var(--line); color:var(--ink); font-size:15px; padding:10px 32px 10px 12px; border-radius:2px; outline:none; transition:border-color .2s ease; }\n  .field input:focus{ border-color:var(--crimson); }\n  .field input::placeholder{ color:var(--dim); opacity:.55; }\n  .extra{ max-height:0; opacity:0; overflow:hidden; transition:max-height .5s cubic-bezier(.4,0,.2,1), opacity .35s ease; }\n  .field-wrap{ position:relative; }\n  .eye-btn{ position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer; color:var(--dim); display:flex; }\n  .eye-btn:hover{ color:var(--crimson); }\n  .eye-btn svg{ width:15px; height:15px; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--dim); margin:0 0 24px; }\n  .row-between a{ color:var(--dim); text-decoration:none; border-bottom:1px solid var(--line); }\n  .row-between a:hover{ color:var(--crimson); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--crimson); width:13px; height:13px; }\n\n  button.enter{ position:relative; width:100%; background:var(--crimson); border:none; color:var(--cream); font-size:13.5px; font-weight:600; padding:13px; border-radius:2px; cursor:pointer;\n    box-shadow:4px 4px 0 rgba(36,26,22,0.85); transition:transform .15s ease, box-shadow .15s ease; }\n  button.enter:hover{ transform:translate(-2px,-2px); box-shadow:6px 6px 0 rgba(36,26,22,0.85); }\n  button.enter:active{ transform:translate(2px,2px); box-shadow:1px 1px 0 rgba(36,26,22,0.85); }\n\n  .foot{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:22px; }\n  .foot a{ color:var(--crimson); text-decoration:none; font-weight:600; }\n  .foot a:hover{ text-decoration:underline; }\n</style>\n</head>\n<body>\n\n<div class=\"stage\">\n  <div class=\"seal-wrap\"><div class=\"seal\">N</div></div>\n\n  <div class=\"card\">\n    <div class=\"brand\">NORTHBOUND POST</div>\n    <h1 id=\"heading\">Track your parcels</h1>\n    <p class=\"sub\" id=\"subhead\">Sign in to your shipping account.</p>\n\n    <div class=\"tabs\" id=\"tabs\">\n      <button class=\"active\" data-tab=\"signin\" type=\"button\">Sign In</button>\n      <button data-tab=\"signup\" type=\"button\">Create account</button>\n    </div>\n\n    <form onsubmit=\"return false;\">\n      <div class=\"field extra\" id=\"nameField\"><div class=\"field-wrap\">\n        <label for=\"nameInput\">Full name</label>\n        <input type=\"text\" id=\"nameInput\" placeholder=\"Jordan Rivera\" autocomplete=\"name\" />\n      </div></div>\n      <div class=\"field\"><div class=\"field-wrap\">\n        <label for=\"emailInput\">Email address</label>\n        <input type=\"email\" id=\"emailInput\" placeholder=\"you@company.com\" required autocomplete=\"email\" />\n      </div></div>\n      <div class=\"field\"><div class=\"field-wrap\">\n        <label for=\"pwInput\">Password</label>\n        <input type=\"password\" id=\"pwInput\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\" required autocomplete=\"current-password\" class=\"has-eye\" />\n        <button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n      </div></div>\n      <div class=\"row-between\" id=\"signinOnlyRow\">\n        <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n        <a href=\"#\">Forgot password?</a>\n      </div>\n      <button class=\"enter\" type=\"submit\"><span id=\"submitLabel\">Sign In</span></button>\n    </form>\n\n    <p class=\"foot\" id=\"footNote\">New here? <a data-switch=\"signup\">Create an account</a></p>\n  </div>\n</div>\n\n<script>\n(function(){\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n    });\n  });\n\n  var tabs = document.querySelectorAll('#tabs button[data-tab]');\n  var nameField = document.getElementById('nameField');\n  var signinOnlyRow = document.getElementById('signinOnlyRow');\n  var heading = document.getElementById('heading');\n  var subhead = document.getElementById('subhead');\n  var submitLabel = document.getElementById('submitLabel');\n  var footNote = document.getElementById('footNote');\n\n  var COPY = {\n    signin: { heading:'Track your parcels', sub:'Sign in to your shipping account.', submit:'Sign In', foot:'New here? <a data-switch=\"signup\">Create an account</a>' },\n    signup: { heading:'Create your account', sub:'Track shipments and manage delivery preferences.', submit:'Create account', foot:'Already have an account? <a data-switch=\"signin\">Sign in</a>' }\n  };\n  function bindSwitchLinks(){ document.querySelectorAll('[data-switch]').forEach(function(a){ a.addEventListener('click', function(e){ e.preventDefault(); setMode(a.getAttribute('data-switch')); }); }); }\n  function setMode(mode){\n    tabs.forEach(function(t){ t.classList.toggle('active', t.dataset.tab===mode); });\n    var showExtra = mode==='signup';\n    nameField.style.maxHeight = showExtra ? nameField.scrollHeight+'px' : '0px';\n    nameField.style.opacity = showExtra?1:0;\n    signinOnlyRow.style.display = mode==='signin' ? 'flex' : 'none';\n    heading.textContent = COPY[mode].heading;\n    subhead.textContent = COPY[mode].sub;\n    submitLabel.textContent = COPY[mode].submit;\n    footNote.innerHTML = COPY[mode].foot;\n    bindSwitchLinks();\n  }\n  tabs.forEach(function(t){ t.addEventListener('click', function(){ setMode(t.dataset.tab); }); });\n  bindSwitchLinks();\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--crimson', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "the-orangery", "file": "forms/the-orangery.html", "title": "The Orangery", "layout": "Split Screen + Vine Growth", "layout_key": "split-vine", "palette": "Sage & Brass", "palette_key": "sage-brass", "blurb": "A botanical conservatory: a vine draws itself upward with leaves fading in along the way, behind a greenhouse windowpane grid.", "n": 21, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>The Orangery \u2014 Sign In</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;1,500&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --sage:#1c2b22; --card:#22332a; --brass:#b99a55; --brass-bright:#d4b76e; --line:rgba(185,154,85,0.16); --cream:#eef1ea; --dim:#8ea08f;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--sage); color:var(--cream); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:grid; grid-template-columns:1fr 1fr;\n  }\n  @media(max-width:860px){ body{ grid-template-columns:1fr; } .glass-side{ display:none; } }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n  :focus-visible{ outline:1px solid var(--brass-bright); outline-offset:2px; }\n\n  .glass-side{\n    position:relative; overflow:hidden; display:flex; align-items:center; justify-content:center;\n    background:\n      repeating-linear-gradient(0deg, rgba(185,154,85,0.05) 0 1px, transparent 1px 48px),\n      repeating-linear-gradient(90deg, rgba(185,154,85,0.05) 0 1px, transparent 1px 48px),\n      linear-gradient(170deg, #24362a, #1c2b22);\n  }\n  .vine{ width:60%; max-width:220px; }\n  .vine path{ fill:none; stroke:var(--brass); stroke-width:1.5; stroke-linecap:round; stroke-dasharray:400; stroke-dashoffset:400; animation:grow 2s cubic-bezier(.4,0,.2,1) forwards; animation-delay:.2s; }\n  @keyframes grow{ to{ stroke-dashoffset:0; } }\n  .leaf{ opacity:0; animation:leafIn .5s ease forwards; }\n  .leaf:nth-child(1){ animation-delay:.5s; } .leaf:nth-child(2){ animation-delay:.9s; }\n  .leaf:nth-child(3){ animation-delay:1.3s; } .leaf:nth-child(4){ animation-delay:1.7s; }\n  @keyframes leafIn{ to{ opacity:1; } }\n\n  .form-side{ display:flex; align-items:center; justify-content:center; padding:48px; }\n  .panel{ width:100%; max-width:360px;\n    opacity:0; transform:translateY(14px); animation:reveal .9s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.15s; }\n  @keyframes reveal{ to{ opacity:1; transform:none; } }\n\n  .brand{ font-size:11px; letter-spacing:.22em; color:var(--brass); margin-bottom:16px; }\n  h1{ font-family:'Cormorant Garamond', serif; font-weight:500; font-style:italic; font-size:29px; margin-bottom:8px; }\n  .sub{ font-size:13.5px; color:var(--dim); margin-bottom:30px; }\n\n  .tabs{ display:flex; gap:26px; margin-bottom:30px; }\n  .tabs button{ background:none; border:none; color:var(--dim); font-size:12.5px; font-weight:600; padding:0; cursor:pointer; transition:color .3s ease; }\n  .tabs button.active{ color:var(--brass-bright); }\n\n  .field{ margin-bottom:22px; }\n  .field label{ display:block; font-size:11px; letter-spacing:.04em; color:var(--dim); margin-bottom:8px; }\n  .field input{ width:100%; background:rgba(255,255,255,0.03); border:1px solid var(--line); color:var(--cream); font-size:15px; padding:10px 32px 10px 12px; border-radius:2px; outline:none; transition:border-color .2s ease; }\n  .field input:focus{ border-color:var(--brass); }\n  .field input::placeholder{ color:var(--dim); opacity:.5; }\n  .extra{ max-height:0; opacity:0; overflow:hidden; transition:max-height .5s cubic-bezier(.4,0,.2,1), opacity .35s ease; }\n  .field-wrap{ position:relative; }\n  .eye-btn{ position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer; color:var(--dim); display:flex; }\n  .eye-btn:hover{ color:var(--brass-bright); }\n  .eye-btn svg{ width:15px; height:15px; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--dim); margin:0 0 28px; }\n  .row-between a{ color:var(--dim); text-decoration:none; border-bottom:1px solid var(--line); }\n  .row-between a:hover{ color:var(--brass-bright); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--brass); width:13px; height:13px; }\n\n  button.enter{ position:relative; width:100%; background:transparent; border:1px solid var(--brass); color:var(--brass-bright); font-size:13.5px; font-weight:600;\n    padding:13px; cursor:pointer; overflow:hidden; isolation:isolate; transition:color .45s ease; }\n  button.enter::before{ content:\"\"; position:absolute; left:0; right:0; bottom:0; height:0%; background:linear-gradient(180deg, var(--brass-bright), var(--brass)); transition:height .45s cubic-bezier(.65,0,.35,1); z-index:-1; }\n  button.enter:hover{ color:#1c2b22; }\n  button.enter:hover::before{ height:100%; }\n\n  .foot{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:22px; }\n  .foot a{ color:var(--brass-bright); text-decoration:none; cursor:pointer; }\n  .foot a:hover{ text-decoration:underline; }\n</style>\n</head>\n<body>\n\n<div class=\"glass-side\">\n  <svg class=\"vine\" viewBox=\"0 0 100 240\">\n    <path d=\"M50 235 C 50 190, 30 170, 45 130 C 60 90, 40 70, 50 20\"/>\n    <circle class=\"leaf\" cx=\"38\" cy=\"170\" r=\"7\"/>\n    <circle class=\"leaf\" cx=\"58\" cy=\"120\" r=\"8\"/>\n    <circle class=\"leaf\" cx=\"36\" cy=\"80\" r=\"6\"/>\n    <circle class=\"leaf\" cx=\"56\" cy=\"40\" r=\"7\"/>\n  </svg>\n</div>\n\n<div class=\"form-side\">\n  <div class=\"panel\">\n    <div class=\"brand\">THE ORANGERY</div>\n    <h1 id=\"heading\">Welcome back</h1>\n    <p class=\"sub\" id=\"subhead\">Your plant care schedule and greenhouse notes.</p>\n\n    <div class=\"tabs\" id=\"tabs\">\n      <button class=\"active\" data-tab=\"signin\" type=\"button\">Sign in</button>\n      <button data-tab=\"signup\" type=\"button\">Create account</button>\n    </div>\n\n    <form onsubmit=\"return false;\">\n      <div class=\"field extra\" id=\"nameField\"><div class=\"field-wrap\">\n        <label for=\"nameInput\">Full name</label>\n        <input type=\"text\" id=\"nameInput\" placeholder=\"Jordan Rivera\" autocomplete=\"name\" />\n      </div></div>\n      <div class=\"field\"><div class=\"field-wrap\">\n        <label for=\"emailInput\">Email address</label>\n        <input type=\"email\" id=\"emailInput\" placeholder=\"you@company.com\" required autocomplete=\"email\" />\n      </div></div>\n      <div class=\"field\"><div class=\"field-wrap\">\n        <label for=\"pwInput\">Password</label>\n        <input type=\"password\" id=\"pwInput\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\" required autocomplete=\"current-password\" class=\"has-eye\" />\n        <button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n      </div></div>\n      <div class=\"row-between\" id=\"signinOnlyRow\">\n        <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n        <a href=\"#\">Forgot password?</a>\n      </div>\n      <button class=\"enter\" type=\"submit\"><span id=\"submitLabel\">Sign in</span></button>\n    </form>\n\n    <p class=\"foot\" id=\"footNote\">New here? <a data-switch=\"signup\">Create an account</a></p>\n  </div>\n</div>\n\n<script>\n(function(){\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n    });\n  });\n\n  var tabs = document.querySelectorAll('#tabs button[data-tab]');\n  var nameField = document.getElementById('nameField');\n  var signinOnlyRow = document.getElementById('signinOnlyRow');\n  var heading = document.getElementById('heading');\n  var subhead = document.getElementById('subhead');\n  var submitLabel = document.getElementById('submitLabel');\n  var footNote = document.getElementById('footNote');\n\n  var COPY = {\n    signin: { heading:'Welcome back', sub:'Your plant care schedule and greenhouse notes.', submit:'Sign in', foot:'New here? <a data-switch=\"signup\">Create an account</a>' },\n    signup: { heading:'Create your account', sub:'Track watering, light, and repotting for every plant.', submit:'Create account', foot:'Already have an account? <a data-switch=\"signin\">Sign in</a>' }\n  };\n  function bindSwitchLinks(){ document.querySelectorAll('[data-switch]').forEach(function(a){ a.addEventListener('click', function(e){ e.preventDefault(); setMode(a.getAttribute('data-switch')); }); }); }\n  function setMode(mode){\n    tabs.forEach(function(t){ t.classList.toggle('active', t.dataset.tab===mode); });\n    var showExtra = mode==='signup';\n    nameField.style.maxHeight = showExtra ? nameField.scrollHeight+'px' : '0px';\n    nameField.style.opacity = showExtra?1:0;\n    signinOnlyRow.style.display = mode==='signin' ? 'flex' : 'none';\n    heading.textContent = COPY[mode].heading;\n    subhead.textContent = COPY[mode].sub;\n    submitLabel.textContent = COPY[mode].submit;\n    footNote.innerHTML = COPY[mode].foot;\n    bindSwitchLinks();\n  }\n  tabs.forEach(function(t){ t.addEventListener('click', function(){ setMode(t.dataset.tab); }); });\n  bindSwitchLinks();\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--brass', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "constantine-and-reeve", "file": "forms/constantine-and-reeve.html", "title": "Constantine & Reeve", "layout": "Centered, Sign-In Only", "layout_key": "centered-signin-only", "palette": "Burgundy & Brass", "palette_key": "burgundy-brass", "blurb": "A barrister's chambers: flanking architectural column lines and a crest that settles into place \u2014 invite-only, no public sign-up.", "n": 22, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Constantine &amp; Reeve \u2014 Client Portal</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,600;1,500&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --burgundy:#1c0f12; --card:#241318; --brass:#b08d4f; --brass-bright:#d1af6f; --line:rgba(176,141,79,0.16); --cream:#efe6dd; --dim:#8f7d78;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--burgundy); color:var(--cream); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:flex; align-items:center; justify-content:center; padding:60px 24px; position:relative; overflow:hidden;\n  }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n  :focus-visible{ outline:1px solid var(--brass-bright); outline-offset:2px; }\n\n  .column{ position:fixed; top:0; bottom:0; width:1px; background:linear-gradient(180deg, transparent, var(--line) 15%, var(--line) 85%, transparent); }\n  .column.c1{ left:12%; } .column.c2{ left:22%; } .column.c3{ right:22%; } .column.c4{ right:12%; }\n\n  .stage{ position:relative; z-index:1; width:100%; max-width:380px; text-align:center;\n    opacity:0; animation:fadeIn .3s ease forwards; }\n  @keyframes fadeIn{ to{ opacity:1; } }\n\n  .crest{ width:38px; height:38px; margin:0 auto 18px; border:1px solid var(--brass); border-radius:50%; display:flex; align-items:center; justify-content:center;\n    font-family:'Playfair Display', serif; font-size:16px; color:var(--brass-bright);\n    opacity:0; transform:scale(.7); animation:crestIn .6s cubic-bezier(.34,1.4,.4,1) forwards; animation-delay:.1s; }\n  @keyframes crestIn{ to{ opacity:1; transform:scale(1); } }\n\n  .brand{ font-size:11px; letter-spacing:.24em; color:var(--brass); margin-bottom:16px;\n    opacity:0; animation:fadeUp .6s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.3s; }\n  h1{ font-family:'Playfair Display', serif; font-weight:600; font-size:25px; margin-bottom:8px;\n    opacity:0; animation:fadeUp .6s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.38s; }\n  .sub{ font-size:13px; color:var(--dim); margin-bottom:32px;\n    opacity:0; animation:fadeUp .6s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.44s; }\n  @keyframes fadeUp{ to{ opacity:1; transform:none; } }\n  h1, .sub{ transform:translateY(6px); }\n\n  .panel{ text-align:left; background:var(--card); border:1px solid var(--line); padding:36px 32px;\n    opacity:0; animation:fadeUp .7s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.5s; }\n\n  .field{ position:relative; margin-bottom:24px; }\n  .field label{ display:block; font-size:11px; letter-spacing:.04em; color:var(--dim); margin-bottom:8px; }\n  .field input{ width:100%; background:none; border:none; border-bottom:1px solid var(--line); color:var(--cream); font-size:15px; padding:9px 32px 9px 0; outline:none; transition:border-color .3s ease; }\n  .field input:focus{ border-color:var(--brass); }\n  .field input::placeholder{ color:var(--dim); opacity:.5; }\n  .eye-btn{ position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer; color:var(--dim); display:flex; }\n  .eye-btn:hover{ color:var(--brass-bright); }\n  .eye-btn svg{ width:15px; height:15px; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--dim); margin:0 0 26px; }\n  .row-between a{ color:var(--dim); text-decoration:none; border-bottom:1px solid var(--line); }\n  .row-between a:hover{ color:var(--brass-bright); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--brass); width:13px; height:13px; }\n\n  button.enter{ width:100%; background:var(--brass); border:none; color:#1c0f12; font-size:13.5px; font-weight:600; padding:13px; cursor:pointer; transition:background .25s ease, transform .1s ease; }\n  button.enter:hover{ background:var(--brass-bright); }\n  button.enter:active{ transform:scale(.99); }\n\n  .foot{ text-align:center; font-size:12px; color:var(--dim); margin-top:24px; line-height:1.6; }\n  .foot a{ color:var(--brass-bright); text-decoration:none; }\n  .foot a:hover{ text-decoration:underline; }\n</style>\n</head>\n<body>\n\n<div class=\"column c1\"></div><div class=\"column c2\"></div><div class=\"column c3\"></div><div class=\"column c4\"></div>\n\n<div class=\"stage\">\n  <div class=\"crest\">CR</div>\n  <div class=\"brand\">CONSTANTINE &amp; REEVE</div>\n  <h1>Client portal</h1>\n  <p class=\"sub\">Case documents, correspondence, and billing.</p>\n\n  <div class=\"panel\">\n    <form onsubmit=\"return false;\">\n      <div class=\"field\">\n        <label for=\"emailInput\">Email address</label>\n        <input type=\"email\" id=\"emailInput\" placeholder=\"you@company.com\" required autocomplete=\"email\" />\n      </div>\n      <div class=\"field\">\n        <label for=\"pwInput\">Password</label>\n        <input type=\"password\" id=\"pwInput\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\" required autocomplete=\"current-password\" class=\"has-eye\" />\n        <button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n      </div>\n      <div class=\"row-between\">\n        <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n        <a href=\"#\">Forgot password?</a>\n      </div>\n      <button class=\"enter\" type=\"submit\">Sign in</button>\n    </form>\n  </div>\n\n  <p class=\"foot\">Access is provisioned by your case manager.<br/><a href=\"#\">Request portal access</a></p>\n</div>\n\n<script>\n(function(){\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n    });\n  });\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--brass', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "nightjar-records", "file": "forms/nightjar-records.html", "title": "Nightjar Records", "layout": "Split Screen + Turntable", "layout_key": "split-turntable", "palette": "Indigo & Amber", "palette_key": "indigo-amber", "blurb": "A vinyl label: a tonearm lowers onto a record, which then spins continuously behind the form for as long as the page is open.", "n": 23, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Nightjar Records \u2014 Sign In</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,600;1,9..144,500&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --indigo:#0e0d16; --card:#161420; --amber:#d1934a; --amber-bright:#eab077; --line:rgba(209,147,74,0.14); --cream:#efeaf0; --dim:#847d94;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--indigo); color:var(--cream); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:grid; grid-template-columns:1fr 1fr;\n  }\n  @media(max-width:860px){ body{ grid-template-columns:1fr; } .vinyl-side{ display:none; } }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } .record{ animation:none !important; } }\n  :focus-visible{ outline:1px solid var(--amber-bright); outline-offset:2px; }\n\n  .vinyl-side{ position:relative; display:flex; align-items:center; justify-content:center; background:radial-gradient(circle at 50% 40%, #1a1826, #0e0d16); overflow:hidden; }\n  .record{ width:56%; max-width:260px; border-radius:50%; animation:spin 6s linear infinite; animation-play-state:paused; }\n  .record.playing{ animation-play-state:running; }\n  @keyframes spin{ to{ transform:rotate(360deg); } }\n  .record circle:first-child{ fill:#0a0910; }\n  .record .groove{ fill:none; stroke:rgba(209,147,74,0.12); }\n  .record .label{ fill:var(--amber); }\n  .record .hole{ fill:var(--indigo); }\n  .tonearm{ position:absolute; top:14%; right:18%; width:34%; transform-origin:90% 10%; transform:rotate(-26deg); transition:transform 1s cubic-bezier(.4,0,.2,1); }\n  .tonearm.down{ transform:rotate(0deg); }\n  .tonearm line{ stroke:var(--dim); stroke-width:2; stroke-linecap:round; }\n  .tonearm circle{ fill:var(--amber); }\n\n  .form-side{ display:flex; align-items:center; justify-content:center; padding:48px; }\n  .panel{ width:100%; max-width:360px;\n    opacity:0; transform:translateY(14px); animation:reveal .9s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.15s; }\n  @keyframes reveal{ to{ opacity:1; transform:none; } }\n\n  .brand{ font-size:11px; letter-spacing:.22em; color:var(--amber); margin-bottom:16px; }\n  h1{ font-family:'Fraunces', serif; font-style:italic; font-weight:600; font-size:28px; margin-bottom:8px; }\n  .sub{ font-size:13.5px; color:var(--dim); margin-bottom:30px; }\n\n  .tabs{ position:relative; display:flex; gap:4px; margin-bottom:28px; background:rgba(255,255,255,0.03); border-radius:999px; padding:4px; }\n  .tabs button{ position:relative; z-index:2; flex:1; background:none; border:none; color:var(--dim); font-size:12px; font-weight:600; padding:9px 0; cursor:pointer; transition:color .3s ease; border-radius:999px; }\n  .tabs button.active{ color:#0e0d16; }\n  .tab-indicator{ position:absolute; top:4px; bottom:4px; z-index:1; border-radius:999px; background:var(--amber); transition:transform .45s cubic-bezier(.65,0,.35,1), width .45s cubic-bezier(.65,0,.35,1); }\n\n  .field{ position:relative; margin-bottom:22px; }\n  .field label{ display:block; font-size:11px; letter-spacing:.04em; color:var(--dim); margin-bottom:7px; }\n  .field input{ width:100%; background:rgba(255,255,255,0.03); border:1px solid var(--line); color:var(--cream); font-size:15px; padding:10px 32px 10px 12px; border-radius:3px; outline:none; transition:border-color .2s ease; }\n  .field input:focus{ border-color:var(--amber); }\n  .field input::placeholder{ color:var(--dim); opacity:.5; }\n  .extra{ max-height:0; opacity:0; overflow:hidden; transition:max-height .5s cubic-bezier(.4,0,.2,1), opacity .35s ease; }\n  .eye-btn{ position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer; color:var(--dim); display:flex; }\n  .eye-btn:hover{ color:var(--amber-bright); }\n  .eye-btn svg{ width:15px; height:15px; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--dim); margin:0 0 26px; }\n  .row-between a{ color:var(--dim); text-decoration:none; border-bottom:1px solid var(--line); }\n  .row-between a:hover{ color:var(--amber-bright); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--amber); width:13px; height:13px; }\n\n  button.enter{ position:relative; width:100%; background:var(--amber); border:none; color:#171008; font-weight:600; font-size:13.5px; padding:13px; border-radius:3px; cursor:pointer; overflow:hidden; transition:filter .3s ease, transform .1s ease; }\n  button.enter:hover{ filter:brightness(1.1); }\n  button.enter:active{ transform:scale(.99); }\n  button.enter::after{ content:\"\"; position:absolute; top:0; left:-60%; width:40%; height:100%; background:linear-gradient(120deg, transparent, rgba(255,255,255,.35), transparent); transform:skewX(-20deg); transition:left .6s ease; }\n  button.enter:hover::after{ left:120%; }\n\n  .foot{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:22px; }\n  .foot a{ color:var(--amber-bright); text-decoration:none; cursor:pointer; }\n  .foot a:hover{ text-decoration:underline; }\n</style>\n</head>\n<body>\n\n<div class=\"vinyl-side\">\n  <svg class=\"tonearm\" id=\"tonearm\" viewBox=\"0 0 100 100\"><line x1=\"90\" y1=\"10\" x2=\"20\" y2=\"55\"/><circle cx=\"90\" cy=\"10\" r=\"5\"/><circle cx=\"20\" cy=\"55\" r=\"3\"/></svg>\n  <svg class=\"record\" id=\"record\" viewBox=\"0 0 200 200\">\n    <circle cx=\"100\" cy=\"100\" r=\"98\"/>\n    <circle class=\"groove\" cx=\"100\" cy=\"100\" r=\"88\"/><circle class=\"groove\" cx=\"100\" cy=\"100\" r=\"76\"/>\n    <circle class=\"groove\" cx=\"100\" cy=\"100\" r=\"64\"/><circle class=\"groove\" cx=\"100\" cy=\"100\" r=\"52\"/>\n    <circle class=\"label\" cx=\"100\" cy=\"100\" r=\"38\"/>\n    <circle class=\"hole\" cx=\"100\" cy=\"100\" r=\"4\"/>\n  </svg>\n</div>\n\n<div class=\"form-side\">\n  <div class=\"panel\">\n    <div class=\"brand\">NIGHTJAR RECORDS</div>\n    <h1 id=\"heading\">Sign in</h1>\n    <p class=\"sub\" id=\"subhead\">Your releases, royalties, and studio bookings.</p>\n\n    <div class=\"tabs\" id=\"tabs\">\n      <button class=\"active\" data-tab=\"signin\" type=\"button\">Sign in</button>\n      <button data-tab=\"signup\" type=\"button\">Create account</button>\n      <span class=\"tab-indicator\" id=\"tabIndicator\"></span>\n    </div>\n\n    <form onsubmit=\"return false;\">\n      <div class=\"field extra\" id=\"nameField\">\n        <label for=\"nameInput\">Full name</label>\n        <input type=\"text\" id=\"nameInput\" placeholder=\"Jordan Rivera\" autocomplete=\"name\" />\n      </div>\n      <div class=\"field\">\n        <label for=\"emailInput\">Email address</label>\n        <input type=\"email\" id=\"emailInput\" placeholder=\"you@company.com\" required autocomplete=\"email\" />\n      </div>\n      <div class=\"field\">\n        <label for=\"pwInput\">Password</label>\n        <input type=\"password\" id=\"pwInput\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\" required autocomplete=\"current-password\" class=\"has-eye\" />\n        <button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n      </div>\n      <div class=\"row-between\" id=\"signinOnlyRow\">\n        <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n        <a href=\"#\">Forgot password?</a>\n      </div>\n      <button class=\"enter\" type=\"submit\"><span id=\"submitLabel\">Sign in</span></button>\n    </form>\n\n    <p class=\"foot\" id=\"footNote\">New here? <a data-switch=\"signup\">Create an account</a></p>\n  </div>\n</div>\n\n<script>\n(function(){\n  var record = document.getElementById('record');\n  var tonearm = document.getElementById('tonearm');\n  setTimeout(function(){ tonearm.classList.add('down'); }, 400);\n  setTimeout(function(){ record.classList.add('playing'); }, 1200);\n\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n    });\n  });\n\n  var tabs = document.querySelectorAll('#tabs button[data-tab]');\n  var indicator = document.getElementById('tabIndicator');\n  var nameField = document.getElementById('nameField');\n  var signinOnlyRow = document.getElementById('signinOnlyRow');\n  var heading = document.getElementById('heading');\n  var subhead = document.getElementById('subhead');\n  var submitLabel = document.getElementById('submitLabel');\n  var footNote = document.getElementById('footNote');\n\n  var COPY = {\n    signin: { heading:'Sign in', sub:'Your releases, royalties, and studio bookings.', submit:'Sign in', foot:'New here? <a data-switch=\"signup\">Create an account</a>' },\n    signup: { heading:'Create your account', sub:'Submit demos and track your release schedule.', submit:'Create account', foot:'Already have an account? <a data-switch=\"signin\">Sign in</a>' }\n  };\n  function positionIndicator(el){ indicator.style.width = el.offsetWidth+'px'; indicator.style.transform = 'translateX('+el.offsetLeft+'px)'; }\n  function bindSwitchLinks(){ document.querySelectorAll('[data-switch]').forEach(function(a){ a.addEventListener('click', function(e){ e.preventDefault(); setMode(a.getAttribute('data-switch')); }); }); }\n  function setMode(mode){\n    tabs.forEach(function(t){ t.classList.toggle('active', t.dataset.tab===mode); if(t.dataset.tab===mode) positionIndicator(t); });\n    var showExtra = mode==='signup';\n    nameField.style.maxHeight = showExtra ? nameField.scrollHeight+'px' : '0px';\n    nameField.style.opacity = showExtra?1:0;\n    signinOnlyRow.style.display = mode==='signin' ? 'flex' : 'none';\n    heading.textContent = COPY[mode].heading;\n    subhead.textContent = COPY[mode].sub;\n    submitLabel.textContent = COPY[mode].submit;\n    footNote.innerHTML = COPY[mode].foot;\n    bindSwitchLinks();\n  }\n  tabs.forEach(function(t){ t.addEventListener('click', function(){ setMode(t.dataset.tab); }); });\n  bindSwitchLinks();\n  window.addEventListener('load', function(){ positionIndicator(document.querySelector('#tabs button.active')); });\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--amber', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "the-apiary", "file": "forms/the-apiary.html", "title": "The Apiary", "layout": "Underline Tab + Honeycomb", "layout_key": "underline-honeycomb", "palette": "Honey & Umber", "palette_key": "honey-umber", "blurb": "A beekeeping brand: a field of hexagons builds itself in behind the card, and the button blooms with a warm glow on hover.", "n": 24, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>The Apiary \u2014 Sign In</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,600&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --honeybg:#1a1209; --card:#231708; --honey:#d9a441; --honey-bright:#f0c169; --line:rgba(217,164,65,0.16); --cream:#f2e9d6; --dim:#a08a5f;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--honeybg); color:var(--cream); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:flex; align-items:center; justify-content:center; padding:60px 24px; position:relative; overflow:hidden;\n  }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n  :focus-visible{ outline:1px solid var(--honey-bright); outline-offset:2px; }\n\n  .hex-bg{ position:fixed; inset:0; display:flex; flex-wrap:wrap; align-content:center; justify-content:center; opacity:.5; pointer-events:none; z-index:0; }\n  .hex{\n    width:46px; height:26px; background:transparent; border:1px solid var(--honey); margin:2px;\n    clip-path:polygon(25% 0%, 75% 0%, 100% 50%, 75% 100%, 25% 100%, 0% 50%);\n    opacity:0; transform:scale(.5); animation:hexIn .5s cubic-bezier(.34,1.4,.4,1) forwards;\n  }\n  @keyframes hexIn{ to{ opacity:.35; transform:scale(1); } }\n\n  .stage{ position:relative; z-index:1; width:100%; max-width:380px; text-align:center; }\n\n  .brand{ font-size:11px; letter-spacing:.24em; color:var(--honey); margin-bottom:16px;\n    opacity:0; animation:fadeUp .6s cubic-bezier(.16,1,.3,1) forwards; animation-delay:1.4s; }\n  h1{ font-family:'Fraunces', serif; font-weight:600; font-size:27px; margin-bottom:8px;\n    opacity:0; animation:fadeUp .6s cubic-bezier(.16,1,.3,1) forwards; animation-delay:1.48s; }\n  .sub{ font-size:13.5px; color:var(--dim); margin-bottom:32px;\n    opacity:0; animation:fadeUp .6s cubic-bezier(.16,1,.3,1) forwards; animation-delay:1.54s; }\n  @keyframes fadeUp{ to{ opacity:1; transform:none; } }\n  h1, .sub{ transform:translateY(6px); }\n\n  .panel{ text-align:left; background:var(--card); border:1px solid var(--line); padding:36px 32px; border-radius:3px;\n    opacity:0; animation:fadeUp .7s cubic-bezier(.16,1,.3,1) forwards; animation-delay:1.6s; }\n\n  .tabs{ position:relative; display:flex; gap:24px; margin-bottom:28px; border-bottom:1px solid var(--line); }\n  .tabs button{ background:none; border:none; color:var(--dim); font-size:12.5px; font-weight:500; padding:0 0 12px; cursor:pointer; transition:color .3s ease; }\n  .tabs button.active{ color:var(--honey-bright); }\n  .tab-indicator{ position:absolute; bottom:-1px; height:1.5px; background:var(--honey-bright); box-shadow:0 0 8px var(--honey); transition:transform .5s cubic-bezier(.65,0,.35,1), width .5s cubic-bezier(.65,0,.35,1); }\n\n  .field{ position:relative; margin-bottom:24px; }\n  .field label{ position:absolute; left:0; top:11px; font-size:14px; color:var(--dim); pointer-events:none; transition:transform .3s cubic-bezier(.4,0,.2,1), font-size .3s ease, color .3s ease; transform-origin:left top; }\n  .field input{ width:100%; background:none; border:none; border-bottom:1px solid var(--line); color:var(--cream); font-size:15px; padding:10px 0; outline:none; transition:border-color .3s ease; }\n  .field input:focus{ border-color:var(--honey); }\n  .field input:focus + label, .field input:not(:placeholder-shown) + label{ transform:translateY(-19px); font-size:11px; color:var(--honey-bright); }\n  .field input::placeholder{ color:transparent; }\n  .extra{ max-height:0; opacity:0; overflow:hidden; transition:max-height .5s cubic-bezier(.4,0,.2,1), opacity .35s ease; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--dim); margin:0 0 28px; }\n  .row-between a{ color:var(--dim); text-decoration:none; border-bottom:1px solid var(--line); }\n  .row-between a:hover{ color:var(--honey-bright); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--honey); width:13px; height:13px; }\n\n  button.enter{ position:relative; width:100%; background:var(--honey); border:none; color:#231708; font-weight:600; font-size:13.5px; padding:14px; border-radius:3px; cursor:pointer;\n    box-shadow:0 0 0 0 rgba(217,164,65,0.45); transition:box-shadow .35s ease, background .3s ease, transform .1s ease; }\n  button.enter:hover{ background:var(--honey-bright); box-shadow:0 0 0 8px rgba(217,164,65,0.16), 0 0 26px 4px rgba(217,164,65,0.28); }\n  button.enter:active{ transform:scale(.99); }\n\n  .foot{ text-align:center; font-size:12.5px; color:var(--dim); margin-top:22px; }\n  .foot a{ color:var(--honey-bright); text-decoration:none; cursor:pointer; }\n  .foot a:hover{ text-decoration:underline; }\n</style>\n</head>\n<body>\n\n<div class=\"hex-bg\" id=\"hexBg\"></div>\n\n<div class=\"stage\">\n  <div class=\"brand\">THE APIARY</div>\n  <h1 id=\"heading\">Sign in</h1>\n  <p class=\"sub\" id=\"subhead\">Your hives, harvest logs, and honey orders.</p>\n\n  <div class=\"panel\">\n    <div class=\"tabs\" id=\"tabs\">\n      <button class=\"active\" data-tab=\"signin\" type=\"button\">Sign in</button>\n      <button data-tab=\"signup\" type=\"button\">Create account</button>\n      <span class=\"tab-indicator\" id=\"tabIndicator\"></span>\n    </div>\n\n    <form onsubmit=\"return false;\">\n      <div class=\"field extra\" id=\"nameField\">\n        <input type=\"text\" placeholder=\" \" id=\"nameInput\" autocomplete=\"name\" />\n        <label for=\"nameInput\">Full name</label>\n      </div>\n      <div class=\"field\">\n        <input type=\"email\" placeholder=\" \" id=\"emailInput\" required autocomplete=\"email\" />\n        <label for=\"emailInput\">Email address</label>\n      </div>\n      <div class=\"field\">\n        <input type=\"password\" placeholder=\" \" id=\"pwInput\" required autocomplete=\"current-password\" class=\"has-eye\" style=\"padding-right:34px;\" />\n        <label for=\"pwInput\">Password</label>\n        <button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\" style=\"position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer; color:var(--dim);\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" width=\"15\" height=\"15\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n      </div>\n      <div class=\"row-between\" id=\"signinOnlyRow\">\n        <label class=\"checkbox\"><input type=\"checkbox\" /> Remember me</label>\n        <a href=\"#\">Forgot password?</a>\n      </div>\n      <button class=\"enter\" type=\"submit\"><span id=\"submitLabel\">Sign in</span></button>\n    </form>\n\n    <p class=\"foot\" id=\"footNote\">New here? <a data-switch=\"signup\">Create an account</a></p>\n  </div>\n</div>\n\n<script>\n(function(){\n  var hexBg = document.getElementById('hexBg');\n  for(var i=0;i<40;i++){\n    var h = document.createElement('div');\n    h.className = 'hex';\n    h.style.animationDelay = (Math.random()*1.1).toFixed(2)+'s';\n    hexBg.appendChild(h);\n  }\n\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n    });\n  });\n\n  var tabs = document.querySelectorAll('#tabs button[data-tab]');\n  var indicator = document.getElementById('tabIndicator');\n  var nameField = document.getElementById('nameField');\n  var signinOnlyRow = document.getElementById('signinOnlyRow');\n  var heading = document.getElementById('heading');\n  var subhead = document.getElementById('subhead');\n  var submitLabel = document.getElementById('submitLabel');\n  var footNote = document.getElementById('footNote');\n\n  var COPY = {\n    signin: { heading:'Sign in', sub:'Your hives, harvest logs, and honey orders.', submit:'Sign in', foot:'New here? <a data-switch=\"signup\">Create an account</a>' },\n    signup: { heading:'Create your account', sub:'Register your apiary and start logging hives.', submit:'Create account', foot:'Already have an account? <a data-switch=\"signin\">Sign in</a>' }\n  };\n  function positionIndicator(el){ indicator.style.width = el.offsetWidth+'px'; indicator.style.transform = 'translateX('+el.offsetLeft+'px)'; }\n  function bindSwitchLinks(){ document.querySelectorAll('[data-switch]').forEach(function(a){ a.addEventListener('click', function(e){ e.preventDefault(); setMode(a.getAttribute('data-switch')); }); }); }\n  function setMode(mode){\n    tabs.forEach(function(t){ t.classList.toggle('active', t.dataset.tab===mode); if(t.dataset.tab===mode) positionIndicator(t); });\n    var showExtra = mode==='signup';\n    nameField.style.maxHeight = showExtra ? nameField.scrollHeight+'px' : '0px';\n    nameField.style.opacity = showExtra?1:0;\n    signinOnlyRow.style.display = mode==='signin' ? 'flex' : 'none';\n    heading.textContent = COPY[mode].heading;\n    subhead.textContent = COPY[mode].sub;\n    submitLabel.textContent = COPY[mode].submit;\n    footNote.innerHTML = COPY[mode].foot;\n    bindSwitchLinks();\n  }\n  tabs.forEach(function(t){ t.addEventListener('click', function(){ setMode(t.dataset.tab); }); });\n  bindSwitchLinks();\n  window.addEventListener('load', function(){ positionIndicator(document.querySelector('#tabs button.active')); });\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--honey', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}, {"id": "sterling-and-vine", "file": "forms/sterling-and-vine.html", "title": "Sterling & Vine", "layout": "Centered, Sign-In Only", "layout_key": "centered-ticker", "palette": "Sterling & Pale Gold", "palette_key": "sterling-palegold", "blurb": "A private bank: quiet market-ticker text scrolls along the top and bottom edges \u2014 invitation-only, passkey offered as an alternative.", "n": 25, "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Sterling &amp; Vine \u2014 Private Client Sign In</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,600;1,500&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --sterling:#0f1613; --card:#151f1a; --palegold:#c7b57a; --palegold-bright:#e2d59e; --line:rgba(199,181,122,0.14); --cream:#eceee9; --dim:#7f8a80;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{\n    background:var(--sterling); color:var(--cream); font-family:'Inter', sans-serif; -webkit-font-smoothing:antialiased;\n    min-height:100vh; display:flex; align-items:center; justify-content:center; padding:60px 24px; position:relative; overflow:hidden;\n  }\n  @media (prefers-reduced-motion: reduce){ *{ animation-duration:.01ms !important; transition-duration:.01ms !important; } }\n  :focus-visible{ outline:1px solid var(--palegold-bright); outline-offset:2px; }\n\n  .ticker{\n    position:fixed; top:40px; left:0; right:0; white-space:nowrap; font-family:'Inter', monospace; font-size:11px; letter-spacing:.05em;\n    color:var(--dim); opacity:.4; overflow:hidden;\n  }\n  .ticker span{ display:inline-block; padding-left:100%; animation:scroll 38s linear infinite; }\n  @keyframes scroll{ from{ transform:translateX(0); } to{ transform:translateX(-100%); } }\n  .ticker.bottom{ top:auto; bottom:40px; }\n  .ticker.bottom span{ animation-direction:reverse; }\n\n  .stage{ position:relative; z-index:1; width:100%; max-width:380px; text-align:center;\n    opacity:0; animation:fadeIn .3s ease forwards; }\n  @keyframes fadeIn{ to{ opacity:1; } }\n\n  .brand{ font-size:11px; letter-spacing:.24em; color:var(--palegold); margin-bottom:16px;\n    opacity:0; animation:fadeUp .6s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.1s; }\n  h1{ font-family:'Playfair Display', serif; font-weight:600; font-size:26px; margin-bottom:8px;\n    opacity:0; animation:fadeUp .6s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.18s; }\n  .sub{ font-size:13px; color:var(--dim); margin-bottom:32px;\n    opacity:0; animation:fadeUp .6s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.24s; }\n  @keyframes fadeUp{ to{ opacity:1; transform:none; } }\n  h1, .sub{ transform:translateY(6px); }\n\n  .panel{ text-align:left; background:var(--card); border:1px solid var(--line); padding:38px 34px;\n    opacity:0; animation:fadeUp .7s cubic-bezier(.16,1,.3,1) forwards; animation-delay:.32s; }\n\n  .field{ position:relative; margin-bottom:24px; }\n  .field label{ display:block; font-size:11px; letter-spacing:.04em; color:var(--dim); margin-bottom:8px; }\n  .field input{ width:100%; background:none; border:none; border-bottom:1px solid var(--line); color:var(--cream); font-size:15px; padding:9px 32px 9px 0; outline:none; transition:border-color .3s ease; }\n  .field input:focus{ border-color:var(--palegold); }\n  .field input::placeholder{ color:var(--dim); opacity:.5; }\n  .eye-btn{ position:absolute; right:2px; bottom:6px; background:none; border:none; padding:5px; cursor:pointer; color:var(--dim); display:flex; }\n  .eye-btn:hover{ color:var(--palegold-bright); }\n  .eye-btn svg{ width:15px; height:15px; }\n\n  .row-between{ display:flex; justify-content:space-between; font-size:12px; color:var(--dim); margin:0 0 26px; }\n  .row-between a{ color:var(--dim); text-decoration:none; border-bottom:1px solid var(--line); }\n  .row-between a:hover{ color:var(--palegold-bright); }\n  .checkbox{ display:flex; align-items:center; gap:7px; }\n  .checkbox input{ accent-color:var(--palegold); width:13px; height:13px; }\n\n  button.enter{ width:100%; background:var(--palegold); border:none; color:#0f1613; font-size:13.5px; font-weight:600; padding:13px; cursor:pointer; transition:background .25s ease, transform .1s ease; }\n  button.enter:hover{ background:var(--palegold-bright); }\n  button.enter:active{ transform:scale(.99); }\n\n  .alt{ margin-top:18px; }\n  .alt button{ width:100%; background:none; border:1px solid var(--line); color:var(--cream); font-size:12.5px; padding:10px; cursor:pointer; transition:border-color .2s ease; }\n  .alt button:hover{ border-color:var(--palegold); }\n\n  .foot{ text-align:center; font-size:12px; color:var(--dim); margin-top:26px; line-height:1.6; }\n  .foot a{ color:var(--palegold-bright); text-decoration:none; }\n  .foot a:hover{ text-decoration:underline; }\n</style>\n</head>\n<body>\n\n<div class=\"ticker\"><span>STG 412.85 \u25b20.6% &nbsp;&nbsp;&nbsp; VNE 98.12 \u25bc0.2% &nbsp;&nbsp;&nbsp; INDX 5,102.4 \u25b20.3% &nbsp;&nbsp;&nbsp; BND 101.9 \u25b20.1% &nbsp;&nbsp;&nbsp; STG 412.85 \u25b20.6%</span></div>\n<div class=\"ticker bottom\"><span>FX EUR/USD 1.084 &nbsp;&nbsp;&nbsp; GOLD 2,341 \u25b20.4% &nbsp;&nbsp;&nbsp; 10Y 4.21% &nbsp;&nbsp;&nbsp; VIX 13.2 \u25bc1.1% &nbsp;&nbsp;&nbsp; FX EUR/USD 1.084</span></div>\n\n<div class=\"stage\">\n  <div class=\"brand\">STERLING &amp; VINE</div>\n  <h1>Private client sign in</h1>\n  <p class=\"sub\">Portfolio, statements, and your relationship manager.</p>\n\n  <div class=\"panel\">\n    <form onsubmit=\"return false;\">\n      <div class=\"field\">\n        <label for=\"emailInput\">Client email</label>\n        <input type=\"email\" id=\"emailInput\" placeholder=\"you@company.com\" required autocomplete=\"email\" />\n      </div>\n      <div class=\"field\">\n        <label for=\"pwInput\">Password</label>\n        <input type=\"password\" id=\"pwInput\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022\" required autocomplete=\"current-password\" class=\"has-eye\" />\n        <button type=\"button\" class=\"eye-btn\" data-for=\"pwInput\" aria-label=\"Show password\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button>\n      </div>\n      <div class=\"row-between\">\n        <label class=\"checkbox\"><input type=\"checkbox\" /> Remember this device</label>\n        <a href=\"#\">Forgot password?</a>\n      </div>\n      <button class=\"enter\" type=\"submit\">Sign in</button>\n    </form>\n    <div class=\"alt\"><button type=\"button\">Use a passkey instead</button></div>\n  </div>\n\n  <p class=\"foot\">Private banking is by invitation.<br/><a href=\"#\">Speak with a relationship manager</a></p>\n</div>\n\n<script>\n(function(){\n  document.querySelectorAll('.eye-btn').forEach(function(btn){\n    var input = document.getElementById(btn.dataset.for);\n    var showing = false;\n    btn.addEventListener('click', function(){\n      showing = !showing;\n      input.type = showing ? 'text' : 'password';\n      btn.setAttribute('aria-pressed', showing ? 'true' : 'false');\n      btn.setAttribute('aria-label', showing ? 'Hide password' : 'Show password');\n    });\n  });\n  window.addEventListener('message', function(e){ if(e.data && e.data.type==='loginkit-accent'){ document.documentElement.style.setProperty('--palegold', e.data.color); } });\n})();\n</script>\n\n</body>\n</html>\n"}];
